def subject_exam_max_raw_marks(exam_total_marks_value):
    """Positive maximum raw marks for exam entry; default 100 when unset, zero, or invalid."""
    try:
        v = float(exam_total_marks_value)
        if v > 0:
            return v
    except (TypeError, ValueError):
        pass
    return 100.0


def raw_mark_to_percentage(raw_marks, exam_total_marks_value):
    """Scale raw marks to a 0–100 percentage using the subject's exam total (default 100)."""
    mx = subject_exam_max_raw_marks(exam_total_marks_value)
    if raw_marks is None:
        return None
    try:
        r = float(raw_marks)
    except (TypeError, ValueError):
        return None
    if mx <= 0:
        return None
    return round(100.0 * r / mx, 2)


def round_mark_display(value):
    """Whole-number rounding for scaled marks, means, and totals shown on reports."""
    if value is None or value == '':
        return None
    try:
        return int(round(float(value)))
    except (TypeError, ValueError):
        return None


def pct_value_for_grade_band_match(marks_value):
    """Map a percentage to the integer scale used by grade_registrations start/end bands."""
    try:
        return int(math.floor(float(marks_value) + 1e-9))
    except (TypeError, ValueError):
        return None


def match_grade_band(marks_value, bands):
    """Return the first band whose [start, end] contains the floored percentage, or None."""
    mv = pct_value_for_grade_band_match(marks_value)
    if mv is None:
        return None
    for band in bands or []:
        try:
            start = float(band.get('start', 0))
            end = float(band.get('end', 0))
        except (TypeError, ValueError):
            continue
        if mv >= start and mv <= end:
            return band
    return None


def subject_display_label(subject_code=None, subject_name=None, fallback='SUBJECT'):
    """Prefer subject_code for marks sheets, reports, and timetables; fall back to name."""
    code = str(subject_code or '').strip()
    if code:
        return code
    name = str(subject_name or '').strip()
    if name and name.upper() not in ('N/A', '-'):
        return name
    if name:
        return name
    return fallback


def grade_code_and_points_from_pct(marks_value, bands):
    """Return (code, points) for a percentage using Grades Registration bands."""
    band = match_grade_band(marks_value, bands)
    if not band:
        return '', None
    code = (band.get('code') or band.get('label') or '').strip()
    points = None
    ap = band.get('allocation_points')
    if ap is not None and ap != '':
        try:
            f = float(ap)
            points = int(round(f)) if abs(f - round(f)) < 1e-9 else round(f, 2)
        except (TypeError, ValueError):
            points = None
    return code, points


def load_grade_bands_from_db(cursor):
    """Load default and per-subject grade bands (marks sheet / reports)."""
    default_grade_bands = []
    subject_grade_bands = {}
    try:
        cursor.execute("""
            SELECT code, level_label, start_mark, end_mark, allocation_points
            FROM grade_registrations
            WHERE start_mark IS NOT NULL AND end_mark IS NOT NULL
            ORDER BY start_mark DESC, end_mark DESC
        """)
        for grow in (cursor.fetchall() or []):
            if isinstance(grow, dict):
                ap = grow.get('allocation_points')
                default_grade_bands.append({
                    'code': (grow.get('code') or '').strip(),
                    'label': (grow.get('level_label') or '').strip(),
                    'start': float(grow.get('start_mark') or 0),
                    'end': float(grow.get('end_mark') or 0),
                    'allocation_points': float(ap) if ap is not None else None,
                })
            else:
                apv = grow[4] if len(grow) > 4 else None
                default_grade_bands.append({
                    'code': ((grow[0] if len(grow) > 0 else '') or '').strip(),
                    'label': ((grow[1] if len(grow) > 1 else '') or '').strip(),
                    'start': float(grow[2] or 0) if len(grow) > 2 else 0.0,
                    'end': float(grow[3] or 0) if len(grow) > 3 else 0.0,
                    'allocation_points': float(apv) if apv is not None else None,
                })
    except Exception as ge:
        print(f"Note: grade_registrations lookup skipped: {ge}")
    try:
        cursor.execute("""
            SELECT subject_id, code, start_mark, end_mark, allocation_points
            FROM subject_grade_mark_overrides
            WHERE start_mark IS NOT NULL AND end_mark IS NOT NULL
            ORDER BY subject_id ASC, start_mark DESC, end_mark DESC
        """)
        for srow in (cursor.fetchall() or []):
            if isinstance(srow, dict):
                sid = int(srow.get('subject_id') or 0)
                ap = srow.get('allocation_points')
                band = {
                    'code': (srow.get('code') or '').strip(),
                    'label': '',
                    'start': float(srow.get('start_mark') or 0),
                    'end': float(srow.get('end_mark') or 0),
                    'allocation_points': float(ap) if ap is not None else None,
                }
            else:
                sid = int(srow[0] or 0) if len(srow) > 0 else 0
                apv = srow[4] if len(srow) > 4 else None
                band = {
                    'code': ((srow[1] if len(srow) > 1 else '') or '').strip(),
                    'label': '',
                    'start': float(srow[2] or 0) if len(srow) > 2 else 0.0,
                    'end': float(srow[3] or 0) if len(srow) > 3 else 0.0,
                    'allocation_points': float(apv) if apv is not None else None,
                }
            if sid <= 0:
                continue
            subject_grade_bands.setdefault(sid, []).append(band)
    except Exception as se:
        print(f"Note: subject_grade_mark_overrides lookup skipped: {se}")
    return default_grade_bands, subject_grade_bands


def sql_scaled_exam_mark_pct(sm_alias='sm', sub_alias='sub'):
    """SQL expression: student_marks.marks as 0–100 % using subjects.exam_total_marks."""
    return (
        f"(100 * CAST({sm_alias}.marks AS DECIMAL(16,8))) "
        f"/ COALESCE(NULLIF({sub_alias}.exam_total_marks, 0), 100)"
    )


def ensure_subject_exam_combination_tables(cursor):
    """Groups of subjects shown as one marks column (combined label); marks stored per member subject."""
    try:
        cursor.execute("SHOW TABLES LIKE 'subject_exam_combinations'")
        if not cursor.fetchone():
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS subject_exam_combinations (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            print("OK: Created subject_exam_combinations table")
        cursor.execute("SHOW TABLES LIKE 'subject_exam_combination_members'")
        if not cursor.fetchone():
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS subject_exam_combination_members (
                    combination_id INT NOT NULL,
                    subject_id INT NOT NULL,
                    sort_order INT NOT NULL DEFAULT 0,
                    PRIMARY KEY (combination_id, subject_id),
                    INDEX idx_subject_exam_combo_member_subject (subject_id)
                )
            """)
            print("OK: Created subject_exam_combination_members table")
        try:
            cursor.execute("SHOW COLUMNS FROM subject_exam_combinations LIKE 'totals_snapshot_json'")
            if not cursor.fetchone():
                cursor.execute(
                    """
                    ALTER TABLE subject_exam_combinations
                    ADD COLUMN totals_snapshot_json TEXT NULL
                    COMMENT 'JSON snapshot of subjects.exam_total_marks before proportional rescale to sum 100'
                    AFTER created_at
                    """
                )
                print("OK: Added subject_exam_combinations.totals_snapshot_json")
        except Exception as e:
            print(f"ensure_subject_exam_combination_tables (totals_snapshot_json): {e}")
    except Exception as e:
        print(f"ensure_subject_exam_combination_tables: {e}")


def _exam_total_marks_snapshot_value(db_val):
    """JSON-safe prior exam_total_marks for restore (NULL stays None)."""
    if db_val is None:
        return None
    try:
        return round(float(db_val), 2)
    except (TypeError, ValueError):
        return None


def normalize_subject_totals_for_exam_combination(cursor, subject_ids_ordered):
    """
    Rescale subjects.exam_total_marks proportionally so effective maxima sum to 100.
    Returns a list suitable for json.dumps into totals_snapshot_json (restore on combination delete).
    """
    if not subject_ids_ordered or len(subject_ids_ordered) < 2:
        return []
    placeholders = ','.join(['%s'] * len(subject_ids_ordered))
    cursor.execute(
        f"SELECT id, exam_total_marks FROM subjects WHERE id IN ({placeholders})",
        tuple(subject_ids_ordered),
    )
    rows = cursor.fetchall() or []
    by_id = {}
    for r in rows:
        sid = r.get('id') if isinstance(r, dict) else r[0]
        etm = r.get('exam_total_marks') if isinstance(r, dict) else r[1]
        by_id[int(sid)] = etm

    snapshot = []
    weights = []
    for sid in subject_ids_ordered:
        sid = int(sid)
        etm_before = by_id.get(sid)
        snapshot.append({
            'subject_id': sid,
            'exam_total_marks': _exam_total_marks_snapshot_value(etm_before),
        })
        weights.append(subject_exam_max_raw_marks(etm_before))

    total_w = sum(weights)
    n = len(subject_ids_ordered)
    if total_w <= 0:
        equal = round(100.0 / n, 2)
        floored = [equal] * n
        diff = round(100.0 - sum(floored), 2)
        floored[-1] = round(floored[-1] + diff, 2)
    else:
        precise = [100.0 * w / total_w for w in weights]
        floored = [round(x, 2) for x in precise]
        diff = round(100.0 - sum(floored), 2)
        floored[-1] = round(floored[-1] + diff, 2)

    for sid, new_max in zip(subject_ids_ordered, floored):
        cursor.execute(
            "UPDATE subjects SET exam_total_marks = %s WHERE id = %s",
            (new_max, int(sid)),
        )
    return snapshot


def restore_subject_totals_from_combination_snapshot(cursor, snapshot_json_str):
    """Apply stored exam_total_marks per subject; ignores invalid entries."""
    if not snapshot_json_str:
        return
    try:
        entries = json.loads(snapshot_json_str)
    except (TypeError, ValueError, json.JSONDecodeError) as e:
        print(f"restore_subject_totals_from_combination_snapshot: bad JSON: {e}")
        return
    if not isinstance(entries, list):
        return
    for ent in entries:
        if not isinstance(ent, dict):
            continue
        sid = ent.get('subject_id')
        if sid is None:
            continue
        try:
            sid = int(sid)
        except (TypeError, ValueError):
            continue
        etm = ent.get('exam_total_marks')
        if etm is None:
            cursor.execute(
                "UPDATE subjects SET exam_total_marks = NULL WHERE id = %s",
                (sid,),
            )
        else:
            try:
                cursor.execute(
                    "UPDATE subjects SET exam_total_marks = %s WHERE id = %s",
                    (round(float(etm), 2), sid),
                )
            except (TypeError, ValueError):
                cursor.execute(
                    "UPDATE subjects SET exam_total_marks = NULL WHERE id = %s",
                    (sid,),
                )


def fetch_subject_exam_combinations(cursor):
    """Return [{'id': combo_id, 'member_subject_ids': [..ordered..], 'display_order': int|None}, ...]."""
    ensure_subject_exam_combination_tables(cursor)
    ensure_subject_exam_display_order_columns(cursor)
    cursor.execute(
        """
        SELECT m.combination_id, m.subject_id, m.sort_order, c.display_order
        FROM subject_exam_combination_members m
        INNER JOIN subject_exam_combinations c ON c.id = m.combination_id
        ORDER BY COALESCE(c.display_order, c.id) ASC, c.id ASC, m.sort_order ASC, m.subject_id ASC
        """
    )
    grouped = {}
    disp = {}
    for row in cursor.fetchall() or []:
        cid = row.get('combination_id') if isinstance(row, dict) else row[0]
        sid = row.get('subject_id') if isinstance(row, dict) else row[1]
        dord = row.get('display_order') if isinstance(row, dict) else (row[3] if len(row) > 3 else None)
        if cid is None or sid is None:
            continue
        cid = int(cid)
        sid = int(sid)
        grouped.setdefault(cid, []).append(sid)
        if dord is not None:
            try:
                disp[cid] = int(dord)
            except (TypeError, ValueError):
                pass
    def _combo_key(item):
        cid, mids = item
        return (disp.get(cid) if cid in disp else 10**9 + cid, cid)

    return [
        {'id': cid, 'member_subject_ids': mids, 'display_order': disp.get(cid)}
        for cid, mids in sorted(grouped.items(), key=_combo_key)
    ]


def merge_subjects_with_exam_combinations(subjects, combinations, id_to_gc=None, section_order=None):
    """
    Replace member subjects with one synthetic column per applicable combination.
    Synthetic row uses negative id -combo_id, exam_total_marks 100 (enter unified %); names/codes joined with '/'.
    When id_to_gc and section_order are provided (same semantics as exam-subject-settings), subjects are ordered
    by academic category first, then exam_display_order.
    """
    if not subjects:
        return subjects
    if not combinations:
        return subjects

    def _sub_sort_key(s):
        sid = int(s['id'])
        eo = s.get('exam_display_order')
        try:
            eo_n = int(eo)
        except (TypeError, ValueError):
            eo_n = None
        if eo_n is None:
            return (1, 10**9 + sid, str(s.get('subject_name') or '').lower(), sid)
        return (0, eo_n, str(s.get('subject_name') or '').lower(), sid)

    if id_to_gc is not None and section_order is not None:
        def _cat_key(s):
            sc = dict(s)
            try:
                sid = int(sc['id'])
                if sid > 0:
                    sc.setdefault('group_category', id_to_gc.get(sid, 'Uncategorized'))
            except (TypeError, ValueError, KeyError):
                sc.setdefault('group_category', 'Uncategorized')
            return exam_subject_column_sort_key(sc, section_order)

        subjects = sorted((dict(s) for s in subjects), key=_cat_key)
    else:
        subjects = sorted((dict(s) for s in subjects), key=_sub_sort_key)
    by_id = {int(s['id']): dict(s) for s in subjects}
    original_order = [int(s['id']) for s in subjects]
    id_set = set(original_order)
    subject_to_combo = {}
    combo_members_by_id = {}
    for c in combinations:
        mids = [int(x) for x in (c.get('member_subject_ids') or [])]
        if len(mids) < 2:
            continue
        if not all(m in id_set for m in mids):
            continue
        cid = int(c['id'])
        combo_members_by_id[cid] = mids
        conflict = False
        for mid in mids:
            if mid in subject_to_combo:
                conflict = True
                break
        if conflict:
            continue
        for mid in mids:
            subject_to_combo[mid] = cid

    sep = '/'
    out = []
    consumed = set()
    for sid in original_order:
        if sid in consumed:
            continue
        if sid not in subject_to_combo:
            out.append(by_id[sid])
            continue
        cid = subject_to_combo[sid]
        mids = combo_members_by_id.get(cid)
        if not mids:
            out.append(by_id[sid])
            continue
        anchor = min(mids, key=lambda m: original_order.index(m))
        if sid != anchor:
            continue
        names = sep.join((by_id[mid].get('subject_name') or '').strip() or '—' for mid in mids)
        code_parts = []
        for mid in mids:
            cd = (by_id[mid].get('subject_code') or '').strip()
            code_parts.append(cd if cd else ((by_id[mid].get('subject_name') or '')[:12] or '—'))
        combo_ord_vals = []
        for mid in mids:
            eo_m = by_id.get(mid, {}).get('exam_display_order')
            try:
                combo_ord_vals.append(int(eo_m))
            except (TypeError, ValueError):
                combo_ord_vals.append(10**9 + int(mid))
        combo_row = {
            'id': -cid,
            'subject_name': names,
            'subject_code': sep.join(code_parts),
            'description': '',
            'status': 'active',
            'exam_total_marks': 100.0,
            'combination_id': cid,
            'member_subject_ids': list(mids),
            'exam_display_order': min(combo_ord_vals) if combo_ord_vals else (10**9 + cid),
        }
        if id_to_gc is not None and section_order is not None:
            combo_row['group_category'] = _combo_exam_group_category(mids, id_to_gc, section_order)
        out.append(combo_row)
        for mid in mids:
            consumed.add(mid)
    return out


def fetch_base_academic_level_category_order(cursor):
    """Ordered list of distinct level_category values (same ordering intent as exam-subject-settings)."""
    base_category_order = []
    try:
        cursor.execute(
            """
            SELECT DISTINCT al.level_category AS lc
            FROM academic_levels al
            WHERE COALESCE(al.level_status, 'active') = 'active'
              AND TRIM(COALESCE(al.level_category, '')) <> ''
            ORDER BY al.level_category ASC
            """
        )
        for cr in cursor.fetchall() or []:
            lc = cr.get('lc') if isinstance(cr, dict) else cr[0]
            if lc and str(lc).strip():
                base_category_order.append(str(lc).strip())
    except Exception:
        base_category_order = []
    return base_category_order


def build_exam_subject_section_order(keys_set, base_category_order):
    """Order category *tabs* like exam-subject-settings: known school order first, then alpha, Uncategorized last."""
    keys_set = set(keys_set or [])
    section_order = [k for k in (base_category_order or []) if k in keys_set]
    section_order.extend(
        sorted(k for k in keys_set if k not in section_order and k != 'Uncategorized')
    )
    if 'Uncategorized' in keys_set:
        section_order.append('Uncategorized')
    return section_order


def fetch_subject_id_to_exam_group_category(cursor, subject_ids):
    """Map subject id -> group_category using the same rules as exam_subject_settings."""
    subject_ids = []
    seen = set()
    for x in subject_ids or []:
        try:
            sid = int(x)
        except (TypeError, ValueError):
            continue
        if sid > 0 and sid not in seen:
            seen.add(sid)
            subject_ids.append(sid)
    if not subject_ids:
        return {}
    base_category_order = fetch_base_academic_level_category_order(cursor)
    placeholders = ','.join(['%s'] * len(subject_ids))
    cursor.execute(
        f"""
        SELECT s.id,
               GROUP_CONCAT(DISTINCT al.level_category ORDER BY al.level_category SEPARATOR '|') AS cat_blob
        FROM subjects s
        LEFT JOIN subject_academic_levels sal ON sal.subject_id = s.id
        LEFT JOIN academic_levels al ON al.id = sal.academic_level_id
            AND COALESCE(al.level_status, 'active') = 'active'
        WHERE s.id IN ({placeholders})
        GROUP BY s.id
        """,
        tuple(subject_ids),
    )
    id_to_gc = {}
    for row in cursor.fetchall() or []:
        sid = int(row.get('id') if isinstance(row, dict) else row[0])
        cat_blob = row.get('cat_blob') if isinstance(row, dict) else (row[1] if len(row) > 1 else '')
        seen_c = set()
        level_categories = []
        for part in str(cat_blob or '').split('|'):
            c = part.strip()
            if c and c not in seen_c:
                seen_c.add(c)
                level_categories.append(c)
        assigned = None
        for c in base_category_order:
            if c in seen_c:
                assigned = c
                break
        if assigned is None:
            if level_categories:
                assigned = sorted(level_categories)[0]
            else:
                assigned = 'Uncategorized'
        id_to_gc[sid] = assigned
    return id_to_gc


def exam_subject_column_sort_key(subject_row, section_order):
    """Sort tuple: category section, exam_display_order, name, id (matches marks sheet / reports)."""
    gc = (subject_row or {}).get('group_category') or 'Uncategorized'
    try:
        cat_i = section_order.index(gc)
    except ValueError:
        cat_i = len(section_order)
    eo = (subject_row or {}).get('exam_display_order')
    try:
        eo_n = int(eo)
    except (TypeError, ValueError):
        eo_n = 1000000000
    try:
        sid = int((subject_row or {}).get('id'))
    except (TypeError, ValueError):
        sid = 0
    name = str((subject_row or {}).get('subject_name') or '').lower()
    return (cat_i, eo_n, name, sid)


def sort_subjects_list_for_exam_columns(cursor, subjects):
    """
    Mutates subjects (each dict must have 'id'): sets group_category, sorts by
    exam-subject-settings category order then exam_display_order.
    Returns (id_to_gc, section_order).
    """
    if not subjects:
        return {}, []
    id_to_gc = fetch_subject_id_to_exam_group_category(cursor, [s.get('id') for s in subjects])
    base = fetch_base_academic_level_category_order(cursor)
    section_order = build_exam_subject_section_order(set(id_to_gc.values()) or {'Uncategorized'}, base)
    for s in subjects:
        try:
            sid = int(s.get('id'))
            if sid > 0:
                s['group_category'] = id_to_gc.get(sid, 'Uncategorized')
        except (TypeError, ValueError):
            s['group_category'] = 'Uncategorized'
    subjects.sort(key=lambda s: exam_subject_column_sort_key(s, section_order))
    return id_to_gc, section_order


def _combo_exam_group_category(member_ids, id_to_gc, section_order):
    """Pick one representative category for a combined exam column (earliest section wins)."""
    best_gc = 'Uncategorized'
    best_i = len(section_order) + 1
    for mid in member_ids or []:
        try:
            mid_i = int(mid)
        except (TypeError, ValueError):
            continue
        gc = id_to_gc.get(mid_i, 'Uncategorized')
        try:
            ci = section_order.index(gc)
        except ValueError:
            ci = len(section_order)
        if ci < best_i:
            best_i = ci
            best_gc = gc
    return best_gc


def _build_exam_column_order_slots(name_map, combinations_raw, base_category_order=None):
    """Flat list for UI: standalone subjects + combined groups (one row per combination)."""
    member_set = set()
    for c in combinations_raw or []:
        for mid in c.get('member_subject_ids') or []:
            try:
                member_set.add(int(mid))
            except (TypeError, ValueError):
                continue
    gcs = set()
    for sid, info in (name_map or {}).items():
        try:
            int(sid)
        except (TypeError, ValueError):
            continue
        gcs.add((info or {}).get('group_category') or 'Uncategorized')
    for c in combinations_raw or []:
        for mid in c.get('member_subject_ids') or []:
            inf = name_map.get(int(mid)) if mid is not None else None
            gcs.add((inf or {}).get('group_category') or 'Uncategorized')
    section_order = build_exam_subject_section_order(gcs, base_category_order or [])

    slots = []
    for sid, info in name_map.items():
        sid = int(sid)
        if sid in member_set:
            continue
        eo = info.get('exam_display_order')
        try:
            o = int(eo)
        except (TypeError, ValueError):
            o = 10**9 + sid
        gc = info.get('group_category') or 'Uncategorized'
        try:
            cat_i = section_order.index(gc)
        except ValueError:
            cat_i = len(section_order)
        slots.append(
            {
                'type': 'subject',
                'id': sid,
                'label': (info.get('subject_name') or '').strip() or '—',
                '_ord': o,
                '_cat_i': cat_i,
            }
        )
    for c in combinations_raw or []:
        mids = c.get('member_subject_ids') or []
        if len(mids) < 2:
            continue
        try:
            cid = int(c['id'])
        except (TypeError, ValueError):
            continue
        label_parts = []
        for mid in mids:
            inf = name_map.get(int(mid))
            label_parts.append((inf.get('subject_name') or '').strip() or '—' if inf else '—')
        label = '/'.join(label_parts)
        dord = c.get('display_order')
        try:
            o = int(dord) if dord is not None else None
        except (TypeError, ValueError):
            o = None
        if o is None:
            ovals = []
            for mid in mids:
                inf = name_map.get(int(mid))
                ev = inf.get('exam_display_order') if inf else None
                try:
                    ovals.append(int(ev))
                except (TypeError, ValueError):
                    ovals.append(10**9 + int(mid))
            o = min(ovals) if ovals else 10**9 + cid
        id_gc = {int(mid): (name_map.get(int(mid)) or {}).get('group_category') or 'Uncategorized' for mid in mids}
        combo_gc = _combo_exam_group_category(mids, id_gc, section_order)
        try:
            cat_i = section_order.index(combo_gc)
        except ValueError:
            cat_i = len(section_order)
        slots.append({'type': 'combo', 'id': cid, 'label': label, '_ord': o, '_cat_i': cat_i})
    slots.sort(key=lambda z: (z['_cat_i'], z['_ord'], str(z.get('label') or '').lower()))
    for s in slots:
        s.pop('_ord', None)
        cat_i = s.pop('_cat_i', None)
        s['group_category'] = section_order[cat_i] if cat_i is not None and 0 <= cat_i < len(section_order) else 'Uncategorized'
        if s.get('type') == 'subject':
            inf = name_map.get(int(s.get('id') or 0)) or {}
            s['level_categories'] = list(inf.get('level_categories') or [])
        elif s.get('type') == 'combo':
            cid = s.get('id')
            combo = next((c for c in (combinations_raw or []) if int(c.get('id') or 0) == int(cid or 0)), None)
            lc_seen = []
            for mid in (combo.get('member_subject_ids') if combo else []) or []:
                inf = name_map.get(int(mid)) or {}
                for lc in inf.get('level_categories') or []:
                    if lc and lc not in lc_seen:
                        lc_seen.append(lc)
            s['level_categories'] = lc_seen
    return slots


def _build_exam_column_order_by_category(name_map, combinations_raw, base_category_order=None):
    """Column-order UI sections grouped by academic level category (Primary, JSS, etc.)."""
    slots = _build_exam_column_order_slots(name_map, combinations_raw, base_category_order)
    if not slots:
        return []
    by_cat = defaultdict(list)
    for slot in slots:
        gc = (slot.get('group_category') or 'Uncategorized').strip() or 'Uncategorized'
        by_cat[gc].append(slot)
    section_order = build_exam_subject_section_order(set(by_cat.keys()), base_category_order or [])
    return [{'category': cat, 'slots': by_cat[cat]} for cat in section_order if by_cat.get(cat)]


def ensure_exams_marks_lock_at_column(cursor):
    """Adds marks_lock_at (optional deadline after which teachers may not change marks)."""
    try:
        cursor.execute("ALTER TABLE exams ADD COLUMN marks_lock_at DATETIME NULL")
    except Exception as e:
        msg = str(e).lower()
        if 'duplicate column' not in msg and 'already exists' not in msg:
            print(f"Note: exams.marks_lock_at column: {e}")


def _exam_group_max_is_locked_and_marks_lock_at(cursor, exam_id):
    """
    Allocation lock and marks-entry deadline are shared across all subject rows
    for the same level + exam_name + academic_year_id + term_id.
    Returns (max_is_locked: int 0|1, marks_lock_at: datetime|None).
    """
    cursor.execute("""
        SELECT academic_level_id, exam_name, academic_year_id, term_id
        FROM exams WHERE id = %s LIMIT 1
    """, (exam_id,))
    g = cursor.fetchone()
    if not g:
        return 0, None
    if isinstance(g, dict):
        lvl = g.get('academic_level_id')
        name = (g.get('exam_name') or '').strip()
        ay = g.get('academic_year_id')
        term = g.get('term_id')
    else:
        lvl, name, ay, term = g[0], (g[1] or '').strip(), g[2], g[3]
    if not name or ay is None or term is None:
        return 0, None
    cursor.execute("""
        SELECT MAX(COALESCE(is_locked, 0)) AS mx, MAX(marks_lock_at) AS mla
        FROM exams
        WHERE academic_level_id = %s AND exam_name = %s AND academic_year_id = %s AND term_id = %s
    """, (lvl, name, ay, term))
    r = cursor.fetchone()
    if not r:
        return 0, None
    if isinstance(r, dict):
        mx = int(r.get('mx') or 0)
        mla = r.get('mla')
    else:
        mx = int(r[0] or 0)
        mla = r[1] if len(r) > 1 else None
    return (1 if mx else 0), mla


def _marks_lock_deadline_passed(marks_lock_at):
    if not marks_lock_at:
        return False
    try:
        now = datetime.now()
        dt = marks_lock_at
        if isinstance(dt, date_cls) and not isinstance(dt, datetime):
            dt = datetime.combine(dt, datetime.min.time())
        if getattr(dt, 'tzinfo', None) is not None and dt.tzinfo is not None:
            dt = dt.replace(tzinfo=None)
        return dt <= now
    except Exception:
        return False


def ensure_registered_current_exam_column(cursor):
    try:
        cursor.execute(
            "ALTER TABLE school_settings ADD COLUMN registered_current_exam_json TEXT NULL "
            "COMMENT 'JSON: exam_name, academic_year_id, term_id for school-wide current exam'"
        )
    except Exception as e:
        msg = str(e).lower()
        if 'duplicate' not in msg and 'already exists' not in msg:
            print(f"ensure_registered_current_exam_column: {e}")


def load_registered_current_exam_dict(cursor):
    """Returns dict exam_name (upper), exam_type (upper str or None if legacy JSON), academic_year_id, term_id or None."""
    try:
        ensure_registered_current_exam_column(cursor)
        cursor.execute(
            "SELECT registered_current_exam_json FROM school_settings ORDER BY id DESC LIMIT 1"
        )
        row = cursor.fetchone()
        if not row:
            return None
        raw = row.get('registered_current_exam_json') if isinstance(row, dict) else (row[0] if row else None)
        if raw is None or (isinstance(raw, str) and not str(raw).strip()):
            return None
        j = json.loads(raw) if isinstance(raw, str) else raw
        if not isinstance(j, dict):
            return None
        name = (j.get('exam_name') or '').strip().upper()
        try:
            ay = int(j.get('academic_year_id') or 0)
            tid = int(j.get('term_id') or 0)
        except (TypeError, ValueError):
            return None
        if not name or ay <= 0 or tid <= 0:
            return None
        out = {'exam_name': name, 'academic_year_id': ay, 'term_id': tid}
        if 'exam_type' in j:
            out['exam_type'] = (j.get('exam_type') or '').strip().upper()
        else:
            out['exam_type'] = None
        return out
    except Exception as e:
        print(f"load_registered_current_exam_dict: {e}")
        return None


def apply_marks_lock_deadline_auto_lock(cursor):
    """
    When marks_lock_at is in the past, set allocation lock so the exam row matches
    the closed marks window (coordinators can still unlock manually if needed).
    """
    try:
        ensure_exams_marks_lock_at_column(cursor)
        cursor.execute("""
            UPDATE exams
            SET is_locked = 1,
                locked_at = CURRENT_TIMESTAMP
            WHERE marks_lock_at IS NOT NULL
              AND marks_lock_at <= NOW()
              AND COALESCE(is_locked, 0) = 0
        """)
    except Exception as e:
        print(f"apply_marks_lock_deadline_auto_lock: {e}")


def _default_exam_session_presets():
    return {
        'MORNING': ('08:00:00', '11:00:00'),
        'MIDDAY': ('11:30:00', '13:30:00'),
        'AFTERNOON': ('14:00:00', '16:00:00'),
        'EVENING': ('17:00:00', '19:00:00'),
    }


def _parse_exam_session_settings_json(raw_json: str):
    """
    Returns dict like { 'MORNING': ('08:00:00','11:00:00'), ... }.
    Falls back to defaults on any validation failure.
    """
    import json
    presets = _default_exam_session_presets()
    if not raw_json:
        return presets
    try:
        data = json.loads(raw_json)
        if not isinstance(data, dict):
            return presets
    except Exception:
        return presets

    def _norm_hm(s):
        s = (s or '').strip()
        parts = s.split(':')
        if len(parts) < 2:
            return None
        try:
            h = int(parts[0]); m = int(parts[1])
        except Exception:
            return None
        if h < 0 or h > 23 or m < 0 or m > 59:
            return None
        return f"{h:02d}:{m:02d}:00"

    def _to_minutes(hms):
        if not hms:
            return None
        parts = str(hms).split(':')
        if len(parts) < 2:
            return None
        try:
            return int(parts[0]) * 60 + int(parts[1])
        except Exception:
            return None

    def _from_minutes(total_minutes):
        total_minutes = total_minutes % (24 * 60)
        return f"{total_minutes // 60:02d}:{total_minutes % 60:02d}:00"

    for key in ['MORNING', 'MIDDAY', 'AFTERNOON', 'EVENING']:
        row = data.get(key)
        if not isinstance(row, dict):
            continue
        st = _norm_hm(row.get('start') or row.get('start_time') or '')
        try:
            dur = int(row.get('duration_minutes', 0) or 0)
        except Exception:
            dur = 0
        if not st or dur <= 0:
            continue
        sm = _to_minutes(st)
        if sm is None:
            continue
        presets[key] = (st, _from_minutes(sm + dur))

    return presets


def _load_exam_session_presets_from_db(cursor):
    """Load session presets from latest school_settings row (or defaults)."""
    presets = _default_exam_session_presets()
    try:
        cursor.execute("SHOW COLUMNS FROM school_settings LIKE 'exam_session_settings'")
        if not cursor.fetchone():
            return presets
        cursor.execute("SELECT exam_session_settings FROM school_settings ORDER BY id DESC LIMIT 1")
        row = cursor.fetchone()
        raw = None
        if row:
            raw = row.get('exam_session_settings') if isinstance(row, dict) else row[0]
        return _parse_exam_session_settings_json(raw or '')
    except Exception:
        return presets


def ensure_student_marks_foreign_keys(cursor):
    """
    Add InnoDB foreign keys to student_marks if possible.

    Inline FKs on CREATE TABLE often fail with errno 150 on shared hosting when parent
    tables are not InnoDB or when VARCHAR charset/collation does not match exactly.
    Creating the table first (indexes + unique only) then ALTER ... ADD CONSTRAINT
    avoids blocking init_db; constraints are applied when the server allows them.
    """
    cursor.execute("SHOW TABLES LIKE 'student_marks'")
    if not cursor.fetchone():
        return
    alters = [
        (
            "fk_student_marks_student",
            """
            ALTER TABLE student_marks
            ADD CONSTRAINT fk_student_marks_student
            FOREIGN KEY (student_id) REFERENCES students(student_id) ON DELETE CASCADE
            """,
        ),
        (
            "fk_student_marks_subject",
            """
            ALTER TABLE student_marks
            ADD CONSTRAINT fk_student_marks_subject
            FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE
            """,
        ),
        (
            "fk_student_marks_exam",
            """
            ALTER TABLE student_marks
            ADD CONSTRAINT fk_student_marks_exam
            FOREIGN KEY (exam_id) REFERENCES exams(id) ON DELETE CASCADE
            """,
        ),
    ]
    for constraint_name, sql in alters:
        try:
            cursor.execute(
                """
                SELECT 1 FROM information_schema.TABLE_CONSTRAINTS
                WHERE TABLE_SCHEMA = DATABASE()
                  AND TABLE_NAME = 'student_marks'
                  AND CONSTRAINT_NAME = %s
                LIMIT 1
                """,
                (constraint_name,),
            )
            if cursor.fetchone():
                continue
            cursor.execute(sql)
            print(f"OK: Added constraint {constraint_name} on student_marks")
        except Exception as e:
            print(f"Migration note (student_marks {constraint_name}): {e}")


_library_books_schema_ensuring = False


def ensure_library_books_table(cursor):
    """Librarian catalog: titles with book category, academic category (level_category), subject, buying price."""
    global _library_books_schema_ensuring
    if _library_books_schema_ensuring:
        return
    _library_books_schema_ensuring = True
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS library_books (
                id INT AUTO_INCREMENT PRIMARY KEY,
                book_category VARCHAR(120) NOT NULL,
                book_name VARCHAR(255) NOT NULL,
                description TEXT,
                buying_price DECIMAL(12,2) NOT NULL DEFAULT 0.00,
                academic_category VARCHAR(255) NOT NULL,
                subject_id INT NOT NULL,
                library_status ENUM('active', 'suspended') NOT NULL DEFAULT 'active',
                allocation_status ENUM('unallocated', 'allocated') NOT NULL DEFAULT 'unallocated',
                copies_total INT NOT NULL DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE RESTRICT,
                INDEX idx_library_books_academic_category (academic_category(100)),
                INDEX idx_library_books_subject (subject_id)
            )
        """)
        cursor.execute("SHOW COLUMNS FROM library_books LIKE 'buying_price'")
        if not cursor.fetchone():
            cursor.execute("""
                ALTER TABLE library_books
                ADD COLUMN buying_price DECIMAL(12,2) NOT NULL DEFAULT 0.00 AFTER description
            """)
            print("OK: Added library_books.buying_price")
        migrate_library_books_academic_category_schema(cursor)
        migrate_library_books_status_columns(cursor)
        ensure_library_book_allocations_table(cursor)
        migrate_library_books_copies_and_allocation_qty(cursor)
        ensure_library_book_stock_movements_table(cursor)
        ensure_library_book_copy_units_table(cursor)
        ensure_library_book_suppliers_table(cursor)
        ensure_library_book_teacher_distributions_table(cursor)
        ensure_library_book_student_issues_table(cursor)
    except Exception as e:
        print(f"ensure_library_books_table: {e}")
    finally:
        _library_books_schema_ensuring = False


def _library_books_drop_fk_on_column(cursor, table, column_name):
    try:
        cursor.execute(
            """
            SELECT CONSTRAINT_NAME
            FROM information_schema.KEY_COLUMN_USAGE
            WHERE TABLE_SCHEMA = DATABASE()
              AND TABLE_NAME = %s
              AND COLUMN_NAME = %s
              AND REFERENCED_TABLE_NAME IS NOT NULL
            """,
            (table, column_name),
        )
        row = cursor.fetchone()
        if not row:
            return
        cname = row.get('CONSTRAINT_NAME') if isinstance(row, dict) else row[0]
        if cname:
            cursor.execute(f"ALTER TABLE `{table}` DROP FOREIGN KEY `{cname}`")
    except Exception as e:
        print(f"_library_books_drop_fk_on_column ({table}.{column_name}): {e}")


def migrate_library_books_academic_category_schema(cursor):
    """Replace academic_level_id with academic_category (from academic_levels.level_category)."""
    try:
        cursor.execute("SHOW COLUMNS FROM library_books LIKE 'academic_category'")
        has_cat = bool(cursor.fetchone())
        cursor.execute("SHOW COLUMNS FROM library_books LIKE 'academic_level_id'")
        has_level = bool(cursor.fetchone())

        if has_level and not has_cat:
            cursor.execute(
                "ALTER TABLE library_books ADD COLUMN academic_category VARCHAR(255) NULL AFTER buying_price"
            )
            cursor.execute("""
                UPDATE library_books lb
                INNER JOIN academic_levels al ON al.id = lb.academic_level_id
                SET lb.academic_category = UPPER(TRIM(al.level_category))
            """)
            has_cat = True

        if has_level and has_cat:
            cursor.execute("""
                UPDATE library_books lb
                INNER JOIN academic_levels al ON al.id = lb.academic_level_id
                SET lb.academic_category = UPPER(TRIM(al.level_category))
                WHERE lb.academic_category IS NULL OR TRIM(lb.academic_category) = ''
            """)
            _library_books_drop_fk_on_column(cursor, 'library_books', 'academic_level_id')
            try:
                cursor.execute("ALTER TABLE library_books DROP INDEX idx_library_books_level")
            except Exception:
                pass
            try:
                cursor.execute("ALTER TABLE library_books DROP COLUMN academic_level_id")
            except Exception as e:
                print(f"migrate_library_books: drop academic_level_id: {e}")

        if not has_cat:
            cursor.execute(
                "ALTER TABLE library_books ADD COLUMN academic_category VARCHAR(255) NOT NULL DEFAULT ''"
            )

        cursor.execute(
            "UPDATE library_books SET academic_category = UPPER(TRIM(academic_category)) WHERE academic_category IS NOT NULL"
        )
        cursor.execute("""
            UPDATE library_books
            SET academic_category = 'UNKNOWN'
            WHERE academic_category IS NULL OR TRIM(academic_category) = ''
        """)
        try:
            cursor.execute(
                "ALTER TABLE library_books MODIFY COLUMN academic_category VARCHAR(255) NOT NULL"
            )
        except Exception as e:
            print(f"migrate_library_books: modify academic_category NOT NULL: {e}")

        cursor.execute("SHOW INDEX FROM library_books WHERE Key_name = 'idx_library_books_academic_category'")
        if not cursor.fetchone():
            try:
                cursor.execute(
                    "ALTER TABLE library_books ADD INDEX idx_library_books_academic_category (academic_category(100))"
                )
            except Exception as e:
                print(f"migrate_library_books: add index academic_category: {e}")
    except Exception as e:
        print(f"migrate_library_books_academic_category_schema: {e}")


