def get_db_connection():
    """Create and return a database connection - automatically creates database and tables if missing"""
    try:
        connection = pymysql.connect(**DB_CONFIG)
        return connection
    except pymysql.err.OperationalError as e:
        # If database doesn't exist, try to create it and reconnect
        if e.args[0] == 1049:  # Unknown database error
            print(f"Database '{DB_CONFIG['database']}' not found. Creating database and tables...")
            if ensure_database_exists():
                try:
                    # Initialize tables in the newly created database
                    if init_db():
                        # Now connect to the database
                        connection = pymysql.connect(**DB_CONFIG)
                        return connection
                    else:
                        print("Failed to initialize database tables.")
                        return None
                except Exception as e2:
                    print(f"Database connection error after creation: {e2}")
                    return None
            else:
                print(f"Failed to create database '{DB_CONFIG['database']}'.")
                return None
        else:
            print(f"Database connection error: {e}")
            return None
    except Exception as e:
        print(f"Database connection error: {e}")
        return None

def login_required(f):
    """Decorator to require login"""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if 'user_id' not in session:
            flash('Please login to access this page.', 'error')
            return redirect(url_for('login'))
        return f(*args, **kwargs)
    return decorated_function

def role_required(role):
    """Decorator to require specific role"""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if 'user_id' not in session:
                flash('Please login to access this page.', 'error')
                return redirect(url_for('login'))
            if session.get('role') != role:
                flash('You do not have permission to access this page.', 'error')
                return redirect(url_for('home'))
            return f(*args, **kwargs)
        return decorated_function
    return decorator

def _employee_staff_identity_sql(alias='e'):
    """SQL expression: employee_number.staff_number when present (teachers get a row on approval), else employees.id—used in timetables/reports (not portal login code)."""
    return (
        f"COALESCE((SELECT en.staff_number FROM employee_number en WHERE en.employee_id = {alias}.id LIMIT 1), "
        f"CAST({alias}.id AS CHAR))"
    )


def _staff_number_is_taken(cursor, staff_number: str, exclude_employee_id=None) -> bool:
    """Return True if another employee already uses this effective staff number (utf8mb4 collation-safe)."""
    cursor.execute(
        """
        SELECT e.id FROM employees e
        LEFT JOIN employee_number en ON en.employee_id = e.id
        WHERE (
            CAST(COALESCE(en.staff_number, CAST(e.id AS CHAR)) AS CHAR CHARACTER SET utf8mb4)
            COLLATE utf8mb4_general_ci
        ) = (
            CAST(%s AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_general_ci
        )
          AND (%s IS NULL OR e.id != %s)
        LIMIT 1
        """,
        (staff_number, exclude_employee_id, exclude_employee_id),
    )
    return bool(cursor.fetchone())


def resolve_session_employee_pk():
    """Resolve employees.id for the logged-in user (session user_id is authoritative)."""
    if not has_request_context():
        return None
    user_pk = session.get('user_id')
    portal_id = session.get('employee_id')
    connection = get_db_connection()
    if not connection:
        return None
    try:
        with connection.cursor() as cursor:
            if user_pk is not None:
                try:
                    pk = int(user_pk)
                    cursor.execute('SELECT id FROM employees WHERE id = %s LIMIT 1', (pk,))
                    row = cursor.fetchone()
                    if row:
                        return row.get('id') if isinstance(row, dict) else row[0]
                except (TypeError, ValueError):
                    pass
            if portal_id is not None and str(portal_id).strip():
                cursor.execute(
                    'SELECT id FROM employees WHERE employee_id = %s LIMIT 1',
                    (str(portal_id).strip(),),
                )
                row = cursor.fetchone()
                if row:
                    return row.get('id') if isinstance(row, dict) else row[0]
    except Exception as e:
        print(f'Error resolving session employee pk: {e}')
    finally:
        try:
            connection.close()
        except Exception:
            pass
    return None


def session_effective_role():
    """Role used for permission fallbacks (technician view-as uses viewed role)."""
    if not has_request_context():
        return 'employee'
    user_role = (session.get('role') or '').strip().lower()
    viewing = (session.get('viewing_as_employee_role') or '').strip().lower()
    if user_role == 'technician' and viewing:
        return viewing
    return user_role or 'employee'


def has_permission(employee_id, permission_key):
    """Check if an employee has a specific permission"""
    if not employee_id:
        return False
    
    connection = get_db_connection()
    if not connection:
        return False
    
    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT COUNT(*) as count 
                FROM employee_permissions 
                WHERE employee_id = %s AND permission_key = %s
            """, (employee_id, permission_key))
            result = cursor.fetchone()
            if result:
                count = result.get('count', 0) if isinstance(result, dict) else result[0] if isinstance(result, tuple) else 0
                return count > 0
            return False
    except Exception as e:
        print(f"Error checking permission: {e}")
        return False
    finally:
        if connection:
            try:
                connection.close()
            except:
                pass

def check_permission_or_role(permission_key, allowed_roles=None):
    """Check if user has permission OR is in allowed roles (for backward compatibility)
    
    Priority:
    1. Technicians always have access
    2. If employee has specific permission, grant access
    3. If employee has ANY permissions assigned but not this one, deny access (permission-based mode)
    4. If employee has NO permissions assigned, fall back to role-based access
    """
    user_role = session.get('role', '').lower()
    effective_role = session_effective_role()
    
    # Technicians have all permissions
    if user_role == 'technician':
        return True
    
    actual_employee_id = resolve_session_employee_pk()
    total_permissions = 0
    
    if actual_employee_id:
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    cursor.execute("""
                        SELECT COUNT(*) as count 
                        FROM employee_permissions 
                        WHERE employee_id = %s
                    """, (actual_employee_id,))
                    perm_result = cursor.fetchone()
                    if perm_result:
                        total_permissions = perm_result.get('count', 0) if isinstance(perm_result, dict) else perm_result[0] if isinstance(perm_result, tuple) else 0
            except Exception as e:
                print(f"Error counting employee permissions: {e}")
            finally:
                try:
                    connection.close()
                except Exception:
                    pass
    
    # Check if employee has specific permission assigned
    if actual_employee_id:
        has_specific_permission = has_permission(actual_employee_id, permission_key)
        
        # Debug logging
        print(f"DEBUG check_permission_or_role('{permission_key}'):")
        print(f"  - actual_employee_id: {actual_employee_id}")
        print(f"  - user_role: {user_role}")
        print(f"  - effective_role: {effective_role}")
        print(f"  - has_specific_permission: {has_specific_permission}")
        print(f"  - total_permissions: {total_permissions}")
        
        if has_specific_permission:
            print(f"  - RESULT: GRANTED (has specific permission)")
            return True
        
        # If employee has ANY permissions assigned, we're in permission-based mode
        # So if they don't have this specific permission, deny access — except staff keys for
        # head of institution / super admin, which still use allowed_roles below.
        if total_permissions > 0:
            skip_matrix_denial = (
                permission_key in HEAD_OF_INSTITUTION_STAFF_PERMISSION_FALLBACK
                and effective_role in ('head of institution', 'super admin')
            )
            if not skip_matrix_denial:
                print(f"  - RESULT: DENIED (permission-based mode, no specific permission)")
                return False
        
        # IMPORTANT: For accountants, principals, and other roles that use permissions,
        # if they have been to the permissions page (even if all toggled off),
        # we should check if they've ever had permissions assigned
        # Check if this employee has ever had permissions (check audit or use a flag)
        # For now, if they're an accountant/principal and have 0 permissions, 
        # we'll still allow role-based fallback BUT only if they've never had permissions managed
        
        # Check if employee has ever had any permissions (by checking if they exist in the table at all)
        # Actually, we can't easily check "ever had" without an audit table
        # Accountants with no permission rows use explicit grants only (no role fallback below).
        # Head of institution / super admin: staff keys above bypass matrix denial so role fallback applies.
        if user_role == 'accountant' and total_permissions == 0:
            print(f"  - RESULT: DENIED (accountant with no permissions - requires explicit permission)")
            return False
    
    # Fall back to role-based access only if:
    # 1. No permissions are assigned AND
    # 2. User is not an accountant (accountants require explicit permission rows)
    if allowed_roles and effective_role in allowed_roles:
        if effective_role != 'accountant':
            print(f"  - RESULT: GRANTED (role-based fallback: {effective_role} in {allowed_roles})")
            return True
        print(f"  - RESULT: DENIED (accountant requires explicit permission, no role fallback)")
        return False
    
    print(f"  - RESULT: DENIED (no permission, no role match)")
    return False

def get_employee_permissions_list(employee_id):
    """Get list of all permissions for an employee"""
    connection = get_db_connection()
    permissions = []
    
    if not connection:
        return permissions
    
    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT permission_key 
                FROM employee_permissions 
                WHERE employee_id = %s
            """, (employee_id,))
            results = cursor.fetchall()
            for result in results:
                if isinstance(result, dict):
                    permissions.append(result.get('permission_key'))
                else:
                    permissions.append(result[0] if result else '')
    except Exception as e:
        print(f"Error fetching employee permissions: {e}")
    finally:
        if connection:
            try:
                connection.close()
            except:
                pass
    
    return permissions

def permission_required(permission_key):
    """Decorator to require specific permission"""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if 'user_id' not in session:
                flash('Please login to access this page.', 'error')
                return redirect(url_for('login'))
            
            user_role = session.get('role', '').lower()
            employee_id = session.get('employee_id') or session.get('user_id')
            
            # Technicians have all permissions
            if user_role == 'technician':
                return f(*args, **kwargs)
            
            # Check if employee has the permission
            if employee_id and has_permission(employee_id, permission_key):
                return f(*args, **kwargs)
            
            # Fallback to role-based check for backward compatibility
            # This allows existing role-based access to still work
            flash('You do not have permission to access this page.', 'error')
            return redirect(employee_dashboard_path())
        return decorated_function
    return decorator

