def normalize_login_email(email):
    return (email or '').strip().lower()


def ensure_users_portal_login_schema(cursor):
    """Add login_code / student_id on users for parent & student six-digit portal sign-in."""
    try:
        cursor.execute("SHOW COLUMNS FROM users LIKE 'login_code'")
        if not cursor.fetchone():
            cursor.execute(
                "ALTER TABLE users ADD COLUMN login_code VARCHAR(6) NULL DEFAULT NULL "
                "COMMENT 'Six-digit portal sign-in' AFTER password_hash"
            )
    except Exception as e:
        print(f"ensure_users_portal_login_schema login_code: {e}")
    try:
        cursor.execute("SHOW COLUMNS FROM users LIKE 'student_id'")
        if not cursor.fetchone():
            cursor.execute(
                "ALTER TABLE users ADD COLUMN student_id VARCHAR(20) NULL DEFAULT NULL "
                "COMMENT 'Links student users to students.student_id' AFTER login_code"
            )
    except Exception as e:
        print(f"ensure_users_portal_login_schema student_id: {e}")
    try:
        cursor.execute(
            "SELECT 1 FROM information_schema.statistics "
            "WHERE table_schema = DATABASE() AND table_name = 'users' AND index_name = 'uk_users_login_code'"
        )
        if not cursor.fetchone():
            cursor.execute("CREATE UNIQUE INDEX uk_users_login_code ON users (login_code)")
    except Exception as e:
        print(f"ensure_users_portal_login_schema index: {e}")


def _normalize_parent_admission(raw):
    """Uppercase trimmed admission / student_id for lookups."""
    return (raw or '').strip().upper()


def _parent_admission_pattern_ok(admission_key):
    if not admission_key:
        return False
    if len(admission_key) < 2 or len(admission_key) > 32:
        return False
    return bool(re.match(r'^[A-Z0-9]+$', admission_key))


def _fetch_student_parent_by_admission(cursor, admission_raw):
    """Student + parent row for portal flows. Join is case/space-insensitive on student_id.

    If a student exists but no matching parents row (or join failed due to casing), inserts a minimal
    parents row so parent portal registration can proceed, then returns the joined row.
    """
    ak = _normalize_parent_admission(admission_raw)
    if not _parent_admission_pattern_ok(ak):
        return None

    join_on = (
        "UPPER(TRIM(CAST(p.student_id AS CHAR(64)))) = UPPER(TRIM(CAST(s.student_id AS CHAR(64))))"
    )
    where_student = "UPPER(TRIM(CAST(s.student_id AS CHAR(64)))) = %s"

    left_sql = f"""
        SELECT s.student_id, s.full_name AS student_name, s.date_of_birth, s.status,
               p.full_name AS parent_name, p.email AS parent_email, p.phone AS parent_phone,
               p.id AS parent_id
        FROM students s
        LEFT JOIN parents p ON {join_on}
        WHERE {where_student}
        LIMIT 1
    """

    def _run_left():
        cursor.execute(left_sql, (ak,))
        return cursor.fetchone()

    row = _run_left()
    if not row:
        return None

    if row.get('parent_id') is not None:
        return row

    sid = (row.get('student_id') or ak).strip()
    stu_name = (row.get('student_name') or 'Student').strip() or 'Student'
    guard_name = (f'Guardian - {stu_name}')[:250]

    try:
        cursor.execute(
            """
            SELECT id FROM parents
            WHERE UPPER(TRIM(CAST(student_id AS CHAR(64)))) = UPPER(TRIM(CAST(%s AS CHAR(64))))
            LIMIT 1
            """,
            (sid,),
        )
        if cursor.fetchone():
            row = _run_left()
            return row

        cursor.execute(
            """
            INSERT INTO parents (student_id, full_name, phone, email, relationship, emergency_contact)
            VALUES (%s, %s, '070000000000', NULL, 'GUARDIAN', '070000000000')
            """,
            (sid, guard_name),
        )
        try:
            cursor.connection.commit()
        except Exception as ce:
            print(f"_fetch_student_parent_by_admission commit after parent insert: {ce}")
        row = _run_left()
        return row
    except Exception as ex:
        print(f"_fetch_student_parent_by_admission ensure parent: {ex}")
        return _run_left()


def _mask_email_for_display(email):
    """Partially hide email for parent reset hints (e.g. j***n@school.com)."""
    em = (email or '').strip().lower()
    if '@' not in em:
        return ''
    local, domain = em.split('@', 1)
    if len(local) <= 1:
        masked_local = '*'
    elif len(local) == 2:
        masked_local = local[0] + '*'
    else:
        masked_local = local[0] + ('*' * min(len(local) - 2, 6)) + local[-1]
    return f'{masked_local}@{domain}'


def _clear_parent_password_reset_session():
    session.pop('parent_pwd_reset_student_id', None)
    session.pop('parent_pwd_reset_dob_ok', None)


def _fetch_parent_portal_user(cursor, admission_raw):
    """Parent portal user: match stored student_id (child admission) or legacy 6-digit login_code."""
    admission_key = _normalize_parent_admission(admission_raw)
    if not admission_key:
        return None
    clauses = ["UPPER(TRIM(COALESCE(u.student_id,''))) = %s"]
    params = [admission_key]
    ar = (admission_raw or '').strip()
    if ar.isdigit() and len(ar) == 6:
        clauses.append("(u.login_code IS NOT NULL AND u.login_code = %s)")
        params.append(ar)
        clauses.append(
            "(u.student_id IS NOT NULL AND CHAR_LENGTH(u.student_id) >= 6 AND RIGHT(u.student_id, 6) = %s)"
        )
        params.append(ar)
    sql = "SELECT u.* FROM users u WHERE u.role = 'parent' AND (" + " OR ".join(clauses) + ") LIMIT 1"
    cursor.execute(sql, params)
    return cursor.fetchone()


def _student_display_initials(full_name):
    name = (full_name or '').strip()
    if not name:
        return '?'
    parts = name.split()
    if len(parts) >= 2:
        return (parts[0][0] + parts[-1][0]).upper()
    return name[:2].upper()


def _parent_dashboard_spotlight_student(
    cursor, *, is_technician, viewing_as_parent, selected_student_id, parent_email, user_id
):
    """One student row for /parent header: technician selection, else users.student_id, else first child by parent email."""
    target_sid = ''
    if is_technician and viewing_as_parent:
        target_sid = (selected_student_id or '').strip()
    else:
        if user_id:
            cursor.execute(
                "SELECT student_id FROM users WHERE id = %s AND role = 'parent' LIMIT 1",
                (user_id,),
            )
            ur = cursor.fetchone()
            if ur and (ur.get('student_id') or '').strip():
                target_sid = ur.get('student_id').strip()
        pem = (parent_email or '').strip()
        if not target_sid and pem:
            cursor.execute(
                """
                SELECT s.student_id FROM students s
                INNER JOIN parents p ON s.student_id = p.student_id
                WHERE p.email = %s AND s.status = 'in session'
                ORDER BY s.full_name ASC
                LIMIT 1
                """,
                (pem,),
            )
            fr = cursor.fetchone()
            if fr and (fr.get('student_id') or '').strip():
                target_sid = fr.get('student_id').strip()
    if not target_sid:
        return None

    has_img_col = False
    try:
        cursor.execute("SHOW COLUMNS FROM students LIKE 'profile_image'")
        has_img_col = bool(cursor.fetchone())
    except Exception:
        has_img_col = False

    if has_img_col:
        cursor.execute(
            """
            SELECT student_id, full_name, current_grade, gender, date_of_birth, status, profile_image
            FROM students WHERE student_id = %s LIMIT 1
            """,
            (target_sid,),
        )
    else:
        cursor.execute(
            """
            SELECT student_id, full_name, current_grade, gender, date_of_birth, status
            FROM students WHERE student_id = %s LIMIT 1
            """,
            (target_sid,),
        )
    srow = cursor.fetchone()
    if not srow:
        return None

    dob = srow.get('date_of_birth')
    dob_str = ''
    if dob and hasattr(dob, 'strftime'):
        dob_str = dob.strftime('%d %b %Y')
    elif dob:
        dob_str = str(dob)[:10]

    prof = ''
    if has_img_col:
        prof = (srow.get('profile_image') or '').strip()

    full_name = (srow.get('full_name') or '').strip()
    return {
        'student_id': (srow.get('student_id') or '').strip(),
        'full_name': full_name,
        'current_grade': (srow.get('current_grade') or '').strip(),
        'gender': (srow.get('gender') or '').strip(),
        'status': (srow.get('status') or '').strip(),
        'date_of_birth_formatted': dob_str,
        'profile_image': prof or None,
        'initials': _student_display_initials(full_name),
    }


def _spotlight_academic_level_id(cursor, student_grade):
    """Resolve academic_levels.id for a grade label (tolerates level_status vs status)."""
    if not (student_grade or '').strip():
        return None
    g = student_grade.strip()
    attempts = [
        (
            """
            SELECT al.id FROM academic_levels al
            WHERE al.level_name = %s AND COALESCE(al.level_status, 'active') = 'active'
            LIMIT 1
            """,
            (g,),
        ),
        (
            """
            SELECT al.id FROM academic_levels al
            WHERE al.level_name = %s AND COALESCE(al.status, 'active') = 'active'
            LIMIT 1
            """,
            (g,),
        ),
        (
            "SELECT al.id FROM academic_levels al WHERE al.level_name = %s LIMIT 1",
            (g,),
        ),
    ]
    for sql, params in attempts:
        try:
            cursor.execute(sql, params)
            r = cursor.fetchone()
            if r and r.get('id'):
                return r.get('id')
        except Exception:
            continue
    return None


def _spotlight_fee_balance_for_student(cursor, student_id):
    """Active fee structure + payments for one student (aligned with parent_student_fees)."""
    base = {
        'has_structure': False,
        'fee_name': None,
        'total_amount': 0.0,
        'total_paid': 0.0,
        'balance': 0.0,
    }
    st = None
    try:
        cursor.execute(
            """
            SELECT current_grade, LOWER(TRIM(COALESCE(student_category, ''))) AS student_category
            FROM students WHERE student_id = %s LIMIT 1
            """,
            (student_id,),
        )
        st = cursor.fetchone()
    except Exception:
        try:
            cursor.execute(
                "SELECT current_grade FROM students WHERE student_id = %s LIMIT 1",
                (student_id,),
            )
            st = cursor.fetchone()
        except Exception:
            return base
    if not st:
        return base
    student_grade = (st.get('current_grade') or '').strip()
    student_category = (st.get('student_category') or '').strip().lower() if isinstance(st, dict) else ''
    if not student_grade:
        return base

    academic_level_id = _spotlight_academic_level_id(cursor, student_grade)
    if not academic_level_id:
        return base

    fee_structure_result = None
    try:
        if student_category == 'self sponsored':
            cursor.execute(
                """
                SELECT fs.id, fs.fee_name, fs.total_amount, fs.status
                FROM fee_structures fs
                WHERE fs.academic_level_id = %s
                  AND fs.status = 'active'
                  AND (fs.category = 'self sponsored' OR fs.category = 'both')
                ORDER BY
                  CASE WHEN fs.category = 'self sponsored' THEN 1 WHEN fs.category = 'both' THEN 2 ELSE 3 END,
                  fs.created_at DESC
                LIMIT 1
                """,
                (academic_level_id,),
            )
            fee_structure_result = cursor.fetchone()
        elif student_category == 'sponsored':
            cursor.execute(
                """
                SELECT fs.id, fs.fee_name, fs.total_amount, fs.status
                FROM fee_structures fs
                WHERE fs.academic_level_id = %s
                  AND fs.status = 'active'
                  AND (fs.category = 'sponsored' OR fs.category = 'both')
                ORDER BY
                  CASE WHEN fs.category = 'sponsored' THEN 1 WHEN fs.category = 'both' THEN 2 ELSE 3 END,
                  fs.created_at DESC
                LIMIT 1
                """,
                (academic_level_id,),
            )
            fee_structure_result = cursor.fetchone()
        elif student_category == 'both':
            cursor.execute(
                """
                SELECT fs.id, fs.fee_name, fs.total_amount, fs.status
                FROM fee_structures fs
                WHERE fs.academic_level_id = %s
                  AND fs.status = 'active'
                ORDER BY
                  CASE
                    WHEN fs.category = 'both' THEN 1
                    WHEN fs.category = 'self sponsored' THEN 2
                    WHEN fs.category = 'sponsored' THEN 3
                    ELSE 4
                  END,
                  fs.created_at DESC
                LIMIT 1
                """,
                (academic_level_id,),
            )
            fee_structure_result = cursor.fetchone()
        else:
            cursor.execute(
                """
                SELECT fs.id, fs.fee_name, fs.total_amount, fs.status
                FROM fee_structures fs
                WHERE fs.academic_level_id = %s
                  AND fs.status = 'active'
                  AND fs.category = 'both'
                ORDER BY fs.created_at DESC
                LIMIT 1
                """,
                (academic_level_id,),
            )
            fee_structure_result = cursor.fetchone()
    except Exception as ex:
        print(f"_spotlight_fee_balance_for_student fee_structure: {ex}")
        return base

    if not fee_structure_result:
        return base

    total_amount = float(fee_structure_result.get('total_amount', 0) or 0)
    cursor.execute(
        """
        SELECT COALESCE(SUM(amount_paid), 0) AS total_paid
        FROM student_payments WHERE student_id = %s
        """,
        (student_id,),
    )
    pr = cursor.fetchone()
    total_paid = float(pr.get('total_paid', 0) if pr else 0)
    balance = total_amount - total_paid
    return {
        'has_structure': True,
        'fee_name': fee_structure_result.get('fee_name') or 'Fees',
        'total_amount': total_amount,
        'total_paid': total_paid,
        'balance': balance,
    }


def _spotlight_subjects_for_student(cursor, student_id):
    """Subjects from class assignments for the student's grade, else distinct subjects from marks."""
    out = []
    cursor.execute("SELECT current_grade FROM students WHERE student_id = %s LIMIT 1", (student_id,))
    rw = cursor.fetchone()
    grade = (rw.get('current_grade') or '').strip() if rw else ''
    if grade:
        try:
            cursor.execute("SHOW TABLES LIKE 'teacher_subject_assignments'")
            if cursor.fetchone():
                cursor.execute(
                    """
                    SELECT DISTINCT s.subject_name, COALESCE(s.subject_code, '') AS subject_code
                    FROM teacher_subject_assignments tsa
                    INNER JOIN academic_levels al ON al.id = tsa.academic_level_id
                    INNER JOIN subjects s ON s.id = tsa.subject_id
                    WHERE al.level_name = %s
                    ORDER BY s.subject_name
                    """,
                    (grade,),
                )
                for r in cursor.fetchall() or []:
                    out.append(
                        {
                            'subject_name': (r.get('subject_name') or 'Subject').strip(),
                            'subject_code': (r.get('subject_code') or '').strip(),
                        }
                    )
        except Exception as ex:
            print(f"_spotlight_subjects_for_student tsa: {ex}")
    if not out:
        try:
            cursor.execute(
                """
                SELECT DISTINCT sub.subject_name, COALESCE(sub.subject_code, '') AS subject_code
                FROM student_marks sm
                INNER JOIN subjects sub ON sub.id = sm.subject_id
                WHERE sm.student_id = %s
                ORDER BY sub.subject_name
                """,
                (student_id,),
            )
            for r in cursor.fetchall() or []:
                out.append(
                    {
                        'subject_name': (r.get('subject_name') or 'Subject').strip(),
                        'subject_code': (r.get('subject_code') or '').strip(),
                    }
                )
        except Exception:
            pass
    return out


def _parse_dob_submitted(value):
    """Parse HTML date or common formats to a date object."""
    if not value:
        return None
    s = str(value).strip()
    for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%d-%m-%Y'):
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            continue
    return None


def lookup_account_for_password_reset(email):
    """Find account by email: employees first, then users (parent/student). Returns id, email, full_name, account_type."""
    email_norm = normalize_login_email(email)
    if not email_norm:
        return None
    connection = get_db_connection()
    if not connection:
        return None
    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT id, full_name, email FROM employees
                WHERE LOWER(TRIM(email)) = %s AND status IN ('pending approval', 'active')
            """, (email_norm,))
            row = cursor.fetchone()
            if row:
                return {
                    'account_type': 'employee',
                    'id': row['id'],
                    'full_name': (row.get('full_name') or '').strip(),
                    'email': (row.get('email') or email_norm).strip(),
                }
            cursor.execute("""
                SELECT id, full_name, email, role FROM users
                WHERE LOWER(TRIM(email)) = %s AND role IN ('parent', 'student')
            """, (email_norm,))
            row = cursor.fetchone()
            if row:
                role = (row.get('role') or '').strip()
                if role not in ('parent', 'student'):
                    return None
                return {
                    'account_type': role,
                    'id': row['id'],
                    'full_name': (row.get('full_name') or '').strip(),
                    'email': (row.get('email') or email_norm).strip(),
                }
            return None
    except Exception as e:
        print(f"lookup_account_for_password_reset: {e}")
        return None
    finally:
        try:
            connection.close()
        except Exception:
            pass


def _fetch_integration_email_dict():
    """SMTP settings saved under Integration Settings → Email."""
    connection = get_db_connection()
    if not connection:
        return {}
    try:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT settings_json FROM integration_settings WHERE integration_type = %s LIMIT 1",
                ('email',),
            )
            row = cursor.fetchone()
            if not row:
                return {}
            js = row.get('settings_json') if isinstance(row, dict) else row[0]
            data = json.loads(js or '{}')
            return data if isinstance(data, dict) else {}
    except Exception as e:
        print(f"_fetch_integration_email_dict: {e}")
        return {}
    finally:
        try:
            connection.close()
        except Exception:
            pass


def apply_mail_config_from_env_and_integration():
    """
    Flask-Mail reads app.config. Merge .env with integration_settings email (SMTP),
    so password reset works when credentials are only in the dashboard.
    """
    app.config['MAIL_SERVER'] = os.environ.get('MAIL_SERVER', app.config.get('MAIL_SERVER', 'smtp.gmail.com'))
    try:
        app.config['MAIL_PORT'] = int(os.environ.get('MAIL_PORT', app.config.get('MAIL_PORT', 587)))
    except (TypeError, ValueError):
        app.config['MAIL_PORT'] = 587
    app.config['MAIL_USE_TLS'] = os.environ.get('MAIL_USE_TLS', 'True').lower() in ['true', '1', 'yes']
    app.config['MAIL_USE_SSL'] = os.environ.get('MAIL_USE_SSL', 'False').lower() in ['true', '1', 'yes']
    app.config['MAIL_USERNAME'] = os.environ.get('MAIL_USERNAME', '')
    app.config['MAIL_PASSWORD'] = os.environ.get('MAIL_PASSWORD', '')
    app.config['MAIL_DEFAULT_SENDER'] = os.environ.get(
        'MAIL_DEFAULT_SENDER', app.config.get('MAIL_DEFAULT_SENDER', 'noreply@modernschool.com')
    )

    integ = _fetch_integration_email_dict()
    smtp_user = (integ.get('smtp_username') or '').strip()
    smtp_pass = (integ.get('smtp_password') or '').strip()
    if smtp_user and smtp_pass:
        app.config['MAIL_SERVER'] = (integ.get('smtp_server') or 'smtp.gmail.com').strip() or 'smtp.gmail.com'
        try:
            app.config['MAIL_PORT'] = int(integ.get('smtp_port') or 587)
        except (TypeError, ValueError):
            app.config['MAIL_PORT'] = 587
        port = int(app.config['MAIL_PORT'])
        utls = integ.get('use_tls')
        if utls is None:
            utls = port != 465
        if isinstance(utls, bool):
            app.config['MAIL_USE_TLS'] = utls
        else:
            app.config['MAIL_USE_TLS'] = str(utls).lower() in ('true', '1', 'yes')
        app.config['MAIL_USE_SSL'] = port == 465 and not app.config['MAIL_USE_TLS']
        app.config['MAIL_USERNAME'] = smtp_user
        app.config['MAIL_PASSWORD'] = smtp_pass
        app.config['MAIL_DEFAULT_SENDER'] = (integ.get('from_email') or smtp_user).strip()
    # Flask-Mail caches configuration at init time; refresh extension state after any update.
    try:
        mail.init_app(app)
    except Exception:
        pass

    if smtp_user and smtp_pass:
        return True
    return bool((app.config.get('MAIL_USERNAME') or '').strip())


def send_password_reset_email(to_email, recipient_name, verification_code):
    """Send verification code for password reset."""
    try:
        if not apply_mail_config_from_env_and_integration():
            print("Password reset: no SMTP credentials in .env or Integration Settings → Email.")
            return False
        settings = get_school_settings()
        school_name = (settings.get('school_name') or os.environ.get('SCHOOL_NAME') or 'School').strip() or 'School'
        subject = f"{school_name} — Password reset code"
        safe_name = (recipient_name or 'there').strip() or 'there'
        html_body = f"""
        <!DOCTYPE html>
        <html><head><meta charset="UTF-8"></head>
        <body style="font-family:system-ui,sans-serif;line-height:1.6;color:#333;max-width:560px;margin:0 auto;padding:24px;">
            <p>Hello {safe_name},</p>
            <p>Use this code to finish resetting your password:</p>
            <p style="font-size:28px;font-weight:700;letter-spacing:0.2em;color:#1e293b;">{verification_code}</p>
            <p style="color:#64748b;font-size:14px;">This code expires in 30 minutes. If you did not request a reset, you can ignore this email.</p>
            <p style="margin-top:24px;font-size:13px;color:#94a3b8;">{school_name}</p>
        </body></html>
        """
        text_body = (
            f"Hello {safe_name},\n\nYour password reset code is: {verification_code}\n\n"
            f"This code expires in 30 minutes. If you did not request this, ignore this email.\n\n{school_name}\n"
        )
        msg = Message(subject=subject, recipients=[to_email], html=html_body, body=text_body)
        mail.send(msg)
        print(f"Password reset email sent to {to_email}")
        return True
    except Exception as e:
        print(f"Error sending password reset email: {e}")
        return False


