def normalize_text(value, uppercase=True, allow_empty=False):
    """
    Normalize text: trim whitespace, replace multiple spaces with single space,
    and optionally convert to uppercase.
    
    Args:
        value: The text value to normalize
        uppercase: If True, convert to uppercase (default: True)
        allow_empty: If True, return None for empty values; if False, return empty string (default: False)
    
    Returns:
        Normalized string, empty string, or None based on allow_empty parameter
    """
    if not value:
        return None if allow_empty else ''
    # Replace multiple spaces/tabs/newlines with single space, then trim
    normalized = re.sub(r'\s+', ' ', str(value).strip())
    if not normalized:
        return None if allow_empty else ''
    return normalized.upper() if uppercase else normalized

@app.route('/admission', methods=['GET', 'POST'])
def admission():
    _portal = get_school_settings()
    admission_open = bool(_portal.get('allow_registration', True))

    if request.method == 'POST':
        if not admission_open:
            flash('Online admission is temporarily closed. Please contact the school office.', 'error')
            return redirect(url_for('admission'))

        # Get form data directly from students table column names
        # All text fields to UPPERCASE except email (lowercase)
        # Normalize spacing: multiple spaces become single space
        full_name = normalize_text(request.form.get('full_name', ''))  # students.full_name
        date_of_birth = request.form.get('date_of_birth')  # students.date_of_birth
        gender = normalize_text(request.form.get('gender'), allow_empty=True) if request.form.get('gender') else None  # students.gender
        current_grade = normalize_text(request.form.get('current_grade'), allow_empty=True) if request.form.get('current_grade') else None  # students.current_grade
        previous_school = normalize_text(request.form.get('previous_school'), allow_empty=True) if request.form.get('previous_school') else None  # students.previous_school
        assessment_number = normalize_text(request.form.get('assessment_number'), allow_empty=True) if request.form.get('assessment_number') else None  # students.assessment_number
        address = normalize_text(request.form.get('address'), allow_empty=True) if request.form.get('address') else None  # students.address
        medical_info = normalize_text(request.form.get('medical_info'), allow_empty=True) if request.form.get('medical_info') else None  # students.medical_info
        special_needs = normalize_text(request.form.get('special_needs'), allow_empty=True) if request.form.get('special_needs') else None  # students.special_needs
        student_category = normalize_text(request.form.get('student_category'), uppercase=False, allow_empty=True)  # students.student_category
        if student_category:
            student_category = student_category.lower()
        sponsor_name = normalize_text(request.form.get('sponsor_name'), allow_empty=True) if request.form.get('sponsor_name') else None  # students.sponsor_name
        sponsor_phone = normalize_text(request.form.get('sponsor_phone'), uppercase=False, allow_empty=True) if request.form.get('sponsor_phone') else None  # students.sponsor_phone
        sponsor_email = normalize_text(request.form.get('sponsor_email', ''), uppercase=False, allow_empty=True)  # students.sponsor_email
        if sponsor_email:
            sponsor_email = sponsor_email.lower()  # Email in lowercase
        else:
            sponsor_email = None  # Convert empty string to None for database
        
        # Parent/Guardian information (from parents table) — optional on form; defaults applied before save
        parent_name = normalize_text(request.form.get('parent_name', ''), allow_empty=True)
        relationship = normalize_text(request.form.get('relationship'), allow_empty=True) if request.form.get('relationship') else None
        parent_phone = normalize_text(request.form.get('parent_phone', ''), uppercase=False, allow_empty=True)
        parent_email = normalize_text(request.form.get('parent_email', ''), uppercase=False, allow_empty=True)
        if parent_email:
            parent_email = parent_email.lower()
        else:
            parent_email = None
        emergency_contact = normalize_text(request.form.get('emergency_contact'), allow_empty=True) if request.form.get('emergency_contact') else None
        
        consent = request.form.get('consent')
        parent_email_left_blank = not (request.form.get('parent_email') or '').strip()
        
        # Required: student core + category + consent
        if not all([full_name, date_of_birth, consent, student_category]):
            flash('Please fill in all required fields (student details, student category, and consent).', 'error')
            return redirect(url_for('admission'))
        
        # Validate sponsor_name if category is sponsored or both
        if student_category in ['sponsored', 'both'] and not sponsor_name:
            flash('Please provide sponsor name/company for sponsored students.', 'error')
            return redirect(url_for('admission'))
        
        # Optional blanks → placeholders (parents.phone / parents.full_name are NOT NULL in DB)
        if not parent_name:
            parent_name = normalize_text(f'PARENT TO {full_name}')
        if not relationship:
            relationship = normalize_text('NOT SPECIFIED')
        if not parent_phone:
            parent_phone = '070000000000'
        if parent_email_left_blank:
            parent_email = 'parent@gmail.com'
        if not emergency_contact:
            emergency_contact = '070000000000'
        if not address:
            address = normalize_text(
                f'NOT PROVIDED AT APPLICATION — STUDENT: {full_name}',
                uppercase=False,
                allow_empty=False,
            )
        if not medical_info:
            medical_info = normalize_text(
                'NOT PROVIDED AT APPLICATION',
                uppercase=False,
                allow_empty=False,
            )
        if not special_needs:
            special_needs = normalize_text(
                'NONE REPORTED AT APPLICATION',
                uppercase=False,
                allow_empty=False,
            )
        
        # Save to database
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    # Generate unique student ID
                    student_id = generate_student_id(connection)
                    
                    # Insert student data into students table (using exact column names from students table)
                    student_sql = """
                        INSERT INTO students 
                        (student_id, full_name, date_of_birth, gender, current_grade, previous_school,
                         assessment_number, address, medical_info, special_needs, student_category, sponsor_name, sponsor_phone, sponsor_email, status)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'pending approval')
                    """
                    cursor.execute(student_sql, (
                        student_id, full_name, date_of_birth, gender, current_grade, 
                        previous_school, assessment_number, address, medical_info, special_needs, student_category, 
                        sponsor_name, sponsor_phone, sponsor_email
                    ))
                    
                    # Insert parent data into parents table (linked via student_id)
                    parent_sql = """
                        INSERT INTO parents 
                        (student_id, full_name, phone, email, relationship, emergency_contact)
                        VALUES (%s, %s, %s, %s, %s, %s)
                    """
                    cursor.execute(parent_sql, (
                        student_id,
                        (parent_name or ''),
                        (parent_phone or ''),
                        parent_email,
                        relationship,
                        emergency_contact,
                    ))
                    
                    connection.commit()
                    
                    # Confirmation email only when applicant typed an address (not auto-filled placeholder)
                    if parent_email and not parent_email_left_blank:
                        try:
                            send_admission_confirmation_email(parent_email, parent_name, full_name, student_id)
                        except Exception as email_error:
                            print(f"Error sending email: {email_error}")
                            # Don't fail the submission if email fails
                    
                    flash(f'Application submitted successfully! Your Student ID is: {student_id}. We will review it and get back to you soon.', 'success')
            except Exception as e:
                print(f"Error saving admission: {e}")
                try:
                    connection.rollback()
                except:
                    pass  # Connection might already be closed
                flash('An error occurred while submitting your application. Please try again.', 'error')
            finally:
                if connection:
                    try:
                        connection.close()
                    except:
                        pass  # Connection might already be closed
        else:
            flash('Database connection error. Please try again later.', 'error')
        
        return redirect(url_for('home'))
    
    # GET request - render admission form
    # Fetch active academic levels for admission form
    academic_levels = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description 
                    FROM academic_levels 
                    WHERE level_status = 'active'
                    ORDER BY level_name ASC
                """)
                results = cursor.fetchall()
                
                if results:
                    for row in results:
                        academic_levels.append({
                            'id': row.get('id'),
                            'level_category': row.get('level_category', ''),
                            'level_name': row.get('level_name', ''),
                            'level_description': row.get('level_description', '')
                        })
        except Exception as e:
            print(f"Error fetching academic levels for admission: {e}")
        finally:
            connection.close()
    
    return render_template(
        'admission_form.html',
        academic_levels=academic_levels,
        admission_open=admission_open,
    )

@app.route('/register-employee', methods=['GET', 'POST'])
def register_employee():
    if request.method == 'POST':
        # Get form data and convert to proper case
        # All text fields to UPPERCASE except email (lowercase)
        # Normalize spacing: multiple spaces become single space
        full_name = normalize_text(request.form.get('full_name', ''))
        email = normalize_text(request.form.get('email', ''), uppercase=False, allow_empty=True)
        if email:
            email = email.lower()  # Email in lowercase
        phone = normalize_text(request.form.get('phone', ''), uppercase=False)
        id_number = normalize_text(request.form.get('id_number', ''))
        employee_id = request.form.get('employee_id', '').strip()  # Keep as is (numeric)
        password = request.form.get('password', '')
        confirm_password = request.form.get('confirm_password', '')

        def render_registration_error(message):
            return render_template(
                'employee_registration_form.html',
                register_error=message,
                register_success='',
                ask_login_after_register=False,
                form_data={
                    'full_name': full_name,
                    'email': email,
                    'phone': phone,
                    'id_number': id_number,
                    'employee_id': employee_id,
                },
            )

        def render_registration_success(message):
            return render_template(
                'employee_registration_form.html',
                register_error='',
                register_success=message,
                ask_login_after_register=True,
                form_data={},
            )
        
        # Validate required fields
        if not all([full_name, email, phone, id_number, employee_id, password, confirm_password]):
            return render_registration_error('Please fill in all required fields.')
        
        # Validate employee ID is 6 digits
        if not employee_id.isdigit() or len(employee_id) != 6:
            return render_registration_error('Employee ID must be exactly 6 digits.')
        
        # Validate passwords match
        if password != confirm_password:
            return render_registration_error('Passwords do not match.')
        
        # Validate password strength
        if len(password) < 6:
            return render_registration_error('Password must be at least 6 characters long.')
        
        # Handle profile picture upload
        profile_picture = None
        if 'profile_picture' in request.files:
            file = request.files['profile_picture']
            if file and file.filename != '' and allowed_file(file.filename):
                # Generate unique filename
                timestamp = datetime.now().strftime('%Y%m%d%H%M%S')
                filename = secure_filename(f"{employee_id}_{timestamp}_{file.filename}")
                filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
                file.save(filepath)
                profile_picture = f"uploads/profiles/{filename}"
        
        # Hash password
        password_hash = generate_password_hash(password)
        
        # Save to database
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    # Check if employee ID already exists
                    cursor.execute("SELECT id FROM employees WHERE employee_id = %s", (employee_id,))
                    if cursor.fetchone():
                        return render_registration_error('Employee ID already exists. Please use a different ID.')
                    
                    # Check if email already exists
                    cursor.execute("SELECT id FROM employees WHERE email = %s", (email,))
                    if cursor.fetchone():
                        return render_registration_error('Email already registered. Please use a different email.')
                    
                    # Insert employee data
                    employee_sql = """
                        INSERT INTO employees 
                        (employee_id, full_name, email, phone, id_number, password_hash, 
                         profile_picture, role, status)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, 'employee', 'pending approval')
                    """
                    cursor.execute(employee_sql, (
                        employee_id, full_name, email, phone, id_number, password_hash, profile_picture
                    ))
                    
                    connection.commit()
                    
                    # Send welcome email to employee
                    try:
                        send_employee_welcome_email(email, full_name, employee_id)
                    except Exception as email_error:
                        print(f"Error sending welcome email: {email_error}")
                        # Don't fail the registration if email fails
                    return render_registration_success(
                        'Employee registration submitted successfully! Your application is pending approval. '
                        'You will receive a welcome email shortly.'
                    )
            except Exception as e:
                print(f"Error saving employee registration: {e}")
                try:
                    connection.rollback()
                except:
                    pass  # Connection might already be closed
                return render_registration_error('An error occurred while submitting your registration. Please try again.')
            finally:
                if connection:
                    try:
                        connection.close()
                    except:
                        pass  # Connection might already be closed
        else:
            return render_registration_error('Database connection error. Please try again later.')
        
        return redirect(url_for('home'))
    
    # GET request - render employee registration form
    return render_template(
        'employee_registration_form.html',
        form_data={},
        register_error='',
        register_success='',
        ask_login_after_register=False,
    )

@app.route('/check-employee-id', methods=['POST'])
def check_employee_id():
    """Check if employee ID is available"""
    try:
        data = request.get_json()
        employee_id = data.get('employee_id', '').strip() if data else ''
        
        if not employee_id or len(employee_id) != 6 or not employee_id.isdigit():
            return jsonify({'available': False, 'message': 'Employee ID must be exactly 6 digits'}), 400
        
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    cursor.execute("SELECT id FROM employees WHERE employee_id = %s", (employee_id,))
                    result = cursor.fetchone()
                    
                    if result:
                        return jsonify({'available': False, 'message': 'This Employee ID is already registered. Please use a different ID.'}), 200
                    else:
                        return jsonify({'available': True, 'message': 'Employee ID is available!'}), 200
            except Exception as e:
                print(f"Error checking employee ID: {e}")
                return jsonify({'available': False, 'message': 'Error checking employee ID. Please try again.'}), 500
            finally:
                if connection:
                    try:
                        connection.close()
                    except:
                        pass  # Connection might already be closed
        else:
            return jsonify({'available': False, 'message': 'Database connection error. Please try again.'}), 500
    except Exception as e:
        print(f"Error in check_employee_id: {e}")
        return jsonify({'available': False, 'message': 'An error occurred. Please try again.'}), 500


@app.route('/check-staff-number', methods=['POST'])
@app.route('/dashboard/employee/check-staff-number', methods=['POST'])
@login_required
def check_staff_number():
    """Live availability check for editable staff number (Staff Management edit)."""
    has_access = check_permission_or_role(
        'edit_staff',
        allowed_roles=[
            'employee', 'super admin', 'head of institution', 'deputy head of institution',
            'curriculum coordinator', 'teachers', 'accountant', 'secretary', 'librarian',
            'warden', 'transport manager', 'store manager', 'technician',
        ],
    )
    if not has_access:
        return jsonify({'available': False, 'message': 'You do not have permission to check staff numbers.'}), 403

    data = request.get_json(silent=True) or {}
    staff_number = str(data.get('staff_number', '')).strip()
    exclude_raw = data.get('exclude_employee_id')

    exclude_id = None
    if exclude_raw is not None and str(exclude_raw).strip() != '':
        try:
            exclude_id = int(exclude_raw)
        except (TypeError, ValueError):
            return jsonify({'available': False, 'message': 'Invalid employee reference.'}), 400

    if not staff_number:
        return jsonify({'available': False, 'message': 'Enter a staff number.'}), 200

    if len(staff_number) > 50:
        return jsonify({'available': False, 'message': 'Staff number is too long (max 50 characters).'}), 200

    connection = get_db_connection()
    if not connection:
        return jsonify({'available': False, 'message': 'Database connection error.'}), 500

    try:
        with connection.cursor() as cursor:
            if _staff_number_is_taken(cursor, staff_number, exclude_id):
                return jsonify({
                    'available': False,
                    'message': 'This staff number is already assigned to another employee. Please choose a different one.',
                }), 200
            return jsonify({'available': True, 'message': 'This staff number is available.'}), 200
    except Exception as e:
        print(f"Error checking staff number: {e}")
        return jsonify({'available': False, 'message': 'Could not verify availability. Please try again.'}), 500
    finally:
        if connection:
            try:
                connection.close()
            except Exception:
                pass


@app.route('/api/parent-portal/check-admission', methods=['GET'])
def api_parent_portal_check_admission():
    """Live validation: admission exists (parent row created if missing), and no parent users row yet."""
    raw = (request.args.get('q') or '').strip()
    admission_key = _normalize_parent_admission(raw)
    if not admission_key:
        return jsonify(
            {
                'ok': False,
                'ready': False,
                'reason': 'empty',
                'message': 'Enter your child’s admission ID.',
            }
        )
    if not _parent_admission_pattern_ok(admission_key):
        return jsonify(
            {
                'ok': False,
                'ready': False,
                'reason': 'invalid_format',
                'message': 'Use 2–32 letters or numbers only (e.g. STU001).',
            }
        )
    connection = get_db_connection()
    if not connection:
        return jsonify(
            {
                'ok': False,
                'ready': False,
                'reason': 'server',
                'message': 'Service unavailable. Try again in a moment.',
            }
        ), 503
    try:
        with connection.cursor() as cursor:
            ensure_users_portal_login_schema(cursor)
            connection.commit()
            row = _fetch_student_parent_by_admission(cursor, raw)
            if not row:
                return jsonify(
                    {
                        'ok': False,
                        'ready': False,
                        'reason': 'not_found',
                        'message': 'No student with that admission ID in our records. Check spelling (letters and numbers only) or contact the school.',
                    }
                )
            sid = (row.get('student_id') or admission_key).strip()
            if _fetch_parent_portal_user(cursor, raw):
                return jsonify(
                    {
                        'ok': False,
                        'ready': False,
                        'reason': 'portal_exists',
                        'message': 'A parent portal account already exists for this admission. Sign in or use Forgot password.',
                        'login_url': url_for('login', role='parent', admission=sid),
                    }
                )
            return jsonify(
                {
                    'ok': True,
                    'ready': True,
                    'reason': 'ready',
                    'message': 'Admission verified. Continuing…',
                    'student_name': (row.get('student_name') or '').strip(),
                    'student_id': sid,
                }
            )
    except Exception as e:
        print(f"api_parent_portal_check_admission: {e}")
        return jsonify(
            {
                'ok': False,
                'ready': False,
                'reason': 'server',
                'message': 'Could not verify right now. Try again.',
            }
        ), 500
    finally:
        try:
            connection.close()
        except Exception:
            pass


@app.route('/parent-forgot-password', methods=['GET', 'POST'])
@app.route('/parent/forgot-password', methods=['GET', 'POST'])
@app.route('/dashboard/parent/forgot-password', methods=['GET', 'POST'])
def parent_forgot_password():
    """Parent password reset: admission ID → child DOB → email on account → verification code by email."""
    admission_prefill = (request.args.get('admission') or '').strip()

    if request.method == 'POST':
        action = (request.form.get('reset_action') or '').strip()
        connection = get_db_connection()
        if not connection:
            flash('Database connection error. Please try again later.', 'error')
            return redirect(url_for('parent_forgot_password'))
        error = None
        try:
            with connection.cursor() as cursor:
                ensure_users_portal_login_schema(cursor)
                connection.commit()
                if action == 'admission':
                    raw = (request.form.get('admission') or '').strip()
                    ak = _normalize_parent_admission(raw)
                    if not _parent_admission_pattern_ok(ak):
                        error = 'Enter a valid admission ID (letters and numbers only, e.g. STU001).'
                    else:
                        row = _fetch_student_parent_by_admission(cursor, raw)
                        if not row:
                            error = (
                                'We could not find a student with that admission ID. '
                                'Check the ID or contact the school.'
                            )
                        else:
                            portal_user = _fetch_parent_portal_user(cursor, raw)
                            if not portal_user:
                                error = (
                                    'No parent portal account exists for this admission yet. '
                                    'Use Parent setup on the sign-in page to create one.'
                                )
                            else:
                                canonical_sid = (row.get('student_id') or ak).strip()
                                session['parent_pwd_reset_student_id'] = canonical_sid
                                session.pop('parent_pwd_reset_dob_ok', None)
                                return redirect(url_for('parent_forgot_password'))
                elif action == 'dob':
                    sid = session.get('parent_pwd_reset_student_id')
                    if not sid:
                        error = 'Session expired. Enter the admission ID again.'
                    else:
                        dob_in = _parse_dob_submitted(request.form.get('date_of_birth'))
                        if dob_in is None:
                            error = 'Enter a valid date of birth.'
                        else:
                            row = _fetch_student_parent_by_admission(cursor, sid)
                            if not row:
                                error = 'Record not found. Start again with the admission ID.'
                                _clear_parent_password_reset_session()
                            else:
                                db_dob = row.get('date_of_birth')
                                if db_dob is None:
                                    error = (
                                        'Date of birth is not on file for this student. Please contact the school.'
                                    )
                                else:
                                    if hasattr(db_dob, 'date'):
                                        db_dob = db_dob.date()
                                    if dob_in != db_dob:
                                        error = (
                                            'That date of birth does not match our records. Try again or contact the school.'
                                        )
                                    else:
                                        session['parent_pwd_reset_dob_ok'] = '1'
                                        return redirect(url_for('parent_forgot_password'))
                elif action == 'email':
                    sid = session.get('parent_pwd_reset_student_id')
                    if not sid or session.get('parent_pwd_reset_dob_ok') != '1':
                        error = 'Session expired or date of birth not verified. Start again from the admission step.'
                    else:
                        email_in = normalize_login_email(request.form.get('email', ''))
                        if not email_in or '@' not in email_in:
                            error = 'Enter the email address on your parent portal account.'
                        else:
                            portal_user = _fetch_parent_portal_user(cursor, sid)
                            if not portal_user:
                                error = 'No portal account found. Start again or contact the school.'
                                _clear_parent_password_reset_session()
                            else:
                                account_email = normalize_login_email(portal_user.get('email') or '')
                                if not account_email:
                                    error = (
                                        'No email is stored on your portal account. Please contact the school office.'
                                    )
                                elif email_in != account_email:
                                    error = (
                                        'That email does not match our records for this admission. '
                                        'Use the email you registered with, or contact the school.'
                                    )
                                else:
                                    code = ''.join(secrets.choice('0123456789') for _ in range(6))
                                    code_hash = generate_password_hash(code)
                                    expires_at = datetime.utcnow() + timedelta(minutes=30)
                                    full_name = (portal_user.get('full_name') or 'Parent').strip() or 'Parent'
                                    if not send_password_reset_email(account_email, full_name, code):
                                        error = (
                                            'Could not send the verification email. Ask the school to check email settings, '
                                            'or try again later.'
                                        )
                                    else:
                                        cursor.execute(
                                            """
                                            DELETE FROM password_reset_tokens
                                            WHERE LOWER(TRIM(email)) = %s AND consumed_at IS NULL
                                            """,
                                            (account_email,),
                                        )
                                        cursor.execute(
                                            """
                                            INSERT INTO password_reset_tokens
                                                (email, account_type, account_id, code_hash, expires_at)
                                            VALUES (%s, 'parent', %s, %s, %s)
                                            """,
                                            (account_email, portal_user['id'], code_hash, expires_at),
                                        )
                                        connection.commit()
                                        _clear_parent_password_reset_session()
                                        session['pwd_reset_email'] = account_email
                                        flash(
                                            'We sent a 6-digit code to your email. Enter it on the next page with your new password.',
                                            'success',
                                        )
                                        return redirect(url_for('reset_password'))
                else:
                    error = 'Invalid step.'
        finally:
            try:
                connection.close()
            except Exception:
                pass

        if error:
            flash(error, 'error')
            return redirect(url_for('parent_forgot_password'))

    student_id_sess = session.get('parent_pwd_reset_student_id')
    dob_ok = session.get('parent_pwd_reset_dob_ok') == '1'
    masked_email = ''
    if student_id_sess and dob_ok:
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    portal_user = _fetch_parent_portal_user(cursor, student_id_sess)
                    if portal_user:
                        masked_email = _mask_email_for_display(portal_user.get('email') or '')
            except Exception as e:
                print(f"parent_forgot_password masked email: {e}")
            finally:
                try:
                    connection.close()
                except Exception:
                    pass

    if student_id_sess and dob_ok:
        step = 3
    elif student_id_sess:
        step = 2
    else:
        step = 1

    return render_template(
        'parent_forgot_password.html',
        step=step,
        admission_prefill=admission_prefill,
        student_id_display=student_id_sess or '',
        masked_email=masked_email,
    )


@app.route('/parent-portal-setup', methods=['GET', 'POST'])
@app.route('/parent/portal-setup', methods=['GET', 'POST'])
@app.route('/dashboard/parent/portal-setup', methods=['GET', 'POST'])
def parent_portal_setup():
    """First-time parent portal: admission ID → verify child DOB → email + password (creates users row)."""
    admission_prefill = (request.args.get('admission') or '').strip()

    if request.method == 'POST':
        action = (request.form.get('setup_action') or '').strip()
        connection = get_db_connection()
        if not connection:
            flash('Database connection error. Please try again later.', 'error')
            return redirect(url_for('parent_portal_setup'))
        try:
            with connection.cursor() as cursor:
                ensure_users_portal_login_schema(cursor)
                connection.commit()
                if action == 'admission':
                    raw = (request.form.get('admission') or '').strip()
                    ak = _normalize_parent_admission(raw)
                    if not _parent_admission_pattern_ok(ak):
                        error = 'Enter a valid admission ID (letters and numbers only, e.g. STU001).'
                    else:
                        row = _fetch_student_parent_by_admission(cursor, raw)
                        if not row:
                            error = 'We could not find a student with that admission ID and a parent/guardian on file. Check the ID or contact the school.'
                        else:
                            if _fetch_parent_portal_user(cursor, raw):
                                session.pop('parent_portal_student_id', None)
                                session.pop('parent_portal_dob_ok', None)
                                flash(
                                    'A parent portal account already exists for this admission. Sign in with your admission ID and password, or use Forgot password.',
                                    'info',
                                )
                                return redirect(url_for('login', role='parent', admission=row.get('student_id') or ak))
                            canonical_sid = (row.get('student_id') or ak).strip()
                            session['parent_portal_student_id'] = canonical_sid
                            session.pop('parent_portal_dob_ok', None)
                            return redirect(url_for('parent_portal_setup'))
                elif action == 'dob':
                    sid = session.get('parent_portal_student_id')
                    if not sid:
                        error = 'Session expired. Enter the admission ID again.'
                    else:
                        dob_in = _parse_dob_submitted(request.form.get('date_of_birth'))
                        if dob_in is None:
                            error = 'Enter a valid date of birth.'
                        else:
                            row = _fetch_student_parent_by_admission(cursor, sid)
                            if not row:
                                error = 'Record not found. Start again with the admission ID.'
                                session.pop('parent_portal_student_id', None)
                                session.pop('parent_portal_dob_ok', None)
                            else:
                                db_dob = row.get('date_of_birth')
                                if db_dob is None:
                                    error = 'Date of birth is not on file for this student. Please contact the school.'
                                else:
                                    if hasattr(db_dob, 'date'):
                                        db_dob = db_dob.date()
                                    if dob_in != db_dob:
                                        error = (
                                            'That date of birth does not match our records. Try again or contact the school.'
                                        )
                                    else:
                                        session['parent_portal_dob_ok'] = '1'
                                        return redirect(url_for('parent_portal_setup'))
                elif action == 'account':
                    sid = session.get('parent_portal_student_id')
                    if not sid or session.get('parent_portal_dob_ok') != '1':
                        error = 'Session expired or date of birth not verified. Start again from the admission step.'
                    else:
                        email = normalize_login_email(request.form.get('email', ''))
                        pw = request.form.get('new_password', '')
                        pw2 = request.form.get('confirm_password', '')
                        if not email or '@' not in email:
                            error = 'Enter a valid email address.'
                        elif len(pw) < 6:
                            error = 'Password must be at least 6 characters.'
                        elif pw != pw2:
                            error = 'Password and confirmation do not match.'
                        else:
                            row = _fetch_student_parent_by_admission(cursor, sid)
                            if not row:
                                error = 'Record not found. Start again with the admission ID.'
                                session.pop('parent_portal_student_id', None)
                                session.pop('parent_portal_dob_ok', None)
                            elif _fetch_parent_portal_user(cursor, sid):
                                session.pop('parent_portal_student_id', None)
                                session.pop('parent_portal_dob_ok', None)
                                flash('An account already exists for this admission. Please sign in.', 'info')
                                return redirect(url_for('login', role='parent', admission=sid))
                            else:
                                parent_name = (row.get('parent_name') or 'Parent').strip() or 'Parent'
                                ph = generate_password_hash(pw)
                                canonical_sid = (row.get('student_id') or sid).strip()
                                try:
                                    cursor.execute(
                                        """
                                        INSERT INTO users (full_name, email, password_hash, login_code, student_id, role)
                                        VALUES (%s, %s, %s, NULL, %s, 'parent')
                                        """,
                                        (parent_name, email, ph, canonical_sid),
                                    )
                                    cursor.execute(
                                        "UPDATE parents SET email = %s WHERE student_id = %s",
                                        (email, canonical_sid),
                                    )
                                    connection.commit()
                                except IntegrityError:
                                    connection.rollback()
                                    error = (
                                        'That email is already used by another account. '
                                        'Use a different email or sign in and use Forgot password if this is yours.'
                                    )
                                except Exception as ex:
                                    connection.rollback()
                                    print(f"parent_portal_setup insert: {ex}")
                                    error = 'Could not create your account. Please try again or contact the school.'
                                else:
                                    session.pop('parent_portal_student_id', None)
                                    session.pop('parent_portal_dob_ok', None)
                                    flash(
                                        'Your parent portal account is ready. Sign in with your child\'s admission ID and the password you chose.',
                                        'success',
                                    )
                                    return redirect(url_for('login', role='parent', admission=canonical_sid))
                else:
                    error = 'Invalid step.'
        finally:
            try:
                connection.close()
            except Exception:
                pass

        if error:
            flash(error, 'error')
            return redirect(url_for('parent_portal_setup'))

    student_id_sess = session.get('parent_portal_student_id')
    dob_ok = session.get('parent_portal_dob_ok') == '1'
    if student_id_sess and dob_ok:
        step = 3
    elif student_id_sess:
        step = 2
    else:
        step = 1

    return render_template(
        'parent_portal_setup.html',
        step=step,
        admission_prefill=admission_prefill,
        student_id_display=student_id_sess or '',
    )


@app.route('/login/parent-register', methods=['POST'])
def login_parent_register():
    """Create parent portal account from login page (admission + DOB + email + password), then sign in."""
    admission_raw = (request.form.get('admission') or '').strip()
    email = normalize_login_email(request.form.get('email', ''))
    pw = request.form.get('new_password', '')
    pw2 = request.form.get('confirm_password', '')
    remember = bool(request.form.get('remember_me'))

    def _back(admission_val=''):
        q = {'role': 'parent'}
        if admission_val:
            q['admission'] = admission_val
        return redirect(url_for('login', **q))

    ak = _normalize_parent_admission(admission_raw)
    if not _parent_admission_pattern_ok(ak):
        flash('Enter a valid admission ID (letters and numbers only, e.g. STU001).', 'error')
        return _back(admission_raw)

    dob_in = _parse_dob_submitted(request.form.get('date_of_birth'))
    if dob_in is None:
        flash('Enter your child’s date of birth.', 'error')
        return _back(admission_raw)

    if not email or '@' not in email:
        flash('Enter a valid email address.', 'error')
        return _back(admission_raw)
    if len(pw) < 6:
        flash('Password must be at least 6 characters.', 'error')
        return _back(admission_raw)
    if pw != pw2:
        flash('Password and confirmation do not match.', 'error')
        return _back(admission_raw)

    connection = get_db_connection()
    if not connection:
        flash('Database connection error. Please try again later.', 'error')
        return _back(admission_raw)

    try:
        with connection.cursor() as cursor:
            ensure_users_portal_login_schema(cursor)
            connection.commit()
            row = _fetch_student_parent_by_admission(cursor, admission_raw)
            if not row:
                flash('No student with that admission ID in our records. Check spelling or contact the school.', 'error')
                return _back()
            canonical_sid = (row.get('student_id') or ak).strip()
            db_dob = row.get('date_of_birth')
            if db_dob is not None and hasattr(db_dob, 'date'):
                db_dob = db_dob.date()
            if db_dob is None:
                flash('Date of birth is not on file for this student. Please contact the school.', 'error')
                return _back(canonical_sid)
            if dob_in != db_dob:
                flash('That date of birth does not match our records.', 'error')
                return _back(canonical_sid)
            if _fetch_parent_portal_user(cursor, admission_raw):
                flash('A parent account already exists for this admission. Sign in with your password below.', 'info')
                return _back(canonical_sid)

            parent_name = (row.get('parent_name') or 'Parent').strip() or 'Parent'
            ph = generate_password_hash(pw)
            try:
                cursor.execute(
                    """
                    INSERT INTO users (full_name, email, password_hash, login_code, student_id, role)
                    VALUES (%s, %s, %s, NULL, %s, 'parent')
                    """,
                    (parent_name, email, ph, canonical_sid),
                )
                new_id = cursor.lastrowid
                cursor.execute(
                    "UPDATE parents SET email = %s WHERE student_id = %s",
                    (email, canonical_sid),
                )
                connection.commit()
            except IntegrityError:
                connection.rollback()
                flash(
                    'That email is already used by another account. Use a different email or Forgot password.',
                    'error',
                )
                return _back(canonical_sid)
            except Exception as ex:
                connection.rollback()
                print(f'login_parent_register: {ex}')
                flash('Could not create your account. Please try again.', 'error')
                return _back(canonical_sid)

        session.permanent = remember
        session['user_id'] = new_id
        session['email'] = email
        session['full_name'] = parent_name
        session['role'] = 'parent'
        flash(f'Welcome, {parent_name}! Your parent portal is ready.', 'success')
        return redirect(parent_dashboard_path())
    finally:
        try:
            connection.close()
        except Exception:
            pass


@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        role = request.form.get('role', '').strip()
        raw_password = request.form.get('password', '')
        password = raw_password.strip()
        code = (
            request.form.get('login_code', '').strip()
            or request.form.get('employee_id', '').strip()
            or request.form.get('admission_number', '').strip()
        )

        def render_login_error(message, parent_setup_hint=False, parent_setup_admission=''):
            return render_template(
                'login.html',
                default_role=role if role in ('employee', 'parent', 'student') else '',
                login_error=message,
                login_code=code,
                remember_me=bool(request.form.get('remember_me')),
                parent_setup_hint=parent_setup_hint,
                default_admission=(code.strip() if role == 'parent' else ''),
                parent_setup_admission=parent_setup_admission,
            )

        if not role:
            return render_login_error('Please select who you are signing in as.')
        if role not in ('employee', 'parent', 'student'):
            return render_login_error('Invalid role selected.')
        if not code:
            if role == 'parent':
                return render_login_error(
                    "Enter your child's student admission ID (the ID on the admission confirmation, e.g. STU001)."
                )
            return render_login_error('Please enter your six-digit code.')

        if role == 'employee':
            if not password:
                return render_login_error('Please enter your password.')
            if not code.isdigit() or len(code) != 6:
                return render_login_error('Your sign-in code must be exactly 6 digits.')
        elif role == 'student':
            if not password:
                return render_login_error('Please enter your password.')
            if not code.isdigit() or len(code) != 6:
                return render_login_error('Your sign-in code must be exactly 6 digits.')
        else:
            if not password:
                return render_login_error('Please enter your password.')
            adm_key = _normalize_parent_admission(code)
            if not _parent_admission_pattern_ok(adm_key):
                return render_login_error(
                    'Enter a valid admission ID (letters and numbers only, such as STU001).'
                )

        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    ensure_users_portal_login_schema(cursor)
                    connection.commit()
                    if role == 'employee':
                        cursor.execute(
                            "SELECT * FROM employees WHERE employee_id = %s",
                            (code,),
                        )
                        employee = cursor.fetchone()

                        if employee:
                            stored_hash = employee.get('password_hash') if isinstance(employee, dict) else None
                            password_ok = False
                            try:
                                if stored_hash:
                                    # Accept both exact entry and trimmed entry for compatibility.
                                    password_ok = check_password_hash(stored_hash, raw_password) or check_password_hash(stored_hash, password)
                            except Exception:
                                password_ok = False

                            # Legacy fallback: if a plaintext value is stored by mistake, migrate it on successful login.
                            if not password_ok and stored_hash and (stored_hash == raw_password or stored_hash == password):
                                try:
                                    with connection.cursor() as update_cursor:
                                        update_cursor.execute(
                                            "UPDATE employees SET password_hash = %s, updated_at = CURRENT_TIMESTAMP WHERE id = %s",
                                            (generate_password_hash(password), employee['id']),
                                        )
                                    connection.commit()
                                    password_ok = True
                                except Exception as migrate_err:
                                    print(f"Password hash migration failed: {migrate_err}")
                                    password_ok = False

                            if password_ok:
                                status = employee['status']

                                if status in ['pending', 'pending approval']:
                                    flash(
                                        'Your account is pending approval. Please review the terms and conditions.',
                                        'info',
                                    )
                                    return redirect(url_for('terms_and_conditions'))
                                if status in ['suspended', 'fired']:
                                    return render_login_error(
                                        'Your account has been suspended. Please contact the relevant authorities for assistance.'
                                    )
                                if status == 'retired':
                                    return render_login_error(
                                        'Thank you for your service! Your account has been retired.'
                                    )
                                if status == 'active':
                                    ensure_employee_roles_schema(cursor)
                                    allocated_roles = fetch_employee_allocated_roles(cursor, employee['id'])
                                    if not allocated_roles:
                                        allocated_roles = [
                                            normalize_allocated_role(employee.get('role')) or 'employee'
                                        ]
                                    remember_me = bool(request.form.get('remember_me'))
                                    if len(allocated_roles) == 1:
                                        complete_employee_login_session(
                                            employee, allocated_roles[0], remember_me=remember_me
                                        )
                                        flash(f'Welcome back, {employee["full_name"]}!', 'success')
                                        return redirect(employee_dashboard_path())
                                    session['auth_pending_employee_pk'] = employee['id']
                                    session['auth_pending_remember_me'] = remember_me
                                    return redirect(url_for('login_select_role'))
                                return render_login_error('Your account status is invalid. Please contact support.')
                            return render_login_error(
                                'Incorrect password. Check your password and try again, or use "Forgot password?" below.'
                            )
                        else:
                            return render_login_error(
                                'No employee account matches this code. Check your six-digit employee code and try again.'
                            )
                    elif role == 'parent':
                        user = _fetch_parent_portal_user(cursor, code)
                        if not user:
                            sp = _fetch_student_parent_by_admission(cursor, code)
                            if sp:
                                return render_template(
                                    'login.html',
                                    default_role='parent',
                                    login_error=(
                                        'No portal account is registered for this admission yet, or you still need to '
                                        'set your password. Use first-time parent setup: confirm your child\'s date of birth, '
                                        'then enter your email and choose a password.'
                                    ),
                                    login_code=code,
                                    remember_me=bool(request.form.get('remember_me')),
                                    parent_setup_hint=True,
                                    default_admission=code.strip(),
                                    parent_setup_admission=code.strip(),
                                )
                            return render_login_error(
                                'No parent portal account matches this admission ID. Check the ID or contact the school.'
                            )
                        if not (
                            check_password_hash(user['password_hash'], raw_password)
                            or check_password_hash(user['password_hash'], password)
                        ):
                            return render_login_error(
                                'Incorrect password. Check your password and try again, or use "Forgot password?" below.'
                            )
                        session.permanent = bool(request.form.get('remember_me'))
                        session['user_id'] = user['id']
                        session['email'] = user['email']
                        session['full_name'] = user['full_name']
                        session['role'] = user['role']
                        flash(f'Welcome back, {user["full_name"]}!', 'success')
                        return redirect(parent_dashboard_path())
                    else:
                        cursor.execute(
                            """
                            SELECT * FROM users WHERE role = %s AND (
                                (login_code IS NOT NULL AND login_code = %s)
                                OR (student_id IS NOT NULL AND (
                                    student_id = %s
                                    OR (CHAR_LENGTH(student_id) >= 6 AND RIGHT(student_id, 6) = %s)
                                ))
                            )
                            LIMIT 1
                            """,
                            (role, code, code, code),
                        )
                        user = cursor.fetchone()

                        if not user:
                            return render_login_error(
                                'No account matches this six-digit code for the role you selected. '
                                'If you were given a portal code, use that; students may also try the last six characters of their student ID.'
                            )
                        if not (
                            check_password_hash(user['password_hash'], raw_password)
                            or check_password_hash(user['password_hash'], password)
                        ):
                            return render_login_error(
                                'Incorrect password. Check your password and try again, or use "Forgot password?" below.'
                            )
                        session.permanent = bool(request.form.get('remember_me'))
                        session['user_id'] = user['id']
                        session['email'] = user['email']
                        session['full_name'] = user['full_name']
                        session['role'] = user['role']
                        flash(f'Welcome back, {user["full_name"]}!', 'success')
                        return redirect(student_dashboard_path())
            except Exception as e:
                print(f"Login error: {e}")
                return render_login_error('An error occurred during login. Please try again.')
            finally:
                if connection:
                    try:
                        connection.close()
                    except Exception:
                        pass
        else:
            return render_login_error('Database connection error. Please try again later.')

    # GET request — optional ?role=employee|parent|student
    role = request.args.get('role', '')
    if role not in ('employee', 'parent', 'student'):
        role = ''
    adm = (request.args.get('admission') or '').strip()
    return render_template(
        'login.html',
        default_role=role,
        login_code=adm,
        remember_me=False,
        parent_setup_hint=False,
        default_admission=adm,
        parent_setup_admission='',
        login_error=None,
    )


@app.route('/login/select-role', methods=['GET', 'POST'])
@app.route('/login-select-role', methods=['GET', 'POST'])
def login_select_role():
    """After employee credentials are verified, choose which allocated role to use for this session."""
    pending_pk = session.get('auth_pending_employee_pk')
    if not pending_pk:
        flash('Please sign in first.', 'info')
        return redirect(url_for('login', role='employee'))

    connection = get_db_connection()
    if not connection:
        flash('Database connection error. Please try again later.', 'error')
        return redirect(url_for('login', role='employee'))

    try:
        with connection.cursor() as cursor:
            ensure_employee_roles_schema(cursor)
            connection.commit()
            cursor.execute("SELECT * FROM employees WHERE id = %s", (pending_pk,))
            employee = cursor.fetchone()
            if not employee:
                session.pop('auth_pending_employee_pk', None)
                session.pop('auth_pending_remember_me', None)
                flash('Session expired. Please sign in again.', 'error')
                return redirect(url_for('login', role='employee'))

            status = (employee.get('status') or '').lower()
            if status not in ('active',):
                session.pop('auth_pending_employee_pk', None)
                session.pop('auth_pending_remember_me', None)
                flash('Your account is not active. Please contact the school.', 'error')
                return redirect(url_for('login', role='employee'))

            allocated_roles = fetch_employee_allocated_roles(cursor, employee['id'])
            if not allocated_roles:
                allocated_roles = [normalize_allocated_role(employee.get('role')) or 'employee']

            if request.method == 'POST':
                chosen = normalize_allocated_role(request.form.get('selected_role', ''))
                if chosen not in allocated_roles:
                    return render_template(
                        'login_select_role.html',
                        employee_name=employee.get('full_name', ''),
                        allocated_roles=allocated_roles,
                        select_error='Please choose one of your assigned roles.',
                    )
                remember_me = bool(session.get('auth_pending_remember_me'))
                complete_employee_login_session(employee, chosen, remember_me=remember_me)
                flash(f'Welcome back, {employee["full_name"]}!', 'success')
                return redirect(employee_dashboard_path())

            if len(allocated_roles) == 1:
                remember_me = bool(session.get('auth_pending_remember_me'))
                complete_employee_login_session(employee, allocated_roles[0], remember_me=remember_me)
                flash(f'Welcome back, {employee["full_name"]}!', 'success')
                return redirect(employee_dashboard_path())

            return render_template(
                'login_select_role.html',
                employee_name=employee.get('full_name', ''),
                allocated_roles=allocated_roles,
                select_error=None,
            )
    except Exception as e:
        print(f"login_select_role error: {e}")
        flash('An error occurred. Please try again.', 'error')
        return redirect(url_for('login', role='employee'))
    finally:
        try:
            connection.close()
        except Exception:
            pass


@app.route('/retrieve-password', methods=['GET', 'POST'])
def retrieve_password():
    """Request a verification code by email (matches employee or parent/student account automatically)."""
    generic_notice = (
        'If an account matches this email, we sent a verification code. Check your inbox (and spam).'
    )
    if request.method == 'POST':
        email = request.form.get('email', '').strip()
        if not email:
            flash('Please enter your email.', 'error')
            return redirect(url_for('retrieve_password'))

        account = lookup_account_for_password_reset(email)
        if not account:
            flash(generic_notice, 'info')
            return redirect(url_for('retrieve_password'))

        account_type = account['account_type']
        code = ''.join(secrets.choice('0123456789') for _ in range(6))
        code_hash = generate_password_hash(code)
        expires_at = datetime.utcnow() + timedelta(minutes=30)
        to_addr = account['email']

        if not send_password_reset_email(to_addr, account['full_name'], code):
            flash(
                'Could not send the verification email. Your school can set SMTP under Integration Settings, '
                'or the server administrator can set MAIL_* environment variables.',
                'error',
            )
            return redirect(url_for('retrieve_password'))

        connection = get_db_connection()
        if not connection:
            flash('Database connection error. Please try again later.', 'error')
            return redirect(url_for('retrieve_password'))
        try:
            with connection.cursor() as cursor:
                email_norm = normalize_login_email(email)
                cursor.execute("""
                    DELETE FROM password_reset_tokens
                    WHERE LOWER(TRIM(email)) = %s AND consumed_at IS NULL
                """, (email_norm,))
                cursor.execute("""
                    INSERT INTO password_reset_tokens (email, account_type, account_id, code_hash, expires_at)
                    VALUES (%s, %s, %s, %s, %s)
                """, (email_norm, account_type, account['id'], code_hash, expires_at))
                connection.commit()
        except Exception as e:
            print(f"retrieve_password token insert: {e}")
            try:
                connection.rollback()
            except Exception:
                pass
            flash('We could not save your reset request. Please try again.', 'error')
            return redirect(url_for('retrieve_password'))
        finally:
            try:
                connection.close()
            except Exception:
                pass

        session['pwd_reset_email'] = normalize_login_email(email)
        flash('We sent a code to your email. Enter it on the next page with your new password.', 'success')
        return redirect(url_for('reset_password'))

    return render_template('retrieve_password.html')


@app.route('/reset-password', methods=['GET', 'POST'])
def reset_password():
    """Enter verification code and set a new password."""
    if request.method == 'POST':
        email = normalize_login_email(request.form.get('email', ''))
        reset_code = (request.form.get('reset_code') or '').strip().replace(' ', '')
        new_password = request.form.get('new_password', '')
        confirm_password = request.form.get('confirm_password', '')

        def _render_form():
            return render_template('reset_password.html', preset_email=email)

        if not email:
            flash('Please enter the email you used when requesting the code.', 'error')
            return redirect(url_for('reset_password'))

        if not reset_code:
            flash('Please enter the verification code from your email.', 'error')
            return _render_form()

        if len(new_password) < 6:
            flash('Your new password must be at least 6 characters.', 'error')
            return _render_form()

        if new_password != confirm_password:
            flash('New password and confirmation do not match.', 'error')
            return _render_form()

        connection = get_db_connection()
        if not connection:
            flash('Database connection error. Please try again later.', 'error')
            return _render_form()
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT * FROM password_reset_tokens
                    WHERE LOWER(TRIM(email)) = %s AND consumed_at IS NULL AND expires_at > %s
                    ORDER BY id DESC LIMIT 1
                """, (email, datetime.utcnow()))
                token_row = cursor.fetchone()
                if not token_row or not check_password_hash(token_row['code_hash'], reset_code):
                    flash('Invalid or expired verification code. Request a new code from Retrieve password.', 'error')
                    return _render_form()

                account_type = token_row['account_type']
                new_hash = generate_password_hash(new_password)
                if account_type == 'employee':
                    cursor.execute(
                        "UPDATE employees SET password_hash = %s WHERE id = %s",
                        (new_hash, token_row['account_id']),
                    )
                else:
                    cursor.execute(
                        "UPDATE users SET password_hash = %s WHERE id = %s",
                        (new_hash, token_row['account_id']),
                    )
                cursor.execute(
                    "UPDATE password_reset_tokens SET consumed_at = %s WHERE id = %s",
                    (datetime.utcnow(), token_row['id']),
                )
                connection.commit()
        except Exception as e:
            print(f"reset_password error: {e}")
            try:
                connection.rollback()
            except Exception:
                pass
            flash('Could not update your password. Please try again.', 'error')
            return _render_form()
        finally:
            try:
                connection.close()
            except Exception:
                pass

        session.pop('pwd_reset_email', None)
        flash('Your password has been updated. You can sign in now.', 'success')
        return redirect(url_for('login'))

    preset_email = session.get('pwd_reset_email') or request.args.get('email', '').strip()
    return render_template('reset_password.html', preset_email=preset_email)


@app.route('/logout')
def logout():
    session.clear()
    flash('You have been logged out successfully.', 'success')
    return redirect(url_for('home'))

@app.route('/dashboard/parent')
@login_required
def dashboard_parent():
    """Parent dashboard - accessible to parents and technicians"""
    user_role = session.get('role', '').lower()
    viewing_as = session.get('viewing_as_role', '')
    
    # Allow access if user is parent OR if technician is viewing as parent
    if user_role != 'parent' and not (user_role == 'technician' and viewing_as == 'parent'):
        if user_role != 'technician':
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
    
    # Check if technician is viewing as parent
    is_technician = user_role == 'technician'
    current_view_role = viewing_as if is_technician and viewing_as else user_role
    
    # Get parent's email from session
    parent_email = session.get('email', '')
    
    # For technicians, fetch all students for selection
    all_students = []
    selected_student_id = request.args.get('student_id', '') or session.get('parent_view_student_id', '')
    
    if is_technician and viewing_as == 'parent':
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    cursor.execute("""
                        SELECT DISTINCT s.id, s.student_id, s.full_name, s.current_grade, s.status,
                               p.full_name as parent_name, p.email as parent_email
                        FROM students s
                        LEFT JOIN parents p ON s.student_id = p.student_id
                        WHERE s.status = 'in session'
                        ORDER BY s.full_name ASC
                    """)
                    all_students = cursor.fetchall()
            except Exception as e:
                print(f"Error fetching students for technician: {e}")
            finally:
                if connection:
                    try:
                        connection.close()
                    except:
                        pass
        
        # If a student is selected, use that student's parent email
        if selected_student_id:
            session['parent_view_student_id'] = selected_student_id
            connection = get_db_connection()
            if connection:
                try:
                    with connection.cursor() as cursor:
                        cursor.execute("""
                            SELECT p.email
                            FROM parents p
                            WHERE p.student_id = %s
                            LIMIT 1
                        """, (selected_student_id,))
                        parent_result = cursor.fetchone()
                        if parent_result:
                            parent_email = parent_result.get('email', '') if isinstance(parent_result, dict) else parent_result[0]
                except Exception as e:
                    print(f"Error fetching parent email: {e}")
                finally:
                    if connection:
                        try:
                            connection.close()
                        except:
                            pass
    
    # Parent home (/parent): spotlight student + analytics (fees, subjects, exams).
    spotlight_student = None
    spotlight_fee = None
    spotlight_subjects = []
    spotlight_exam = None
    spotlight_conn = get_db_connection()
    if spotlight_conn:
        try:
            with spotlight_conn.cursor() as spotlight_cursor:
                raw = _parent_dashboard_spotlight_student(
                    spotlight_cursor,
                    is_technician=is_technician,
                    viewing_as_parent=(viewing_as == 'parent'),
                    selected_student_id=selected_student_id,
                    parent_email=parent_email,
                    user_id=session.get('user_id'),
                )
                if raw:
                    row = dict(raw)
                    row['student_photo_url'] = None
                    if row.get('profile_image'):
                        try:
                            row['student_photo_url'] = url_for('static', filename=str(row['profile_image']))
                        except Exception:
                            row['student_photo_url'] = None
                    row.pop('profile_image', None)
                    spotlight_student = row
                    sid = spotlight_student.get('student_id')
                    if sid:
                        try:
                            spotlight_fee = _spotlight_fee_balance_for_student(spotlight_cursor, sid)
                        except Exception as fe:
                            print(f"dashboard_parent spotlight fee: {fe}")
                            spotlight_fee = {'has_structure': False}
                        try:
                            spotlight_subjects = _spotlight_subjects_for_student(spotlight_cursor, sid)
                        except Exception as se:
                            print(f"dashboard_parent spotlight subjects: {se}")
                            spotlight_subjects = []
        except Exception as e:
            print(f"dashboard_parent spotlight: {e}")
            spotlight_student = None
        finally:
            try:
                spotlight_conn.close()
            except Exception:
                pass

    if spotlight_student and spotlight_student.get('student_id'):
        try:
            ep = _fetch_student_progress_payload(spotlight_student['student_id'])
            by_ex = ep.get('by_exam') or []
            spotlight_exam = {
                'summary': ep.get('summary'),
                'by_subject': ep.get('by_subject') or [],
                'by_exam_recent': list(reversed(by_ex[-8:])) if by_ex else [],
            }
        except Exception as ee:
            print(f"dashboard_parent spotlight exam: {ee}")
            spotlight_exam = None

    library_student_id = (selected_student_id or '').strip()
    if not library_student_id and spotlight_student:
        library_student_id = (spotlight_student.get('student_id') or '').strip()

    return render_template('dashboards/dashboard_parent.html',
                         is_technician=is_technician,
                         current_view_role=current_view_role,
                         all_students=all_students if is_technician and viewing_as == 'parent' else [],
                         selected_student_id=selected_student_id,
                         library_student_id=library_student_id,
                         spotlight_student=spotlight_student,
                         spotlight_fee=spotlight_fee,
                         spotlight_subjects=spotlight_subjects,
                         spotlight_exam=spotlight_exam)

@app.route('/dashboard/parent/student-fees')
@login_required
def parent_student_fees():
    """Parent view of their children's fees - list all children with detailed fees"""
    user_role = session.get('role', '').lower()
    viewing_as = session.get('viewing_as_role', '')
    parent_email = session.get('email', '')
    
    # Allow access if user is parent OR if technician is viewing as parent
    if user_role != 'parent' and not (user_role == 'technician' and viewing_as == 'parent'):
        if user_role != 'technician':
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
    
    # For technicians, fetch all students for selection
    all_students = []
    selected_student_id = request.args.get('student_id', '') or session.get('parent_view_student_id', '')
    
    if user_role == 'technician' and viewing_as == 'parent':
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    cursor.execute("""
                        SELECT DISTINCT s.id, s.student_id, s.full_name, s.current_grade, s.status,
                               p.full_name as parent_name, p.email as parent_email
                        FROM students s
                        LEFT JOIN parents p ON s.student_id = p.student_id
                        WHERE s.status = 'in session'
                        ORDER BY s.full_name ASC
                    """)
                    all_students = cursor.fetchall()
            except Exception as e:
                print(f"Error fetching students for technician: {e}")
            finally:
                if connection:
                    try:
                        connection.close()
                    except:
                        pass
        
        # If a student is selected, use that student's parent email
        if selected_student_id:
            session['parent_view_student_id'] = selected_student_id
            connection = get_db_connection()
            if connection:
                try:
                    with connection.cursor() as cursor:
                        cursor.execute("""
                            SELECT p.email
                            FROM parents p
                            WHERE p.student_id = %s
                            LIMIT 1
                        """, (selected_student_id,))
                        parent_result = cursor.fetchone()
                        if parent_result:
                            parent_email = parent_result.get('email', '') if isinstance(parent_result, dict) else parent_result[0]
                except Exception as e:
                    print(f"Error fetching parent email: {e}")
                finally:
                    if connection:
                        try:
                            connection.close()
                        except:
                            pass
    
    # Fetch parent's children and their detailed fee information
    connection = get_db_connection()
    children = []
    
    if connection and parent_email:
        try:
            with connection.cursor() as cursor:
                # Get all students linked to this parent (by email)
                cursor.execute("""
                    SELECT DISTINCT s.id, s.student_id, s.full_name, s.current_grade, s.status, s.student_category,
                           p.full_name as parent_name, p.phone as parent_phone, p.email as parent_email
                    FROM students s
                    INNER JOIN parents p ON s.student_id = p.student_id
                    WHERE p.email = %s AND s.status = 'in session'
                    ORDER BY s.full_name ASC
                """, (parent_email,))
                results = cursor.fetchall()
                
                if results:
                    for row in results:
                        student_grade = row.get('current_grade', '')
                        student_id = row.get('student_id', '')
                        student_category = row.get('student_category', '').lower().strip() if row.get('student_category') else ''
                        
                        # Find the academic level for this student's grade
                        academic_level = None
                        fee_structure = None
                        fee_items = []
                        payments = []
                        total_paid = 0.0
                        balance = 0.0
                        
                        if student_grade:
                            # Try to match student's current_grade with academic_levels.level_name
                            cursor.execute("""
                                SELECT al.id, al.level_category, al.level_name, al.level_description
                                FROM academic_levels al
                                WHERE al.level_name = %s AND al.level_status = 'active'
                                LIMIT 1
                            """, (student_grade,))
                            level_result = cursor.fetchone()
                            
                            if level_result:
                                academic_level_id = level_result.get('id')
                                academic_level = {
                                    'id': academic_level_id,
                                    'level_category': level_result.get('level_category', ''),
                                    'level_name': level_result.get('level_name', ''),
                                    'level_description': level_result.get('level_description', '')
                                }
                                
                                # Find active fee structure for this academic level matching student category
                                if student_category == 'self sponsored':
                                    cursor.execute("""
                                        SELECT fs.id, fs.fee_name, fs.start_date, fs.end_date, 
                                               fs.payment_deadline, fs.total_amount, fs.status, fs.category
                                        FROM fee_structures fs
                                        WHERE fs.academic_level_id = %s 
                                          AND fs.status = 'active'
                                          AND (fs.category = 'self sponsored' OR fs.category = 'both')
                                        ORDER BY 
                                          CASE 
                                            WHEN fs.category = 'self sponsored' THEN 1
                                            WHEN fs.category = 'both' THEN 2
                                            ELSE 3
                                          END,
                                          fs.created_at DESC
                                        LIMIT 1
                                    """, (academic_level_id,))
                                elif student_category == 'sponsored':
                                    cursor.execute("""
                                        SELECT fs.id, fs.fee_name, fs.start_date, fs.end_date, 
                                               fs.payment_deadline, fs.total_amount, fs.status, fs.category
                                        FROM fee_structures fs
                                        WHERE fs.academic_level_id = %s 
                                          AND fs.status = 'active'
                                          AND (fs.category = 'sponsored' OR fs.category = 'both')
                                        ORDER BY 
                                          CASE 
                                            WHEN fs.category = 'sponsored' THEN 1
                                            WHEN fs.category = 'both' THEN 2
                                            ELSE 3
                                          END,
                                          fs.created_at DESC
                                        LIMIT 1
                                    """, (academic_level_id,))
                                elif student_category == 'both':
                                    cursor.execute("""
                                        SELECT fs.id, fs.fee_name, fs.start_date, fs.end_date, 
                                               fs.payment_deadline, fs.total_amount, fs.status, fs.category
                                        FROM fee_structures fs
                                        WHERE fs.academic_level_id = %s 
                                          AND fs.status = 'active'
                                        ORDER BY 
                                          CASE 
                                            WHEN fs.category = 'both' THEN 1
                                            WHEN fs.category = 'self sponsored' THEN 2
                                            WHEN fs.category = 'sponsored' THEN 3
                                            ELSE 4
                                          END,
                                          fs.created_at DESC
                                        LIMIT 1
                                    """, (academic_level_id,))
                                else:
                                    cursor.execute("""
                                        SELECT fs.id, fs.fee_name, fs.start_date, fs.end_date, 
                                               fs.payment_deadline, fs.total_amount, fs.status, fs.category
                                        FROM fee_structures fs
                                        WHERE fs.academic_level_id = %s 
                                          AND fs.status = 'active'
                                          AND fs.category = 'both'
                                        ORDER BY fs.created_at DESC
                                        LIMIT 1
                                    """, (academic_level_id,))
                                fee_structure_result = cursor.fetchone()
                                
                                if fee_structure_result:
                                    payment_deadline = fee_structure_result.get('payment_deadline')
                                    # Format payment_deadline if it's a date object
                                    if payment_deadline and hasattr(payment_deadline, 'strftime'):
                                        payment_deadline_formatted = payment_deadline.strftime('%B %d, %Y')
                                    elif payment_deadline:
                                        payment_deadline_formatted = str(payment_deadline)
                                    else:
                                        payment_deadline_formatted = None
                                    
                                    fee_structure = {
                                        'id': fee_structure_result.get('id'),
                                        'fee_name': fee_structure_result.get('fee_name'),
                                        'total_amount': float(fee_structure_result.get('total_amount', 0)),
                                        'payment_deadline': fee_structure_result.get('payment_deadline'),
                                        'payment_deadline_formatted': payment_deadline_formatted,
                                        'status': fee_structure_result.get('status')
                                    }
                                    
                                    # Get fee items
                                    cursor.execute("""
                                        SELECT item_name, item_description, amount
                                        FROM fee_items
                                        WHERE fee_structure_id = %s
                                        ORDER BY id ASC
                                    """, (fee_structure['id'],))
                                    fee_items_results = cursor.fetchall()
                                    fee_items = []
                                    for item in fee_items_results:
                                        if isinstance(item, dict):
                                            fee_items.append({
                                                'item_name': item.get('item_name', '') or '',
                                                'item_description': item.get('item_description', '') or '',
                                                'amount': float(item.get('amount', 0) or 0)
                                            })
                                        else:
                                            # Handle tuple/list format
                                            fee_items.append({
                                                'item_name': item[0] if len(item) > 0 else '',
                                                'item_description': item[1] if len(item) > 1 else '',
                                                'amount': float(item[2] if len(item) > 2 and item[2] else 0)
                                            })
                                    
                                    # Get payments
                                    cursor.execute("""
                                        SELECT amount_paid, payment_date, payment_method, reference_number, notes, created_at
                                        FROM student_payments
                                        WHERE student_id = %s
                                        ORDER BY payment_date DESC, created_at DESC
                                    """, (student_id,))
                                    payments_results = cursor.fetchall()
                                    payments = []
                                    for payment in payments_results:
                                        if isinstance(payment, dict):
                                            payment_date = payment.get('payment_date')
                                            # Format payment_date if it's a date object
                                            if payment_date and hasattr(payment_date, 'strftime'):
                                                payment_date_formatted = payment_date.strftime('%B %d, %Y')
                                            elif payment_date:
                                                payment_date_formatted = str(payment_date)
                                            else:
                                                payment_date_formatted = None
                                            
                                            payments.append({
                                                'amount_paid': float(payment.get('amount_paid', 0) or 0),
                                                'payment_date': payment_date,
                                                'payment_date_formatted': payment_date_formatted,
                                                'payment_method': payment.get('payment_method', '') or '',
                                                'reference_number': payment.get('reference_number', '') or '',
                                                'notes': payment.get('notes', '') or '',
                                                'created_at': payment.get('created_at')
                                            })
                                        else:
                                            # Handle tuple/list format
                                            try:
                                                payment_date = payment[1] if len(payment) > 1 else None
                                                # Format payment_date if it's a date object
                                                if payment_date and hasattr(payment_date, 'strftime'):
                                                    payment_date_formatted = payment_date.strftime('%B %d, %Y')
                                                elif payment_date:
                                                    payment_date_formatted = str(payment_date)
                                                else:
                                                    payment_date_formatted = None
                                                
                                                payments.append({
                                                    'amount_paid': float(payment[0] if len(payment) > 0 and payment[0] else 0),
                                                    'payment_date': payment_date,
                                                    'payment_date_formatted': payment_date_formatted,
                                                    'payment_method': payment[2] if len(payment) > 2 else '',
                                                    'reference_number': payment[3] if len(payment) > 3 else '',
                                                    'notes': payment[4] if len(payment) > 4 else '',
                                                    'created_at': payment[5] if len(payment) > 5 else None
                                                })
                                            except (IndexError, KeyError):
                                                # Skip invalid payment records
                                                continue
                                    
                                    # Calculate total paid
                                    cursor.execute("""
                                        SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                                        FROM student_payments
                                        WHERE student_id = %s
                                    """, (student_id,))
                                    payment_result = cursor.fetchone()
                                    total_paid = float(payment_result.get('total_paid', 0) if payment_result else 0)
                                    balance = fee_structure['total_amount'] - total_paid
                        
                        child_dict = {
                            'id': row.get('id'),
                            'student_id': student_id,
                            'full_name': row.get('full_name', ''),
                            'current_grade': student_grade,
                            'status': row.get('status', ''),
                            'academic_level': academic_level,
                            'fee_structure': fee_structure,
                            'fee_items': fee_items,
                            'payments': payments,
                            'total_paid': total_paid,
                            'balance': balance
                        }
                        children.append(child_dict)
        except Exception as e:
            print(f"Error fetching parent's children fees: {e}")
            import traceback
            traceback.print_exc()
            flash('Error loading fees information. Please try again.', 'error')
        finally:
            if connection:
                try:
                    connection.close()
                except:
                    pass
    
    return render_template('dashboards/parent_student_fees.html',
                         children=children,
                         is_technician=user_role == 'technician',
                         current_view_role=viewing_as if user_role == 'technician' and viewing_as else user_role,
                         all_students=all_students if user_role == 'technician' and viewing_as == 'parent' else [],
                         selected_student_id=selected_student_id)

