def _teacher_dashboard_analytics_empty():
    """Default shape for teacher dashboard KPIs (used when nothing computed or on error)."""
    return {
        'student_count': 0,
        'timetable_slot_count': 0,
        'distinct_class_group_count': 0,
        'attendance_present_cohort': 0,
        'attendance_entries_you_recorded': 0,
        'exams_supervise_duty_count': 0,
        'subject_rows': [],
        'class_rank_rows': [],
        'overall_mean': None,
        'overall_rank': None,
        'overall_teachers_count': 0,
    }


def _curriculum_coordinator_dashboard_analytics_empty():
    """Default shape for curriculum coordinator home dashboard charts."""
    return {
        'year_name': None,
        'term_name': None,
        'term_id': None,
        'active_levels_count': 0,
        'registered_subject_links': 0,
        'students_in_session': 0,
        'exam_rows_this_term': 0,
        'marks_entries_this_term': 0,
        'attendance_rows_this_term': 0,
        'attendance_present_this_term': 0,
        'attendance_absent_this_term': 0,
        'attendance_rate_pct': 0.0,
        'level_chart': {'labels': [], 'counts': []},
        'subject_chart': {'labels': [], 'means': []},
        'attendance_by_level_chart': {'labels': [], 'rates': []},
    }


def _fetch_curriculum_coordinator_dashboard_analytics(cursor):
    """School-wide snapshot for the coordinator dashboard (current term when available)."""
    out = _curriculum_coordinator_dashboard_analytics_empty()
    try:
        cursor.execute(
            """
            SELECT id, year_name
            FROM academic_years
            WHERE is_current = TRUE AND status = 'active'
            LIMIT 1
            """
        )
        year_row = cursor.fetchone()
        current_academic_year_id = None
        if year_row:
            current_academic_year_id = year_row.get('id') if isinstance(year_row, dict) else year_row[0]
            out['year_name'] = year_row.get('year_name') if isinstance(year_row, dict) else (year_row[1] if len(year_row) > 1 else None)

        current_term_id = None
        if current_academic_year_id:
            cursor.execute(
                """
                SELECT id, term_name
                FROM terms
                WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
                LIMIT 1
                """,
                (current_academic_year_id,),
            )
            term_row = cursor.fetchone()
            if not term_row:
                cursor.execute(
                    """
                    SELECT id, term_name FROM terms
                    WHERE status = 'active' AND academic_year_id = %s
                    ORDER BY id DESC
                    LIMIT 1
                    """,
                    (current_academic_year_id,),
                )
                term_row = cursor.fetchone()
            if term_row:
                current_term_id = term_row.get('id') if isinstance(term_row, dict) else term_row[0]
                out['term_name'] = term_row.get('term_name') if isinstance(term_row, dict) else (term_row[1] if len(term_row) > 1 else None)

        if not current_term_id:
            cursor.execute(
                """
                SELECT t.id, t.term_name, ay.year_name
                FROM terms t
                JOIN academic_years ay ON t.academic_year_id = ay.id
                WHERE t.status = 'active' AND ay.status = 'active'
                ORDER BY ay.is_current DESC, t.is_current DESC, t.id DESC
                LIMIT 1
                """
            )
            any_term = cursor.fetchone()
            if any_term:
                if isinstance(any_term, dict):
                    current_term_id = any_term.get('id')
                    out['term_name'] = out['term_name'] or any_term.get('term_name')
                    out['year_name'] = out['year_name'] or any_term.get('year_name')
                else:
                    current_term_id = any_term[0] if len(any_term) > 0 else None
                    out['term_name'] = out['term_name'] or (any_term[1] if len(any_term) > 1 else None)
                    out['year_name'] = out['year_name'] or (any_term[2] if len(any_term) > 2 else None)

        if current_term_id is not None:
            out['term_id'] = int(current_term_id)

        try:
            cursor.execute(
                """
                SELECT COUNT(*) AS c FROM academic_levels
                WHERE COALESCE(level_status, 'active') = 'active'
                """
            )
            r = cursor.fetchone()
            if r:
                out['active_levels_count'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
        except Exception:
            pass

        try:
            cursor.execute(
                """
                SELECT COUNT(*) AS c
                FROM subject_academic_levels sal
                INNER JOIN academic_levels al ON sal.academic_level_id = al.id
                INNER JOIN subjects s ON sal.subject_id = s.id
                WHERE COALESCE(al.level_status, 'active') = 'active'
                  AND COALESCE(s.status, 'active') = 'active'
                """
            )
            r = cursor.fetchone()
            if r:
                out['registered_subject_links'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
        except Exception:
            pass

        try:
            cursor.execute(
                """
                SELECT COUNT(*) AS c FROM students
                WHERE LOWER(TRIM(COALESCE(status, ''))) IN ('in session', 'active')
                """
            )
            r = cursor.fetchone()
            if r:
                out['students_in_session'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
        except Exception:
            pass

        if current_term_id is not None:
            try:
                cursor.execute(
                    "SELECT COUNT(*) AS c FROM exams WHERE term_id = %s",
                    (current_term_id,),
                )
                r = cursor.fetchone()
                if r:
                    out['exam_rows_this_term'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
            except Exception:
                pass
            try:
                cursor.execute(
                    """
                    SELECT COUNT(*) AS c
                    FROM student_marks sm
                    INNER JOIN exams e ON sm.exam_id = e.id
                    WHERE e.term_id = %s AND sm.marks IS NOT NULL
                    """,
                    (current_term_id,),
                )
                r = cursor.fetchone()
                if r:
                    out['marks_entries_this_term'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
            except Exception:
                pass

        try:
            cursor.execute(
                """
                SELECT al.level_name AS ln, COUNT(*) AS c
                FROM students st
                INNER JOIN academic_levels al
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al.level_name))
                WHERE LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                  AND COALESCE(al.level_status, 'active') = 'active'
                GROUP BY al.id, al.level_name
                ORDER BY al.level_name ASC
                """
            )
            for row in cursor.fetchall() or []:
                ln = row.get('ln') if isinstance(row, dict) else (row[0] if row else '')
                cv = row.get('c') if isinstance(row, dict) else (row[1] if len(row) > 1 else 0)
                if ln:
                    out['level_chart']['labels'].append(str(ln).strip()[:48])
                    out['level_chart']['counts'].append(int(cv or 0))
        except Exception:
            pass

        if not out['level_chart']['labels']:
            try:
                cursor.execute(
                    """
                    SELECT TRIM(st.current_grade) AS g, COUNT(*) AS c
                    FROM students st
                    WHERE LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                      AND TRIM(COALESCE(st.current_grade, '')) <> ''
                    GROUP BY TRIM(st.current_grade)
                    ORDER BY c DESC, g ASC
                    LIMIT 24
                    """
                )
                for row in cursor.fetchall() or []:
                    g = row.get('g') if isinstance(row, dict) else (row[0] if row else '')
                    cv = row.get('c') if isinstance(row, dict) else (row[1] if len(row) > 1 else 0)
                    if g:
                        out['level_chart']['labels'].append(str(g).strip()[:48])
                        out['level_chart']['counts'].append(int(cv or 0))
            except Exception:
                pass

        if current_term_id is not None:
            try:
                ensure_subject_exam_total_marks_column(cursor)
                cursor.execute(
                    """
                    SELECT sub.subject_name AS sn,
                           AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                               / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS mean_m,
                           COUNT(*) AS cnt
                    FROM student_marks sm
                    INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                    INNER JOIN subjects sub ON sm.subject_id = sub.id
                    INNER JOIN students st ON st.student_id = sm.student_id
                    WHERE sm.marks IS NOT NULL
                      AND LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                    GROUP BY sub.id, sub.subject_name
                    ORDER BY cnt DESC, sn ASC
                    LIMIT 12
                    """,
                    (current_term_id,),
                )
                for row in cursor.fetchall() or []:
                    sn = row.get('sn') if isinstance(row, dict) else (row[0] if row else '')
                    mean_m = row.get('mean_m') if isinstance(row, dict) else (row[1] if len(row) > 1 else None)
                    if not sn:
                        continue
                    try:
                        mf = round(float(mean_m), 2) if mean_m is not None else 0.0
                    except (TypeError, ValueError):
                        mf = 0.0
                    out['subject_chart']['labels'].append(str(sn).strip()[:40])
                    out['subject_chart']['means'].append(mf)
            except Exception:
                pass

            try:
                cursor.execute(
                    """
                    SELECT COUNT(*) AS c, COALESCE(SUM(sar.present), 0) AS pr
                    FROM student_attendance_records sar
                    INNER JOIN students st ON st.student_id = sar.student_id
                    WHERE sar.term_id = %s
                      AND LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                    """,
                    (int(current_term_id),),
                )
                r = cursor.fetchone()
                if r:
                    c = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
                    pr = int((r.get('pr') if isinstance(r, dict) else r[1]) or 0)
                    out['attendance_rows_this_term'] = c
                    out['attendance_present_this_term'] = pr
                    out['attendance_absent_this_term'] = max(0, c - pr)
                    out['attendance_rate_pct'] = round(100.0 * pr / c, 1) if c else 0.0
            except Exception:
                pass

            try:
                cursor.execute(
                    """
                    SELECT al.level_name AS ln, COUNT(*) AS tot, COALESCE(SUM(sar.present), 0) AS pr
                    FROM student_attendance_records sar
                    INNER JOIN academic_levels al ON sar.academic_level_id = al.id
                    INNER JOIN students st ON st.student_id = sar.student_id
                    WHERE sar.term_id = %s
                      AND LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                    GROUP BY al.id, al.level_name
                    ORDER BY al.level_name ASC
                    """,
                    (int(current_term_id),),
                )
                for row in cursor.fetchall() or []:
                    ln = row.get('ln') if isinstance(row, dict) else (row[0] if row else '')
                    tot = int((row.get('tot') if isinstance(row, dict) else row[1]) or 0)
                    pr = int((row.get('pr') if isinstance(row, dict) else row[2]) or 0)
                    if ln and tot > 0:
                        pct = round(100.0 * pr / tot, 1)
                        out['attendance_by_level_chart']['labels'].append(str(ln).strip()[:48])
                        out['attendance_by_level_chart']['rates'].append(pct)
            except Exception:
                pass
    except Exception as e:
        import traceback
        print(f"Error computing curriculum coordinator dashboard analytics: {e}")
        print(traceback.format_exc())
        return _curriculum_coordinator_dashboard_analytics_empty()
    return out


def ensure_student_attendance_records_table(cursor):
    """Daily student attendance (per class, term, date)."""
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS student_attendance_records (
                id INT AUTO_INCREMENT PRIMARY KEY,
                student_id VARCHAR(20) NOT NULL,
                attendance_date DATE NOT NULL,
                academic_level_id INT NOT NULL,
                term_id INT NOT NULL,
                present TINYINT(1) NOT NULL DEFAULT 1,
                recorded_by_employee_id INT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE KEY unique_student_date_level_term (
                    student_id, attendance_date, academic_level_id, term_id
                ),
                INDEX idx_student_date (student_id, attendance_date),
                INDEX idx_level_term_date (academic_level_id, term_id, attendance_date),
                INDEX idx_sar_term_recorded (term_id, recorded_by_employee_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
    except Exception as e:
        print(f"ensure_student_attendance_records_table: {e}")


def _compute_teacher_dashboard_analytics(cursor, teacher_id, term_id):
    """KPIs for the teacher home dashboard for the current term (marks, attendance, exams)."""
    empty = _teacher_dashboard_analytics_empty()
    try:
        teacher_id = int(teacher_id)
        term_id = int(term_id)
    except (TypeError, ValueError):
        return empty
    if not teacher_id or not term_id:
        return empty
    out = dict(empty)
    try:
        ensure_student_attendance_records_table(cursor)
        ensure_subject_exam_total_marks_column(cursor)
        cursor.execute(
            """
            SELECT DISTINCT academic_level_id AS lid FROM teacher_subject_assignments WHERE teacher_id = %s
            UNION
            SELECT DISTINCT academic_level_id AS lid FROM timetables WHERE teacher_id = %s AND term_id = %s
            """,
            (teacher_id, teacher_id, term_id),
        )
        level_ids = []
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                lid = r.get('lid') if r.get('lid') is not None else r.get('academic_level_id')
            else:
                lid = r[0] if r else None
            if lid is not None:
                try:
                    level_ids.append(int(lid))
                except (TypeError, ValueError):
                    continue
        level_ids = list(dict.fromkeys(level_ids))

        if level_ids:
            ph = ','.join(['%s'] * len(level_ids))
            # Resolve cohort level: academic_level_id when set, else map current_grade -> academic_levels.
            # (Marks queries must use the same rule or subject means / ranks stay empty.)
            try:
                cursor.execute(
                    f"""
                    SELECT COUNT(DISTINCT s.student_id) AS c
                    FROM students s
                    LEFT JOIN academic_levels al_sg
                      ON TRIM(LOWER(s.current_grade)) = TRIM(LOWER(al_sg.level_name))
                    WHERE s.status = 'in session'
                      AND COALESCE(s.academic_level_id, al_sg.id) IN ({ph})
                    """,
                    level_ids,
                )
                rr = cursor.fetchone()
                if rr:
                    out['student_count'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)
            except Exception:
                cursor.execute(
                    f"""
                    SELECT COUNT(DISTINCT s.student_id) AS c
                    FROM students s
                    INNER JOIN academic_levels al
                      ON TRIM(LOWER(s.current_grade)) = TRIM(LOWER(al.level_name))
                    WHERE s.status = 'in session' AND al.id IN ({ph})
                    """,
                    level_ids,
                )
                rr = cursor.fetchone()
                if rr:
                    out['student_count'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)

            try:
                cursor.execute(
                    f"""
                    SELECT COUNT(*) AS c FROM student_attendance_records sar
                    INNER JOIN students s ON s.student_id = sar.student_id AND s.status = 'in session'
                    LEFT JOIN academic_levels al_sg
                      ON TRIM(LOWER(s.current_grade)) = TRIM(LOWER(al_sg.level_name))
                    WHERE sar.term_id = %s AND sar.present = 1
                      AND COALESCE(s.academic_level_id, al_sg.id) IN ({ph})
                    """,
                    [term_id] + level_ids,
                )
                rr = cursor.fetchone()
                if rr:
                    out['attendance_present_cohort'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)
            except Exception:
                cursor.execute(
                    f"""
                    SELECT COUNT(*) AS c
                    FROM student_attendance_records sar
                    INNER JOIN students s
                      ON s.student_id = sar.student_id AND s.status = 'in session'
                    INNER JOIN academic_levels al
                      ON TRIM(LOWER(s.current_grade)) = TRIM(LOWER(al.level_name))
                    WHERE sar.term_id = %s AND sar.present = 1 AND al.id IN ({ph})
                    """,
                    [term_id] + level_ids,
                )
                rr = cursor.fetchone()
                if rr:
                    out['attendance_present_cohort'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)

        try:
            cursor.execute(
                """
                SELECT COUNT(*) AS c FROM student_attendance_records
                WHERE term_id = %s AND recorded_by_employee_id = %s
                """,
                (term_id, teacher_id),
            )
            rr = cursor.fetchone()
            if rr:
                out['attendance_entries_you_recorded'] = int(
                    (rr.get('c') if isinstance(rr, dict) else rr[0]) or 0
                )
        except Exception as att_rec_e:
            print(f"Teacher dashboard attendance_entries skipped: {att_rec_e}")

        cursor.execute(
            """
            SELECT COUNT(DISTINCT CONCAT(day_of_week,'|',time_slot,'|',academic_level_id,'|',IFNULL(subject_id,0))) AS c
            FROM timetables WHERE teacher_id = %s AND term_id = %s
            """,
            (teacher_id, term_id),
        )
        rr = cursor.fetchone()
        if rr:
            out['timetable_slot_count'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)

        cursor.execute(
            """
            SELECT COUNT(DISTINCT CONCAT(academic_level_id,'|',IFNULL(subject_id,0))) AS c
            FROM timetables WHERE teacher_id = %s AND term_id = %s
            """,
            (teacher_id, term_id),
        )
        rr = cursor.fetchone()
        if rr:
            out['distinct_class_group_count'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)

        sup_count = 0
        try:
            cursor.execute(
                """
                SELECT COUNT(DISTINCT e.id) AS c FROM exams e
                WHERE e.term_id = %s
                  AND (e.status IS NULL OR e.status != 'cancelled')
                  AND (
                        e.supervisor_id = %s
                        OR EXISTS (
                            SELECT 1 FROM exam_supervisors es
                            WHERE es.exam_id = e.id AND es.supervisor_id = %s
                        )
                      )
                """,
                (term_id, teacher_id, teacher_id),
            )
            rr = cursor.fetchone()
            if rr:
                sup_count = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)
        except Exception as sup_e:
            try:
                cursor.execute(
                    """
                    SELECT COUNT(DISTINCT e.id) AS c FROM exams e
                    WHERE e.term_id = %s
                      AND (e.status IS NULL OR e.status != 'cancelled')
                      AND e.supervisor_id = %s
                    """,
                    (term_id, teacher_id),
                )
                rr = cursor.fetchone()
                if rr:
                    sup_count = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)
            except Exception as sup_e2:
                print(f"Teacher dashboard exam supervisor count skipped: {sup_e} / {sup_e2}")
        out['exams_supervise_duty_count'] = sup_count

        try:
            cursor.execute(
                """
                SELECT sub.subject_name, sub.subject_code,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS mean_marks,
                       COUNT(sm.marks) AS mark_count
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                LEFT JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN teacher_subject_assignments tsa
                  ON tsa.teacher_id = %s
                 AND tsa.subject_id = sm.subject_id
                 AND tsa.academic_level_id = COALESCE(st.academic_level_id, al_st.id)
                WHERE sm.marks IS NOT NULL
                GROUP BY sub.id, sub.subject_name, sub.subject_code
                ORDER BY sub.subject_name
                """,
                (term_id, teacher_id),
            )
        except Exception:
            cursor.execute(
                """
                SELECT sub.subject_name, sub.subject_code,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS mean_marks,
                       COUNT(sm.marks) AS mark_count
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                INNER JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN teacher_subject_assignments tsa
                  ON tsa.teacher_id = %s
                 AND tsa.subject_id = sm.subject_id
                 AND tsa.academic_level_id = al_st.id
                WHERE sm.marks IS NOT NULL
                GROUP BY sub.id, sub.subject_name, sub.subject_code
                ORDER BY sub.subject_name
                """,
                (term_id, teacher_id),
            )
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                mean_m = r.get('mean_marks')
                cnt = r.get('mark_count')
                sn = r.get('subject_name') or ''
                sc = r.get('subject_code') or ''
            else:
                mean_m = r[2] if len(r) > 2 else None
                cnt = r[3] if len(r) > 3 else 0
                sn = r[0] if len(r) > 0 else ''
                sc = r[1] if len(r) > 1 else ''
            try:
                mean_f = round(float(mean_m), 2) if mean_m is not None else None
            except (TypeError, ValueError):
                mean_f = None
            out['subject_rows'].append({
                'subject_name': sn,
                'subject_code': sc,
                'mean_marks': mean_f,
                'mark_count': int(cnt or 0),
            })

        try:
            cursor.execute(
                """
                SELECT COALESCE(st.academic_level_id, al_st.id) AS academic_level_id, al.level_name,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS avg_m, COUNT(*) AS cnt
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                LEFT JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN academic_levels al ON al.id = COALESCE(st.academic_level_id, al_st.id)
                WHERE sm.marks IS NOT NULL
                GROUP BY COALESCE(st.academic_level_id, al_st.id), al.level_name
                """,
                (term_id,),
            )
        except Exception:
            cursor.execute(
                """
                SELECT al_st.id AS academic_level_id, al.level_name,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS avg_m, COUNT(*) AS cnt
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                INNER JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN academic_levels al ON al.id = al_st.id
                WHERE sm.marks IS NOT NULL
                GROUP BY al_st.id, al.level_name
                """,
                (term_id,),
            )
        level_avgs = []
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                lid = r.get('academic_level_id')
                lname = r.get('level_name') or ''
                avg_m = r.get('avg_m')
                cnt = r.get('cnt')
            else:
                lid = r[0] if len(r) > 0 else None
                lname = r[1] if len(r) > 1 else ''
                avg_m = r[2] if len(r) > 2 else None
                cnt = r[3] if len(r) > 3 else 0
            try:
                avg_f = float(avg_m) if avg_m is not None else None
            except (TypeError, ValueError):
                avg_f = None
            if lid is not None and avg_f is not None:
                level_avgs.append({
                    'academic_level_id': int(lid),
                    'level_name': lname,
                    'avg_m': avg_f,
                    'cnt': int(cnt or 0),
                })

        level_avgs.sort(key=lambda x: x['avg_m'], reverse=True)
        total_levels = len(level_avgs)
        last_avg = None
        rank_i = 0
        for idx, row in enumerate(level_avgs):
            if last_avg is None or row['avg_m'] < last_avg:
                rank_i = idx + 1
            row['school_rank'] = rank_i
            last_avg = row['avg_m']

        taught_set = set(level_ids)
        for row in level_avgs:
            if row['academic_level_id'] in taught_set:
                out['class_rank_rows'].append({
                    'level_name': row['level_name'],
                    'avg_m': round(row['avg_m'], 2),
                    'mark_count': row['cnt'],
                    'school_rank': row['school_rank'],
                    'levels_compared': total_levels,
                })

        try:
            cursor.execute(
                """
                SELECT tsa.teacher_id,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS avg_m
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                LEFT JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN teacher_subject_assignments tsa
                  ON tsa.subject_id = sm.subject_id
                 AND tsa.academic_level_id = COALESCE(st.academic_level_id, al_st.id)
                WHERE sm.marks IS NOT NULL
                GROUP BY tsa.teacher_id
                """,
                (term_id,),
            )
        except Exception:
            cursor.execute(
                """
                SELECT tsa.teacher_id,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS avg_m
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                INNER JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN teacher_subject_assignments tsa
                  ON tsa.subject_id = sm.subject_id AND tsa.academic_level_id = al_st.id
                WHERE sm.marks IS NOT NULL
                GROUP BY tsa.teacher_id
                """,
                (term_id,),
            )
        teacher_avgs = []
        for r in cursor.fetchall() or []:
            tid = r.get('teacher_id') if isinstance(r, dict) else (r[0] if r else None)
            avg_m = r.get('avg_m') if isinstance(r, dict) else (r[1] if len(r) > 1 else None)
            if tid is None:
                continue
            try:
                teacher_avgs.append({'teacher_id': int(tid), 'avg_m': float(avg_m)})
            except (TypeError, ValueError):
                continue
        teacher_avgs.sort(key=lambda x: x['avg_m'], reverse=True)
        out['overall_teachers_count'] = len(teacher_avgs)
        last_t = None
        trank = 0
        for idx, row in enumerate(teacher_avgs):
            if last_t is None or row['avg_m'] < last_t:
                trank = idx + 1
            row['rank'] = trank
            last_t = row['avg_m']
        for row in teacher_avgs:
            if row['teacher_id'] == teacher_id:
                out['overall_mean'] = round(row['avg_m'], 2)
                out['overall_rank'] = row['rank']
                break
    except Exception as e:
        import traceback
        print(f"Error computing teacher dashboard analytics: {e}")
        print(traceback.format_exc())
        # Return partial metrics if some queries succeeded before the failure
        return out
    return out


@app.route('/dashboard/employee')
@login_required
def dashboard_employee():
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check if user is a teacher (either actual role or viewing as teacher)
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    
    if user_role not in EMPLOYEE_SUB_ROLES:
        flash('You do not have permission to access this page.', 'error')
        return redirect(url_for('home'))
    
    # Get employee data for profile picture
    connection = get_db_connection()
    employee_data = {}
    if connection:
        try:
            with connection.cursor() as cursor:
                employee_id = session.get('employee_id') or session.get('user_id')
                cursor.execute("SELECT * FROM employees WHERE id = %s OR employee_id = %s", 
                             (employee_id, employee_id))
                employee = cursor.fetchone()
                if employee:
                    employee_data = employee
        except Exception as e:
            print(f"Error fetching employee data: {e}")
        finally:
            connection.close()
    
    # Check if user is technician (for role switching)
    is_technician = user_role == 'technician'
    current_view_role = session.get('viewing_as_role', user_role)
    current_employee_role = session.get('viewing_as_employee_role', user_role if user_role in EMPLOYEE_SUB_ROLES else 'employee')
    dashboard_content_role = normalize_employee_dashboard_content_role(
        user_role, is_technician, session.get('viewing_as_employee_role')
    )
    is_teacher_view = dashboard_content_role in ('teacher', 'teachers')
    
    # List of all employee roles for technician to view
    employee_roles_list = list(EMPLOYEE_SUB_ROLES)

    teacher_dashboard_name = None
    teacher_dashboard_term = None
    teacher_dashboard_year = None
    teacher_class_timetable = []
    teacher_timetable_grid = {}
    teacher_exam_timetable = []
    teacher_dashboard_analytics = _teacher_dashboard_analytics_empty()
    timetable_days_order = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']

    is_coordinator_view = dashboard_content_role == 'curriculum coordinator'
    coordinator_dashboard = _curriculum_coordinator_dashboard_analytics_empty()
    coordinator_dashboard_name = None
    if isinstance(employee_data, dict):
        coordinator_dashboard_name = employee_data.get('full_name') or employee_data.get('name')
    if not coordinator_dashboard_name:
        coordinator_dashboard_name = session.get('full_name')

    if is_coordinator_view:
        cc_conn = get_db_connection()
        if cc_conn:
            try:
                with cc_conn.cursor() as cursor:
                    coordinator_dashboard = _fetch_curriculum_coordinator_dashboard_analytics(cursor)
            except Exception as ce:
                print(f"Curriculum coordinator dashboard load: {ce}")
                coordinator_dashboard = _curriculum_coordinator_dashboard_analytics_empty()
            finally:
                cc_conn.close()

    if is_teacher_view:
        sess_teacher_ref = session.get('viewing_as_employee_id') if is_technician else session.get('user_id')
        portal_employee_code = session.get('employee_id')
        if sess_teacher_ref or portal_employee_code:
            teacher_conn = get_db_connection()
            if teacher_conn:
                try:
                    with teacher_conn.cursor() as cursor:
                        cursor.execute("""
                            SELECT id, full_name
                            FROM employees
                            WHERE id = %s OR employee_id = %s
                            LIMIT 1
                        """, (sess_teacher_ref, portal_employee_code or sess_teacher_ref))
                        teacher_row = cursor.fetchone()
                        if not teacher_row and portal_employee_code:
                            cursor.execute("""
                                SELECT id, full_name
                                FROM employees
                                WHERE employee_id = %s
                                LIMIT 1
                            """, (str(portal_employee_code).strip(),))
                            teacher_row = cursor.fetchone()
                        if not teacher_row and sess_teacher_ref is not None:
                            sid = str(sess_teacher_ref).strip()
                            cursor.execute("""
                                SELECT id, full_name
                                FROM employees
                                WHERE CAST(id AS CHAR) = %s OR employee_id = %s
                                LIMIT 1
                            """, (sid, sid))
                            teacher_row = cursor.fetchone()
                        teacher_id = None
                        teacher_dashboard_name = None
                        if teacher_row:
                            pk = teacher_row.get('id') if isinstance(teacher_row, dict) else teacher_row[0]
                            try:
                                teacher_id = int(pk)
                            except (TypeError, ValueError):
                                teacher_id = None
                            teacher_dashboard_name = (
                                teacher_row.get('full_name') if isinstance(teacher_row, dict) else teacher_row[1]
                            )
                        if teacher_id is None and sess_teacher_ref is not None:
                            try:
                                teacher_id = int(sess_teacher_ref)
                            except (TypeError, ValueError):
                                teacher_id = None

                        current_academic_year_id = None
                        current_term_id = None

                        cursor.execute("""
                            SELECT id, year_name
                            FROM academic_years
                            WHERE is_current = TRUE AND status = 'active'
                            LIMIT 1
                        """)
                        year_row = cursor.fetchone()
                        if year_row:
                            current_academic_year_id = year_row.get('id') if isinstance(year_row, dict) else year_row[0]
                            teacher_dashboard_year = year_row.get('year_name') if isinstance(year_row, dict) else year_row[1]

                        if current_academic_year_id:
                            cursor.execute("""
                                SELECT id, term_name
                                FROM terms
                                WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
                                LIMIT 1
                            """, (current_academic_year_id,))
                            term_row = cursor.fetchone()
                            if not term_row:
                                cursor.execute("""
                                    SELECT id, term_name FROM terms
                                    WHERE status = 'active' AND academic_year_id = %s
                                    ORDER BY id DESC
                                    LIMIT 1
                                """, (current_academic_year_id,))
                                term_row = cursor.fetchone()
                            if term_row:
                                current_term_id = term_row.get('id') if isinstance(term_row, dict) else term_row[0]
                                teacher_dashboard_term = term_row.get('term_name') if isinstance(term_row, dict) else term_row[1]

                        if not current_term_id:
                            cursor.execute("""
                                SELECT t.id, t.term_name, ay.year_name
                                FROM terms t
                                JOIN academic_years ay ON t.academic_year_id = ay.id
                                WHERE t.status = 'active' AND ay.status = 'active'
                                ORDER BY ay.is_current DESC, t.is_current DESC, t.id DESC
                                LIMIT 1
                            """)
                            any_term = cursor.fetchone()
                            if any_term:
                                if isinstance(any_term, dict):
                                    current_term_id = any_term.get('id')
                                    teacher_dashboard_term = any_term.get('term_name')
                                    if not teacher_dashboard_year:
                                        teacher_dashboard_year = any_term.get('year_name')
                                else:
                                    current_term_id = any_term[0] if len(any_term) > 0 else None
                                    teacher_dashboard_term = any_term[1] if len(any_term) > 1 else None
                                    if not teacher_dashboard_year and len(any_term) > 2:
                                        teacher_dashboard_year = any_term[2]

                        # Students table doesn't store academic_level_id; it stores a grade label in current_grade.
                        # Map "in session" counts to academic_levels via current_grade -> level_name.
                        in_session_by_level = {}
                        try:
                            cursor.execute("""
                                SELECT al.id AS academic_level_id, COUNT(*) AS in_session_count
                                FROM students st
                                JOIN academic_levels al
                                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al.level_name))
                                WHERE st.status = 'in session'
                                GROUP BY al.id
                            """)
                            for row in (cursor.fetchall() or []):
                                level_id = row.get('academic_level_id') if isinstance(row, dict) else (row[0] if len(row) > 0 else None)
                                count_val = row.get('in_session_count', 0) if isinstance(row, dict) else (row[1] if len(row) > 1 else 0)
                                if level_id is not None:
                                    in_session_by_level[level_id] = int(count_val or 0)
                        except Exception as _isle:
                            print(f"Teacher dashboard in_session_by_level skipped: {_isle}")

                        if current_term_id and teacher_id:
                            try:
                                teacher_dashboard_analytics = _compute_teacher_dashboard_analytics(
                                    cursor, teacher_id, current_term_id
                                )
                            except Exception as ae:
                                import traceback
                                print(f"Error computing teacher dashboard analytics (early): {ae}")
                                print(traceback.format_exc())
                                teacher_dashboard_analytics = _teacher_dashboard_analytics_empty()

                            cursor.execute("""
                                SELECT DISTINCT t.id, t.day_of_week, t.time_slot, al.level_name,
                                       t.academic_level_id, s.subject_name, s.subject_code
                                FROM timetables t
                                LEFT JOIN academic_levels al ON t.academic_level_id = al.id
                                LEFT JOIN subjects s ON t.subject_id = s.id
                                WHERE t.teacher_id = %s AND t.term_id = %s
                                ORDER BY
                                    FIELD(t.day_of_week, 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'),
                                    t.time_slot
                            """, (teacher_id, current_term_id))
                            for row in (cursor.fetchall() or []):
                                if isinstance(row, dict):
                                    day = row.get('day_of_week', '')
                                    time = row.get('time_slot', '')
                                    level_name = row.get('level_name', '')
                                    level_id = row.get('academic_level_id')
                                    subject_name = row.get('subject_name') or 'No Subject Assigned'
                                    subject_code = row.get('subject_code') or ''
                                else:
                                    day = row[1] if len(row) > 1 else ''
                                    time = row[2] if len(row) > 2 else ''
                                    level_name = row[3] if len(row) > 3 else ''
                                    level_id = row[4] if len(row) > 4 else None
                                    subject_name = (row[5] if len(row) > 5 and row[5] else 'No Subject Assigned')
                                    subject_code = row[6] if len(row) > 6 and row[6] else ''

                                in_cnt = in_session_by_level.get(level_id, 0)
                                slot = {
                                    'level_name': level_name,
                                    'subject_name': subject_name,
                                    'subject_code': subject_code,
                                    'academic_level_id': level_id,
                                    'in_session_count': in_cnt,
                                }
                                teacher_class_timetable.append({
                                    'day': day,
                                    'time': time,
                                    'level_name': level_name,
                                    'subject_name': subject_name,
                                    'subject_code': subject_code,
                                    'in_session_count': in_cnt,
                                })
                                if day and time:
                                    teacher_timetable_grid.setdefault(day, {}).setdefault(time, []).append(slot)

                            cursor.execute("""
                                SELECT e.exam_name, e.exam_date, e.start_time, e.end_time, e.session_type,
                                       al.level_name, s.subject_name, s.subject_code, ay.year_name, tm.term_name,
                                       (CASE
                                         WHEN e.supervisor_id = %s THEN 'Supervisor'
                                         WHEN EXISTS (
                                           SELECT 1 FROM exam_supervisors es
                                           WHERE es.exam_id = e.id AND es.supervisor_id = %s
                                         ) THEN 'Exam duty'
                                         ELSE 'Your class'
                                       END) AS involvement
                                FROM exams e
                                LEFT JOIN academic_levels al ON e.academic_level_id = al.id
                                LEFT JOIN subjects s ON e.subject_id = s.id
                                LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
                                LEFT JOIN terms tm ON e.term_id = tm.id
                                WHERE e.term_id = %s
                                  AND (e.status IS NULL OR e.status != 'cancelled')
                                  AND (
                                        e.supervisor_id = %s
                                        OR EXISTS (
                                            SELECT 1 FROM exam_supervisors es
                                            WHERE es.exam_id = e.id AND es.supervisor_id = %s
                                        )
                                        OR EXISTS (
                                            SELECT 1 FROM teacher_subject_assignments tsa
                                            WHERE tsa.teacher_id = %s
                                              AND tsa.academic_level_id = e.academic_level_id
                                              AND (e.subject_id IS NULL OR tsa.subject_id = e.subject_id)
                                        )
                                      )
                                ORDER BY e.exam_date ASC, e.start_time ASC
                            """, (teacher_id, teacher_id, current_term_id, teacher_id, teacher_id, teacher_id))
                            for row in (cursor.fetchall() or []):
                                if isinstance(row, dict):
                                    exam_date = row.get('exam_date')
                                    exam_date_str = exam_date.strftime('%Y-%m-%d') if exam_date and hasattr(exam_date, 'strftime') else (str(exam_date) if exam_date else '')
                                    teacher_exam_timetable.append({
                                        'exam_name': row.get('exam_name', ''),
                                        'exam_date': exam_date_str,
                                        'start_time': row.get('start_time', ''),
                                        'end_time': row.get('end_time', ''),
                                        'session_type': row.get('session_type', ''),
                                        'level_name': row.get('level_name', ''),
                                        'subject_name': row.get('subject_name', ''),
                                        'subject_code': row.get('subject_code', ''),
                                        'year_name': row.get('year_name', ''),
                                        'term_name': row.get('term_name', ''),
                                        'involvement': row.get('involvement', ''),
                                    })
                                else:
                                    exam_date = row[1] if len(row) > 1 else None
                                    exam_date_str = exam_date.strftime('%Y-%m-%d') if exam_date and hasattr(exam_date, 'strftime') else (str(exam_date) if exam_date else '')
                                    teacher_exam_timetable.append({
                                        'exam_name': row[0] if len(row) > 0 else '',
                                        'exam_date': exam_date_str,
                                        'start_time': row[2] if len(row) > 2 else '',
                                        'end_time': row[3] if len(row) > 3 else '',
                                        'session_type': row[4] if len(row) > 4 else '',
                                        'level_name': row[5] if len(row) > 5 else '',
                                        'subject_name': row[6] if len(row) > 6 else '',
                                        'subject_code': row[7] if len(row) > 7 else '',
                                        'year_name': row[8] if len(row) > 8 else '',
                                        'term_name': row[9] if len(row) > 9 else '',
                                        'involvement': row[10] if len(row) > 10 else '',
                                    })
                except Exception as e:
                    import traceback
                    print(f"Error loading teacher dashboard timetable data: {e}")
                    print(traceback.format_exc())
                finally:
                    teacher_conn.close()

    accountant_dashboard = _accountant_dashboard_analytics_empty()
    if dashboard_content_role == 'accountant':
        acc_conn = get_db_connection()
        if acc_conn:
            try:
                with acc_conn.cursor() as cursor:
                    accountant_dashboard = _fetch_accountant_dashboard_analytics(cursor)
            except Exception as acc_err:
                print(f"Accountant dashboard analytics load: {acc_err}")
                accountant_dashboard = _accountant_dashboard_analytics_empty()
            finally:
                acc_conn.close()
    
    return render_template('dashboards/dashboard_employee.html', 
                         role=session.get('role', 'employee'),
                         employee=employee_data,
                         is_technician=is_technician,
                         current_view_role=current_view_role,
                         current_employee_role=current_employee_role,
                         dashboard_content_role=dashboard_content_role,
                         employee_roles_list=employee_roles_list,
                         teacher_dashboard_name=teacher_dashboard_name,
                         teacher_dashboard_term=teacher_dashboard_term,
                         teacher_dashboard_year=teacher_dashboard_year,
                         teacher_class_timetable=teacher_class_timetable,
                         teacher_timetable_grid=teacher_timetable_grid,
                         timetable_days_order=timetable_days_order,
                         teacher_exam_timetable=teacher_exam_timetable,
                         teacher_dashboard_analytics=teacher_dashboard_analytics,
                         coordinator_dashboard=coordinator_dashboard,
                         coordinator_dashboard_name=coordinator_dashboard_name,
                         accountant_dashboard=accountant_dashboard)


