@app.route('/dashboard/employee/grades-registration')
@login_required
def grades_registration():
    """Register grade codes per level (defaults) and per-subject overrides."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    schedule_management_roles = ['curriculum coordinator', 'head of institution', 'deputy head of institution', 'super admin', 'accountant', 'technician']
    effective_role = viewing_as_role if user_role == 'technician' and viewing_as_role else user_role
    if effective_role not in schedule_management_roles:
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    connection = get_db_connection()
    academic_levels = []
    level_subjects = []
    default_grades = []
    subject_overrides = []
    active_subjects = []
    subject_grade_mark_overrides = []
    subject_grade_allocations = []

    if connection:
        try:
            with connection.cursor() as cursor:
                # Load levels robustly across old/new schemas.
                try:
                    cursor.execute("""
                        SELECT id, level_name, level_category
                        FROM academic_levels
                        WHERE COALESCE(level_status, 'active') = 'active'
                        ORDER BY level_category, level_name
                    """)
                    academic_levels = cursor.fetchall() or []
                except Exception:
                    # Fallback for older schema using `status` instead of `level_status`.
                    try:
                        cursor.execute("""
                            SELECT id, level_name, level_category
                            FROM academic_levels
                            WHERE COALESCE(status, 'active') = 'active'
                            ORDER BY level_category, level_name
                        """)
                        academic_levels = cursor.fetchall() or []
                    except Exception:
                        cursor.execute("""
                            SELECT id, level_name, level_category
                            FROM academic_levels
                            ORDER BY level_category, level_name
                        """)
                        academic_levels = cursor.fetchall() or []

                cursor.execute("""
                    SELECT DISTINCT
                        tsa.academic_level_id,
                        al.level_name,
                        s.id AS subject_id,
                        s.subject_name,
                        s.subject_code
                    FROM teacher_subject_assignments tsa
                    INNER JOIN academic_levels al ON al.id = tsa.academic_level_id
                    INNER JOIN subjects s ON s.id = tsa.subject_id
                    ORDER BY al.level_name, s.subject_name
                """)
                level_subjects = cursor.fetchall() or []

                cursor.execute("""
                    SELECT
                        gr.id,
                        gr.academic_level_id,
                        al.level_name,
                        gr.start_mark,
                        gr.end_mark,
                        gr.level_label,
                        gr.code,
                        gr.meaning,
                        gr.description,
                        gr.allocation_points
                    FROM grade_registrations gr
                    LEFT JOIN academic_levels al ON al.id = gr.academic_level_id
                    ORDER BY COALESCE(gr.start_mark, -1) DESC, COALESCE(gr.end_mark, -1) DESC, gr.code
                """)
                default_grades = cursor.fetchall() or []

                cursor.execute("""
                    SELECT id, subject_name, subject_code
                    FROM subjects
                    WHERE COALESCE(status, 'active') = 'active'
                    ORDER BY subject_name ASC
                """)
                active_subjects = cursor.fetchall() or []

                cursor.execute("""
                    SELECT subject_id, code, start_mark, end_mark, allocation_points
                    FROM subject_grade_mark_overrides
                    ORDER BY subject_id, code
                """)
                subject_grade_mark_overrides = cursor.fetchall() or []

                cursor.execute("""
                    SELECT
                        sgo.id,
                        sgo.academic_level_id,
                        al.level_name,
                        sgo.subject_id,
                        s.subject_name,
                        sgo.code,
                        sgo.meaning,
                        sgo.description
                    FROM subject_grade_overrides sgo
                    INNER JOIN academic_levels al ON al.id = sgo.academic_level_id
                    INNER JOIN subjects s ON s.id = sgo.subject_id
                    ORDER BY al.level_name, s.subject_name, sgo.code
                """)
                subject_overrides = cursor.fetchall() or []

                defaults_as_dict = []
                for row in default_grades:
                    if isinstance(row, dict):
                        defaults_as_dict.append({
                            'code': row.get('code'),
                            'start_mark': row.get('start_mark'),
                            'end_mark': row.get('end_mark'),
                            'level_label': row.get('level_label'),
                            'meaning': row.get('meaning'),
                            'description': row.get('description'),
                            'allocation_points': row.get('allocation_points'),
                        })
                    else:
                        defaults_as_dict.append({
                            'code': row[6] if len(row) > 6 else None,
                            'start_mark': row[3] if len(row) > 3 else None,
                            'end_mark': row[4] if len(row) > 4 else None,
                            'level_label': row[5] if len(row) > 5 else None,
                            'meaning': row[7] if len(row) > 7 else None,
                            'description': row[8] if len(row) > 8 else None,
                            'allocation_points': row[9] if len(row) > 9 else None,
                        })

                overrides_by_subject = {}
                for row in subject_grade_mark_overrides:
                    if isinstance(row, dict):
                        sid = row.get('subject_id')
                        code = row.get('code')
                        sm = row.get('start_mark')
                        em = row.get('end_mark')
                        ap = row.get('allocation_points')
                    else:
                        sid = row[0]
                        code = row[1]
                        sm = row[2]
                        em = row[3]
                        ap = row[4] if len(row) > 4 else None
                    if sid is None or not code:
                        continue
                    if sid not in overrides_by_subject:
                        overrides_by_subject[sid] = {}
                    overrides_by_subject[sid][str(code).upper()] = {
                        'start_mark': sm,
                        'end_mark': em,
                        'allocation_points': ap,
                    }

                for srow in active_subjects:
                    if isinstance(srow, dict):
                        sid = srow.get('id')
                        sname = srow.get('subject_name')
                        scode = srow.get('subject_code')
                    else:
                        sid = srow[0]
                        sname = srow[1]
                        scode = srow[2] if len(srow) > 2 else None
                    merged_bands = []
                    for d in defaults_as_dict:
                        code_key = str(d.get('code') or '').upper()
                        ov = overrides_by_subject.get(sid, {}).get(code_key)
                        def_pts = d.get('allocation_points')
                        ov_pts = ov.get('allocation_points') if ov else None
                        merged_pts = ov_pts if ov_pts is not None else def_pts
                        merged_bands.append({
                            'code': d.get('code'),
                            'level_label': d.get('level_label'),
                            'meaning': d.get('meaning'),
                            'description': d.get('description'),
                            'start_mark': ov.get('start_mark') if ov else d.get('start_mark'),
                            'end_mark': ov.get('end_mark') if ov else d.get('end_mark'),
                            'allocation_points': merged_pts,
                        })
                    subject_grade_allocations.append({
                        'subject_id': sid,
                        'subject_name': sname,
                        'subject_code': scode,
                        'uses_default': sid not in overrides_by_subject,
                        'bands': merged_bands
                    })
        except Exception as e:
            print(f"Error loading grades registration: {e}")
            flash('Error loading grades registration.', 'error')
        finally:
            connection.close()

    return render_template(
        'dashboards/grades_registration.html',
        role=user_role,
        academic_levels=academic_levels,
        level_subjects=level_subjects,
        default_grades=default_grades,
        subject_overrides=subject_overrides,
        subject_grade_allocations=subject_grade_allocations
    )


def _grades_registration_schedule_roles():
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    effective_role = viewing_as_role if user_role == 'technician' and viewing_as_role else user_role
    return effective_role, (
        'curriculum coordinator',
        'head of institution',
        'deputy head of institution',
        'super admin',
        'accountant',
        'technician',
    )


@app.route('/dashboard/employee/grades-registration/default/save', methods=['POST'])
@login_required
def save_default_grade_registration():
    effective_role, schedule_management_roles = _grades_registration_schedule_roles()
    if effective_role not in schedule_management_roles:
        flash('You do not have permission to perform this action.', 'error')
        return redirect(employee_dashboard_path())

    start_mark_raw = (request.form.get('start_mark') or '').strip()
    end_mark_raw = (request.form.get('end_mark') or '').strip()
    level_label = (request.form.get('level_label') or '').strip()
    code = (request.form.get('code') or '').strip().upper()
    meaning = (request.form.get('meaning') or '').strip()
    description = (request.form.get('description') or '').strip()
    points_raw = (request.form.get('allocation_points') or '').strip()
    allocation_points = None
    if points_raw:
        try:
            allocation_points = float(points_raw)
        except Exception:
            flash('Please provide a valid numeric points value, or leave it blank.', 'error')
            return redirect(employee_dashboard_path('grades-registration'))
    try:
        start_mark = float(start_mark_raw)
        end_mark = float(end_mark_raw)
    except Exception:
        flash('Please provide valid start and end marks.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))

    if start_mark > end_mark:
        flash('Start mark must be less than or equal to end mark.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))

    if not (level_label and code and meaning):
        flash('Please provide mark level, code, and meaning.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))

    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))
    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                INSERT INTO grade_registrations (academic_level_id, start_mark, end_mark, level_label, code, meaning, description, allocation_points, created_by)
                VALUES (NULL, %s, %s, %s, %s, %s, %s, %s, %s)
            """, (start_mark, end_mark, level_label, code, meaning, description, allocation_points, session.get('user_id')))
            connection.commit()
        flash('Default grade saved successfully.', 'success')
    except Exception as e:
        print(f"Error saving default grade: {e}")
        connection.rollback()
        flash('Error saving default grade.', 'error')
    finally:
        connection.close()
    return redirect(employee_dashboard_path('grades-registration'))


@app.route('/dashboard/employee/grades-registration/default/update/<int:grade_id>', methods=['POST'])
@login_required
def update_default_grade_registration(grade_id):
    effective_role, schedule_management_roles = _grades_registration_schedule_roles()
    if effective_role not in schedule_management_roles:
        flash('You do not have permission to perform this action.', 'error')
        return redirect(employee_dashboard_path())

    start_mark_raw = (request.form.get('start_mark') or '').strip()
    end_mark_raw = (request.form.get('end_mark') or '').strip()
    level_label = (request.form.get('level_label') or '').strip()
    code = (request.form.get('code') or '').strip().upper()
    meaning = (request.form.get('meaning') or '').strip()
    description = (request.form.get('description') or '').strip()
    points_raw = (request.form.get('allocation_points') or '').strip()
    allocation_points = None
    if points_raw:
        try:
            allocation_points = float(points_raw)
        except Exception:
            flash('Please provide a valid numeric points value, or leave it blank.', 'error')
            return redirect(employee_dashboard_path('grades-registration'))
    try:
        start_mark = float(start_mark_raw)
        end_mark = float(end_mark_raw)
    except Exception:
        flash('Please provide valid start and end marks.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))

    if start_mark > end_mark:
        flash('Start mark must be less than or equal to end mark.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))

    if not (level_label and code and meaning):
        flash('Please provide mark level, code, and meaning.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))

    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))
    try:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT code FROM grade_registrations WHERE id = %s",
                (grade_id,),
            )
            existing = cursor.fetchone()
            if not existing:
                flash('Grade not found.', 'error')
                return redirect(employee_dashboard_path('grades-registration'))
            old_code = (
                (existing.get('code') or '').strip()
                if isinstance(existing, dict)
                else (existing[0] or '').strip()
            )

            cursor.execute(
                """
                UPDATE grade_registrations
                SET start_mark = %s, end_mark = %s, level_label = %s, code = %s,
                    meaning = %s, description = %s, allocation_points = %s, created_by = %s
                WHERE id = %s
                """,
                (
                    start_mark,
                    end_mark,
                    level_label,
                    code,
                    meaning,
                    description,
                    allocation_points,
                    session.get('user_id'),
                    grade_id,
                ),
            )
            if old_code.upper() != code.upper():
                cursor.execute(
                    """
                    UPDATE subject_grade_mark_overrides
                    SET code = %s
                    WHERE UPPER(TRIM(code)) = UPPER(TRIM(%s))
                    """,
                    (code, old_code),
                )
            connection.commit()
        flash('Default grade updated successfully.', 'success')
    except Exception as e:
        print(f"Error updating default grade: {e}")
        connection.rollback()
        flash('Error updating default grade. The code may already exist for this level.', 'error')
    finally:
        connection.close()
    return redirect(employee_dashboard_path('grades-registration'))


@app.route('/dashboard/employee/grades-registration/default/delete/<int:grade_id>', methods=['POST'])
@login_required
def delete_default_grade_registration(grade_id):
    effective_role, schedule_management_roles = _grades_registration_schedule_roles()
    if effective_role not in schedule_management_roles:
        flash('You do not have permission to perform this action.', 'error')
        return redirect(employee_dashboard_path())

    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))
    try:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT code FROM grade_registrations WHERE id = %s",
                (grade_id,),
            )
            existing = cursor.fetchone()
            if not existing:
                flash('Grade not found.', 'error')
                return redirect(employee_dashboard_path('grades-registration'))
            band_code = (
                (existing.get('code') or '').strip()
                if isinstance(existing, dict)
                else (existing[0] or '').strip()
            )
            if band_code:
                cursor.execute(
                    """
                    DELETE FROM subject_grade_mark_overrides
                    WHERE UPPER(TRIM(code)) = UPPER(TRIM(%s))
                    """,
                    (band_code,),
                )
            cursor.execute("DELETE FROM grade_registrations WHERE id = %s", (grade_id,))
            connection.commit()
        flash('Default grade deleted. Subject mark overrides for this code were removed.', 'success')
    except Exception as e:
        print(f"Error deleting default grade: {e}")
        connection.rollback()
        flash('Error deleting default grade.', 'error')
    finally:
        connection.close()
    return redirect(employee_dashboard_path('grades-registration'))


@app.route('/dashboard/employee/grades-registration/subject/save', methods=['POST'])
@login_required
def save_subject_grade_override():
    effective_role, schedule_management_roles = _grades_registration_schedule_roles()
    if effective_role not in schedule_management_roles:
        flash('You do not have permission to perform this action.', 'error')
        return redirect(employee_dashboard_path())

    level_id = (request.form.get('academic_level_id') or '').strip()
    subject_id = (request.form.get('subject_id') or '').strip()
    code = (request.form.get('code') or '').strip().upper()
    meaning = (request.form.get('meaning') or '').strip()
    description = (request.form.get('description') or '').strip()
    if not (level_id.isdigit() and subject_id.isdigit() and code and meaning):
        flash('Please provide level, subject, code, and meaning.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))

    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))
    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                INSERT INTO subject_grade_overrides (academic_level_id, subject_id, code, meaning, description, created_by)
                VALUES (%s, %s, %s, %s, %s, %s)
                ON DUPLICATE KEY UPDATE
                    meaning = VALUES(meaning),
                    description = VALUES(description),
                    created_by = VALUES(created_by)
            """, (int(level_id), int(subject_id), code, meaning, description, session.get('user_id')))
            connection.commit()
        flash('Subject grade override saved successfully.', 'success')
    except Exception as e:
        print(f"Error saving subject grade override: {e}")
        connection.rollback()
        flash('Error saving subject grade override.', 'error')
    finally:
        connection.close()
    return redirect(employee_dashboard_path('grades-registration'))


@app.route('/dashboard/employee/grades-registration/subject/save-ranges', methods=['POST'])
@login_required
def save_subject_grade_ranges():
    effective_role, schedule_management_roles = _grades_registration_schedule_roles()
    if effective_role not in schedule_management_roles:
        flash('You do not have permission to perform this action.', 'error')
        return redirect(employee_dashboard_path())

    subject_id_raw = (request.form.get('subject_id') or '').strip()
    if not subject_id_raw.isdigit():
        flash('Invalid subject selected.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))

    codes = request.form.getlist('code')
    start_marks = request.form.getlist('start_mark')
    end_marks = request.form.getlist('end_mark')
    allocation_points_list = request.form.getlist('allocation_points')
    if not (codes and len(codes) == len(start_marks) == len(end_marks)):
        flash('Invalid grade range payload.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))
    if len(allocation_points_list) < len(codes):
        allocation_points_list = list(allocation_points_list) + [''] * (len(codes) - len(allocation_points_list))

    rows = []
    try:
        for idx, code in enumerate(codes):
            c = (code or '').strip().upper()
            sm = float((start_marks[idx] or '').strip())
            em = float((end_marks[idx] or '').strip())
            if not c:
                raise ValueError('Missing code')
            if sm > em:
                raise ValueError('Start mark cannot exceed end mark')
            ap_raw = (allocation_points_list[idx] if idx < len(allocation_points_list) else '').strip()
            ap = None
            if ap_raw:
                try:
                    ap = float(ap_raw)
                except Exception:
                    raise ValueError('Invalid points')
            rows.append((c, sm, em, ap))
    except Exception:
        flash('Please provide valid start/end marks for every grade code.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))

    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(employee_dashboard_path('grades-registration'))
    try:
        with connection.cursor() as cursor:
            cursor.execute("DELETE FROM subject_grade_mark_overrides WHERE subject_id = %s", (int(subject_id_raw),))
            for c, sm, em, ap in rows:
                cursor.execute("""
                    INSERT INTO subject_grade_mark_overrides (subject_id, code, start_mark, end_mark, allocation_points, created_by)
                    VALUES (%s, %s, %s, %s, %s, %s)
                """, (int(subject_id_raw), c, sm, em, ap, session.get('user_id')))
            connection.commit()
        flash('Subject grade allocation updated successfully.', 'success')
    except Exception as e:
        print(f"Error saving subject grade ranges: {e}")
        connection.rollback()
        flash('Error saving subject grade allocation.', 'error')
    finally:
        connection.close()
    return redirect(employee_dashboard_path('grades-registration'))

# Teacher My Classes Route
@app.route('/dashboard/employee/my-classes')
@login_required
def teacher_my_classes():
    """Teacher's My Classes page - displays timetable with classes and lessons"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check if user is a teacher or technician
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    is_technician = user_role == 'technician'
    
    if not (is_teacher or is_technician):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Get teacher's ID
    if is_technician:
        teacher_id = session.get('viewing_as_employee_id')
        if not teacher_id:
            return render_template('dashboards/teacher_my_classes.html',
                                 role=user_role,
                                 is_technician=True,
                                 teacher_name=None,
                                 staff_employee_number=None,
                                 portal_employee_number=None,
                                 current_term=None,
                                 current_year=None,
                                 timetable_data={},
                                 assignments=[],
                                 days_order=['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'])
    else:
        # Use user_id (database primary key) not employee_id (string like "333333")
        teacher_id = session.get('user_id')
    
    connection = get_db_connection()
    timetable_data = {}
    assignments = []
    teacher_name = None
    staff_employee_number = None
    portal_employee_number = None
    current_term = None
    current_year = None
    
    # Days of the week in order
    days_order = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # Get teacher info
                cursor.execute(f"""
                    SELECT emp.id, emp.full_name,
                           {_employee_staff_identity_sql('emp')} AS staff_employee_number,
                           emp.employee_id AS portal_employee_number
                    FROM employees emp
                    WHERE emp.id = %s
                """, (teacher_id,))
                teacher_result = cursor.fetchone()
                if teacher_result:
                    if isinstance(teacher_result, dict):
                        teacher_name = teacher_result.get('full_name', '')
                        staff_employee_number = teacher_result.get('staff_employee_number')
                        portal_employee_number = teacher_result.get('portal_employee_number')
                    else:
                        teacher_name = teacher_result[1] if len(teacher_result) > 1 else ''
                        staff_employee_number = teacher_result[2] if len(teacher_result) > 2 else None
                        portal_employee_number = teacher_result[3] if len(teacher_result) > 3 else None
                
                # Get current academic year
                cursor.execute("""
                    SELECT id, year_name, is_current
                    FROM academic_years
                    WHERE is_current = TRUE AND status = 'active'
                    LIMIT 1
                """)
                current_year_result = cursor.fetchone()
                current_academic_year_id = None
                if current_year_result:
                    current_academic_year_id = current_year_result.get('id') if isinstance(current_year_result, dict) else current_year_result[0]
                    current_year = current_year_result.get('year_name') if isinstance(current_year_result, dict) else current_year_result[1]
                
                # Get current term
                current_term_id = None
                if current_academic_year_id:
                    cursor.execute("""
                        SELECT id, term_name, is_current
                        FROM terms
                        WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
                        LIMIT 1
                    """, (current_academic_year_id,))
                    current_term_result = cursor.fetchone()
                    if current_term_result:
                        current_term_id = current_term_result.get('id') if isinstance(current_term_result, dict) else current_term_result[0]
                        current_term = current_term_result.get('term_name') if isinstance(current_term_result, dict) else current_term_result[1]
                
                # Get teacher's subject assignments (academic levels and subjects)
                cursor.execute("""
                    SELECT tsa.id, tsa.academic_level_id, tsa.subject_id,
                           al.level_name, al.level_category,
                           s.subject_name, s.subject_code
                    FROM teacher_subject_assignments tsa
                    LEFT JOIN academic_levels al ON tsa.academic_level_id = al.id
                    LEFT JOIN subjects s ON tsa.subject_id = s.id
                    WHERE tsa.teacher_id = %s
                    ORDER BY al.level_name, s.subject_name
                """, (teacher_id,))
                assignments_results = cursor.fetchall()
                
                for row in assignments_results:
                    if isinstance(row, dict):
                        assignments.append({
                            'id': row.get('id'),
                            'academic_level_id': row.get('academic_level_id'),
                            'subject_id': row.get('subject_id'),
                            'level_name': row.get('level_name', ''),
                            'level_category': row.get('level_category', ''),
                            'subject_name': row.get('subject_name', ''),
                            'subject_code': row.get('subject_code', '')
                        })
                    else:
                        assignments.append({
                            'id': row[0],
                            'academic_level_id': row[1],
                            'subject_id': row[2],
                            'level_name': row[3] if len(row) > 3 else '',
                            'level_category': row[4] if len(row) > 4 else '',
                            'subject_name': row[5] if len(row) > 5 else '',
                            'subject_code': row[6] if len(row) > 6 else ''
                        })

                # Count students currently in session per academic level.
                # Students table stores grade label in current_grade, not academic_level_id.
                in_session_by_level = {}
                cursor.execute("""
                    SELECT al.id AS academic_level_id, COUNT(*) AS in_session_count
                    FROM students st
                    JOIN academic_levels al
                      ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al.level_name))
                    WHERE st.status = 'in session'
                    GROUP BY al.id
                """)
                in_session_results = cursor.fetchall()
                for row in in_session_results:
                    if isinstance(row, dict):
                        level_id = row.get('academic_level_id')
                        in_session_count = row.get('in_session_count', 0)
                    else:
                        level_id = row[0] if len(row) > 0 else None
                        in_session_count = row[1] if len(row) > 1 else 0
                    if level_id is not None:
                        in_session_by_level[level_id] = int(in_session_count or 0)
                
                # Get timetable entries for this teacher
                if current_term_id:
                    cursor.execute("""
                        SELECT DISTINCT t.id, t.day_of_week, t.time_slot, t.academic_level_id,
                               al.level_name, al.level_category, t.subject_id,
                               s.subject_name, s.subject_code
                        FROM timetables t
                        LEFT JOIN academic_levels al ON t.academic_level_id = al.id
                        LEFT JOIN subjects s ON t.subject_id = s.id
                        WHERE t.teacher_id = %s AND t.term_id = %s
                        ORDER BY 
                            FIELD(t.day_of_week, 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'),
                            t.time_slot
                    """, (teacher_id, current_term_id))
                    timetable_results = cursor.fetchall()

                    # Organize timetable by day and time
                    for row in timetable_results:
                        if isinstance(row, dict):
                            day = row.get('day_of_week', '')
                            time = row.get('time_slot', '')
                            level_name = row.get('level_name', '')
                            academic_level_id = row.get('academic_level_id')
                            subject_name = row.get('subject_name') or ''
                            subject_code = row.get('subject_code') or ''
                            subject_id = row.get('subject_id')
                        else:
                            day = row[1] if len(row) > 1 else ''
                            time = row[2] if len(row) > 2 else ''
                            level_name = row[4] if len(row) > 4 else ''
                            academic_level_id = row[3] if len(row) > 3 else None
                            subject_id = row[6] if len(row) > 6 else None
                            subject_name = row[7] if len(row) > 7 and row[7] else ''
                            subject_code = row[8] if len(row) > 8 and row[8] else ''
                        
                        if day and time:
                            if day not in timetable_data:
                                timetable_data[day] = {}
                            if time not in timetable_data[day]:
                                timetable_data[day][time] = []

                            # If subject isn't set on this slot, fallback to assignment for same class.
                            if not subject_name and subject_id and assignments:
                                for assignment in assignments:
                                    if assignment.get('academic_level_id') == academic_level_id and assignment.get('subject_id') == subject_id:
                                        subject_name = assignment.get('subject_name', '') or ''
                                        subject_code = assignment.get('subject_code', '') or ''
                                        break

                            timetable_data[day][time].append({
                                'level_name': level_name,
                                'subject_name': subject_name or 'No Subject Assigned',
                                'subject_code': subject_code,
                                'academic_level_id': academic_level_id,
                                'in_session_count': in_session_by_level.get(academic_level_id, 0),
                            })
                
        except Exception as e:
            print(f"Error fetching teacher classes: {e}")
            import traceback
            traceback.print_exc()
            flash('Error loading your classes. Please try again.', 'error')
        finally:
            connection.close()
    
    return render_template('dashboards/teacher_my_classes.html',
                         role=user_role,
                         is_technician=is_technician,
                         teacher_name=teacher_name,
                         staff_employee_number=staff_employee_number,
                         portal_employee_number=portal_employee_number,
                         current_term=current_term,
                         current_year=current_year,
                         timetable_data=timetable_data,
                         assignments=assignments,
                         days_order=days_order)


