# Academic Coordinator Settings Save Route
@app.route('/settings/curriculum-coordinator/save', methods=['POST'])
@app.route('/settings/curriculum coordinator/save', methods=['POST'])
@login_required
def save_academic_coordinator_settings():
    """Save academic coordinator settings"""
    user_role = session.get('role', '').lower()
    schedule_management_roles = ['curriculum coordinator', 'head of institution', 'deputy head of institution', 'super admin', 'accountant', 'technician']

    if user_role not in schedule_management_roles:
        flash('You do not have permission to perform this action.', 'error')
        return redirect(employee_dashboard_path())
    
    study_days = request.form.get('study_days', '')
    class_duration = request.form.get('class_duration', '60')
    profile_name = request.form.get('profile_name', '').strip()
    profile_id = request.form.get('profile_id', '').strip()
    return_to = request.form.get('return_to', '').strip().lower()
    selected_levels = request.form.getlist('applicable_levels')
    
    # Get class times and activities from form (as JSON strings)
    class_times_json = request.form.get('class_times_json', '[]')
    activities_json = request.form.get('activities_json', '[]')
    applicable_levels_json = json.dumps(selected_levels)

    if not profile_name:
        flash('Please provide a profile name.', 'error')
        return redirect(employee_staff_settings_url('curriculum coordinator'))

    if not selected_levels:
        flash('Please select at least one academic level.', 'error')
        return redirect(employee_staff_settings_url('curriculum coordinator'))
    
    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(employee_staff_settings_url('curriculum coordinator'))
    
    try:
        with connection.cursor() as cursor:
            has_is_active = True
            try:
                cursor.execute("SELECT is_active FROM academic_coordinator_settings LIMIT 1")
            except Exception:
                has_is_active = False

            if profile_id.isdigit():
                # Update selected profile
                if has_is_active:
                    cursor.execute("""
                        UPDATE academic_coordinator_settings 
                        SET profile_name = %s,
                            study_days = %s, 
                            applicable_levels = %s,
                            class_time_allocation = %s, 
                            class_duration = %s,
                            activity_time_allocation = %s
                        WHERE id = %s
                    """, (profile_name, study_days, applicable_levels_json, class_times_json, int(class_duration), activities_json, int(profile_id)))
                else:
                    cursor.execute("""
                        UPDATE academic_coordinator_settings 
                        SET profile_name = %s,
                            study_days = %s, 
                            applicable_levels = %s,
                            class_time_allocation = %s, 
                            class_duration = %s,
                            activity_time_allocation = %s
                        WHERE id = %s
                    """, (profile_name, study_days, applicable_levels_json, class_times_json, int(class_duration), activities_json, int(profile_id)))
                saved_profile_id = int(profile_id)
            else:
                # Create new profile
                if has_is_active:
                    cursor.execute("""
                        INSERT INTO academic_coordinator_settings (profile_name, is_active, study_days, applicable_levels, class_time_allocation, class_duration, activity_time_allocation)
                        VALUES (%s, 1, %s, %s, %s, %s, %s)
                    """, (profile_name, study_days, applicable_levels_json, class_times_json, int(class_duration), activities_json))
                else:
                    cursor.execute("""
                        INSERT INTO academic_coordinator_settings (profile_name, study_days, applicable_levels, class_time_allocation, class_duration, activity_time_allocation)
                        VALUES (%s, %s, %s, %s, %s, %s)
                    """, (profile_name, study_days, applicable_levels_json, class_times_json, int(class_duration), activities_json))
                saved_profile_id = cursor.lastrowid

            # Allow multiple profiles to stay active; do not deactivate others.
            
            connection.commit()
            flash('Academic settings profile saved successfully!', 'success')
    except Exception as e:
        print(f"Error saving academic coordinator settings: {e}")
        flash('Error saving settings. Please try again.', 'error')
        saved_profile_id = profile_id if profile_id else ''
    finally:
        connection.close()

    if return_to in ('academic-settings', 'academic-schedule-management'):
        if str(saved_profile_id).isdigit():
            return redirect(url_for('academic_schedule_management', profile_id=saved_profile_id))
        return redirect(url_for('academic_schedule_management'))

    if str(saved_profile_id).isdigit():
        return redirect(employee_staff_settings_url('curriculum coordinator', profile_id=saved_profile_id))
    return redirect(employee_staff_settings_url('curriculum coordinator'))

@app.route('/settings/curriculum-coordinator/status/<int:profile_id>', methods=['POST'])
@app.route('/settings/curriculum coordinator/status/<int:profile_id>', methods=['POST'])
@login_required
def toggle_academic_coordinator_profile_status(profile_id):
    """Toggle active status for a saved academic coordinator settings profile"""
    user_role = session.get('role', '').lower()
    return_to = request.form.get('return_to', '').strip().lower()
    wants_json = request.headers.get('X-Requested-With', '').lower() == 'xmlhttprequest'
    is_active_raw = str(request.form.get('is_active', '0')).strip().lower()
    is_active = 1 if is_active_raw in ('1', 'true', 'yes', 'on') else 0
    schedule_management_roles = ['curriculum coordinator', 'head of institution', 'deputy head of institution', 'super admin', 'accountant', 'technician']

    if user_role not in schedule_management_roles:
        message = 'You do not have permission to perform this action.'
        if wants_json:
            return jsonify({'success': False, 'message': message}), 403
        flash(message, 'error')
        return redirect(employee_dashboard_path())

    connection = get_db_connection()
    if not connection:
        message = 'Database connection error.'
        if wants_json:
            return jsonify({'success': False, 'message': message}), 500
        flash(message, 'error')
        return redirect(employee_staff_settings_url('curriculum coordinator'))

    try:
        with connection.cursor() as cursor:
            cursor.execute("SELECT id FROM academic_coordinator_settings WHERE id = %s LIMIT 1", (profile_id,))
            row = cursor.fetchone()
            if not row:
                message = 'Schedule profile not found.'
                if wants_json:
                    return jsonify({'success': False, 'message': message}), 404
                flash(message, 'error')
            else:
                cursor.execute(
                    "UPDATE academic_coordinator_settings SET is_active = %s WHERE id = %s",
                    (is_active, profile_id)
                )
                connection.commit()
                if wants_json:
                    return jsonify({'success': True, 'is_active': bool(is_active), 'profile_id': profile_id}), 200
                flash('Schedule profile status updated.', 'success')
    except Exception as e:
        print(f"Error updating academic coordinator profile status: {e}")
        connection.rollback()
        message = 'Error updating schedule profile status. Please try again.'
        if wants_json:
            return jsonify({'success': False, 'message': message}), 500
        flash(message, 'error')
    finally:
        connection.close()

    if return_to in ('academic-settings', 'academic-schedule-management'):
        return redirect(url_for('academic_schedule_management', profile_id=profile_id))
    return redirect(employee_staff_settings_url('curriculum coordinator', profile_id=profile_id))

@app.route('/settings/curriculum-coordinator/delete/<int:profile_id>', methods=['POST'])
@app.route('/settings/curriculum coordinator/delete/<int:profile_id>', methods=['POST'])
@login_required
def delete_academic_coordinator_settings(profile_id):
    """Delete a saved academic coordinator settings profile"""
    user_role = session.get('role', '').lower()
    return_to = request.form.get('return_to', '').strip().lower()
    schedule_management_roles = ['curriculum coordinator', 'head of institution', 'deputy head of institution', 'super admin', 'accountant', 'technician']

    if user_role not in schedule_management_roles:
        flash('You do not have permission to perform this action.', 'error')
        return redirect(employee_dashboard_path())

    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(employee_staff_settings_url('curriculum coordinator'))

    next_profile_id = None
    try:
        with connection.cursor() as cursor:
            cursor.execute("SELECT COUNT(*) AS count FROM academic_coordinator_settings")
            result = cursor.fetchone()
            profile_count = result['count'] if isinstance(result, dict) else result[0]

            if profile_count <= 1:
                flash('Cannot delete the only remaining schedule profile.', 'error')
                if return_to in ('academic-settings', 'academic-schedule-management'):
                    return redirect(url_for('academic_schedule_management', profile_id=profile_id))
                return redirect(employee_staff_settings_url('curriculum coordinator', profile_id=profile_id))

            cursor.execute("DELETE FROM academic_coordinator_settings WHERE id = %s", (profile_id,))

            if cursor.rowcount == 0:
                flash('Schedule profile not found.', 'error')
                if return_to in ('academic-settings', 'academic-schedule-management'):
                    return redirect(url_for('academic_schedule_management'))
                return redirect(employee_staff_settings_url('curriculum coordinator'))

            cursor.execute("""
                SELECT id
                FROM academic_coordinator_settings
                ORDER BY updated_at DESC, id DESC
                LIMIT 1
            """)
            next_row = cursor.fetchone()
            if next_row:
                next_profile_id = next_row.get('id') if isinstance(next_row, dict) else next_row[0]

            connection.commit()
            flash('Schedule profile deleted successfully.', 'success')
    except Exception as e:
        print(f"Error deleting academic coordinator settings profile: {e}")
        connection.rollback()
        flash('Error deleting schedule profile. Please try again.', 'error')
    finally:
        connection.close()

    if return_to in ('academic-settings', 'academic-schedule-management'):
        if next_profile_id:
            return redirect(url_for('academic_schedule_management', profile_id=next_profile_id))
        return redirect(url_for('academic_schedule_management'))

    if next_profile_id:
        return redirect(employee_staff_settings_url('curriculum coordinator', profile_id=next_profile_id))
    return redirect(employee_staff_settings_url('curriculum coordinator'))

# Role Switching Route (for technicians)
@app.route('/switch-role/<path:target_role>')
@login_required
def switch_role(target_role):
    """Allow technicians to switch between different role views.
    Uses path converter and normalizes URL slugs (hyphens) to role names (spaces)
    for compatibility with hosting environments that mishandle %20 in paths."""
    user_role = session.get('role', '').lower()
    
    # Only technicians can switch roles
    if user_role != 'technician':
        flash('You do not have permission to switch roles.', 'error')
        return redirect(employee_dashboard_path())
    
    # Normalize: convert URL-safe hyphens to spaces (e.g. deputy-principal -> deputy principal)
    target_role = target_role.strip().replace('-', ' ').lower()
    
    # Get redirect URL from query parameter
    redirect_url = request.args.get('redirect', None)
    
    # Valid main roles to switch to
    valid_main_roles = ['employee', 'student', 'parent']
    
    # Valid employee sub-roles (must match EMPLOYEE_SUB_ROLES / DB ENUM)
    valid_employee_roles = list(EMPLOYEE_SUB_ROLES)
    
    # Check if it's a main role
    if target_role in valid_main_roles:
        # Store the role we're viewing as
        session['viewing_as_role'] = target_role
        session['viewing_as_employee_role'] = None  # Clear employee sub-role
        session.pop('viewing_as_employee_id', None)  # Clear employee selection
        
        flash(f'Switched to {target_role.title()} role view.', 'success')
        
        # Redirect to custom URL if provided, otherwise to appropriate dashboard
        if redirect_url:
            return redirect(redirect_url)
        elif target_role == 'employee':
            return redirect(employee_dashboard_path())
        elif target_role == 'student':
            return redirect(student_dashboard_path())
        elif target_role == 'parent':
            return redirect(parent_dashboard_path())
    
    # Check if it's an employee sub-role
    elif target_role in valid_employee_roles:
        # Set viewing as employee with specific sub-role
        session['viewing_as_role'] = 'employee'
        session['viewing_as_employee_role'] = target_role
        session.pop('viewing_as_employee_id', None)  # Clear previous employee selection when switching roles
        flash(f'Switched to {target_role.title()} role view.', 'success')
        
        # Redirect to custom URL if provided, otherwise to employee dashboard
        if redirect_url:
            return redirect(redirect_url)
        return redirect(employee_dashboard_path())
    
    else:
        flash('Invalid role selected.', 'error')
        return redirect(url_for('role_switch_page'))
    
    return redirect(url_for('role_switch_page'))

@app.route('/role-switch')
@login_required
def role_switch_page():
    """Role switch page for technicians to select which role to view as"""
    user_role = session.get('role', '').lower()
    
    # Only technicians can access this page
    if user_role != 'technician':
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    return render_template('dashboards/role_switch.html', 
                         employee_roles_list=list(EMPLOYEE_SUB_ROLES))

@app.route('/switch-role/reset')
@login_required
def reset_role():
    """Reset to technician's own role"""
    # Get redirect URL from query parameter
    redirect_url = request.args.get('redirect', None)
    user_role = session.get('role', '').lower()
    
    if user_role != 'technician':
        flash('You do not have permission to perform this action.', 'error')
        return redirect(employee_dashboard_path())
    
    # Remove viewing roles and employee from session
    session.pop('viewing_as_role', None)
    session.pop('viewing_as_employee_role', None)
    session.pop('viewing_as_employee_id', None)
    
    flash('Switched back to your technician role.', 'success')
    
    # Redirect to custom URL if provided, otherwise to employee dashboard
    if redirect_url:
        return redirect(redirect_url)
    return redirect(employee_dashboard_path())

@app.route('/switch-employee/<int:employee_id>')
@login_required
def switch_employee(employee_id):
    """Allow technicians to switch to view as a specific employee"""
    user_role = session.get('role', '').lower()
    
    # Only technicians can switch employees
    if user_role != 'technician':
        flash('You do not have permission to switch employees.', 'error')
        return redirect(employee_dashboard_path())
    
    # Get redirect URL from query parameter
    redirect_url = request.args.get('redirect', None)
    
    # If employee_id is 0, clear the selection
    if employee_id == 0:
        session.pop('viewing_as_employee_id', None)
        flash('Employee selection cleared.', 'success')
        if redirect_url:
            return redirect(redirect_url)
        return redirect(employee_dashboard_path())
    
    # Verify the employee exists and matches the viewing role
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    if not viewing_as_role:
        flash('Please select a role first before selecting an employee.', 'error')
        if redirect_url:
            return redirect(redirect_url)
        return redirect(url_for('role_switch_page'))
    
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                # Check if employee exists and has the correct role
                cursor.execute("""
                    SELECT id, employee_id, full_name, role, status
                    FROM employees
                    WHERE id = %s AND (role = %s OR role = %s) AND status = 'active'
                """, (employee_id, viewing_as_role, viewing_as_role + 's'))
                employee = cursor.fetchone()
                
                if not employee:
                    flash('Employee not found or does not match the selected role.', 'error')
                    if redirect_url:
                        return redirect(redirect_url)
                    return redirect(url_for('role_switch_page'))
                
                # Store the employee ID in session
                session['viewing_as_employee_id'] = employee_id
                flash(f'Now viewing as {employee.get("full_name") if isinstance(employee, dict) else employee[2]}.', 'success')
        except Exception as e:
            print(f"Error switching employee: {e}")
            flash('Error switching employee. Please try again.', 'error')
        finally:
            connection.close()
    else:
        flash('Database connection failed.', 'error')
    
    # Redirect to custom URL if provided, otherwise to employee dashboard
    if redirect_url:
        return redirect(redirect_url)
    return redirect(employee_dashboard_path())

# System Settings Route (for technicians)
@app.route('/system-settings')
@login_required
def system_settings():
    """System settings page for technicians and accountants"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check if user is accountant or viewing as accountant
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_technician = user_role == 'technician'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'
    
    # Check permission OR role-based access - allow technicians and accountants
    has_access = check_permission_or_role('system_settings', 
                                         allowed_roles=['technician', 'accountant'])
    
    # Allow secretary to open Academic Year section (read-only UI behavior is in templates/forms).
    if not (has_access or is_accountant or is_technician or is_secretary):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Get school settings, academic levels, academic years, and terms
    connection = get_db_connection()
    school_data = {}
    academic_levels = []
    academic_years = []
    terms = []
    current_academic_year = None
    theme_settings = {
        'primary_color': '#800020',
        'secondary_color': '#A00030',
        'accent_color': '#800020',
        'font_family': 'Inter'
    }
    login_settings = {
        'welcome_title': 'Welcome Back',
        'welcome_subtitle': 'Sign in to your account',
        'show_role_selector': True,
        'show_register_links': True
    }
    if connection:
        try:
            with connection.cursor() as cursor:
                # Get school settings
                cursor.execute("SELECT * FROM school_settings ORDER BY id DESC LIMIT 1")
                result = cursor.fetchone()
                if result:
                    # Handle both dict (DictCursor) and tuple results
                    if isinstance(result, dict):
                        school_data = {
                            'school_name': result.get('school_name', '') or '',
                            'school_email': result.get('school_email', '') or '',
                            'school_phone': result.get('school_phone', '') or '',
                            'school_logo': result.get('school_logo', '') or '',
                            'school_hero_image': result.get('school_hero_image', '') or '',
                            'twitter_url': result.get('twitter_url', '') or '',
                            'facebook_url': result.get('facebook_url', '') or '',
                            'instagram_url': result.get('instagram_url', '') or '',
                            'tiktok_url': result.get('tiktok_url', '') or '',
                            'whatsapp_number': result.get('whatsapp_number', '') or '',
                            'school_location': result.get('school_location', '') or '',
                            'project_name': result.get('project_name', 'Elimu Centric') or 'Elimu Centric',
                            'student_id_prefix': (result.get('student_id_prefix') or 'STU').strip().upper()[:10],
                            'student_id_digits': _parse_student_id_digits(result.get('student_id_digits')),
                            'primary_color': (result.get('primary_color') or '#800020').strip(),
                            'secondary_color': (result.get('secondary_color') or '#A00030').strip(),
                            'accent_color': (result.get('accent_color') or '#5C0014').strip(),
                            'font_family': normalize_portal_font_family(result.get('font_family')),
                        }
                        theme_settings = {k: school_data[k] for k in ('primary_color', 'secondary_color', 'accent_color', 'font_family')}
                    else:
                        school_data = {
                            'school_name': result[1] if len(result) > 1 else '',
                            'school_email': result[2] if len(result) > 2 else '',
                            'school_phone': result[3] if len(result) > 3 else '',
                            'school_logo': result[4] if len(result) > 4 else '',
                            'twitter_url': result[5] if len(result) > 5 else '',
                            'facebook_url': result[6] if len(result) > 6 else '',
                            'instagram_url': result[7] if len(result) > 7 else '',
                            'tiktok_url': result[8] if len(result) > 8 else '',
                            'whatsapp_number': result[9] if len(result) > 9 else '',
                            'school_location': result[10] if len(result) > 10 else '',
                            'project_name': result[11] if len(result) > 11 else 'Elimu Centric'
                        }
                
                # Get academic levels
                try:
                    cursor.execute("""
                        SELECT id, level_category, level_name, level_code, level_description, level_status, 
                               created_at, updated_at 
                        FROM academic_levels 
                        ORDER BY level_category ASC, level_name ASC, level_code ASC
                    """)
                    results = cursor.fetchall()
                    
                    print(f"DEBUG: Query returned {len(results) if results else 0} rows")
                    
                    if results:
                        for row in results:
                            # Since we're using DictCursor, row should be a dict
                            level_data = {
                                'id': row.get('id'),
                                'level_category': str(row.get('level_category', '')).strip() or '',
                                'level_name': str(row.get('level_name', '')).strip() or '',
                                'level_code': str(row.get('level_code', '')).strip() or '',
                                'level_description': str(row.get('level_description', '')).strip() if row.get('level_description') else '',
                                'level_status': str(row.get('level_status', 'active')).strip() or 'active',
                                'created_at': row.get('created_at'),
                                'updated_at': row.get('updated_at')
                            }
                            academic_levels.append(level_data)
                        print(f"OK: Successfully fetched {len(academic_levels)} academic level(s)")
                    else:
                        print("Info: No academic levels found in database (table exists but is empty)")
                except pymysql.err.ProgrammingError as e:
                    # Table doesn't exist (error 1146)
                    error_code = e.args[0] if e.args else 0
                    if error_code == 1146 or "doesn't exist" in str(e).lower():
                        print("Warning: Academic levels table does not exist yet")
                    else:
                        print(f"Warning: SQL Error: {e}")
                        import traceback
                        traceback.print_exc()
                except Exception as e:
                    print(f"Warning: Error fetching academic levels: {e}")
                    import traceback
                    traceback.print_exc()
                
                # Get academic years
                try:
                    # Auto-lock academic years whose end_date has passed
                    from datetime import date
                    today = date.today()
                    cursor.execute("""
                        UPDATE academic_years 
                        SET is_locked = TRUE, locked_at = CURRENT_TIMESTAMP 
                        WHERE end_date < %s AND is_locked = FALSE
                    """, (today,))
                    if cursor.rowcount > 0:
                        connection.commit()
                        print(f"OK: Auto-locked {cursor.rowcount} academic year(s) that have ended")
                    
                    cursor.execute("""
                        SELECT id, year_name, start_date, end_date, status, is_current, is_locked, locked_at
                        FROM academic_years
                        ORDER BY start_date DESC
                    """)
                    academic_years_result = cursor.fetchall()
                    academic_years = []
                    for year in academic_years_result:
                        if isinstance(year, dict):
                            academic_years.append(year)
                        else:
                            academic_years.append({
                                'id': year[0],
                                'year_name': year[1],
                                'start_date': year[2],
                                'end_date': year[3],
                                'status': year[4],
                                'is_current': year[5],
                                'is_locked': year[6] if len(year) > 6 else False,
                                'locked_at': year[7] if len(year) > 7 else None
                            })
                    
                    # Get current academic year
                    cursor.execute("""
                        SELECT id, year_name, start_date, end_date, status, is_current, is_locked, locked_at
                        FROM academic_years
                        WHERE is_current = TRUE
                        LIMIT 1
                    """)
                    current_year_result = cursor.fetchone()
                    if current_year_result:
                        if isinstance(current_year_result, dict):
                            current_academic_year = current_year_result
                        else:
                            current_academic_year = {
                                'id': current_year_result[0],
                                'year_name': current_year_result[1],
                                'start_date': current_year_result[2],
                                'end_date': current_year_result[3],
                                'status': current_year_result[4],
                                'is_current': current_year_result[5],
                                'is_locked': current_year_result[6] if len(current_year_result) > 6 else False,
                                'locked_at': current_year_result[7] if len(current_year_result) > 7 else None
                            }
                    else:
                        current_academic_year = None
                except Exception as e:
                    # Tables might not exist yet
                    print(f"Note: academic_years table may not exist yet: {e}")
                    academic_years = []
                
                # Get terms with their academic levels
                try:
                    cursor.execute("""
                        SELECT t.id, t.term_name, t.academic_year_id,
                               t.start_date, t.end_date, t.status, t.is_current, t.is_locked, t.locked_at,
                               ay.year_name as academic_year_name
                        FROM terms t
                        LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                        ORDER BY t.academic_year_id DESC, t.start_date ASC
                    """)
                    terms_raw = cursor.fetchall()
                    terms = []
                    for term in terms_raw:
                        term_dict = dict(term) if isinstance(term, dict) else {
                            'id': term[0], 'term_name': term[1], 'academic_year_id': term[2],
                            'start_date': term[3], 'end_date': term[4], 'status': term[5],
                            'is_current': term[6] if len(term) > 6 else False,
                            'is_locked': term[7] if len(term) > 7 else False,
                            'locked_at': term[8] if len(term) > 8 else None,
                            'academic_year_name': term[9] if len(term) > 9 else None
                        }
                        
                        # Auto-lock terms that have passed their end date
                        if term_dict.get('end_date') and not term_dict.get('is_locked'):
                            from datetime import date, datetime
                            end_date = term_dict['end_date']
                            if isinstance(end_date, str):
                                end_date = datetime.strptime(end_date, '%Y-%m-%d').date()
                            elif hasattr(end_date, 'date'):
                                end_date = end_date.date()
                            
                            if end_date < date.today():
                                # Auto-lock the term
                                cursor.execute("""
                                    UPDATE terms 
                                    SET is_locked = TRUE, locked_at = NOW() 
                                    WHERE id = %s AND is_locked = FALSE
                                """, (term_dict['id'],))
                                connection.commit()  # Commit auto-lock immediately
                                term_dict['is_locked'] = True
                                term_dict['locked_at'] = datetime.now()
                        # Get academic levels for this term (only active ones)
                        cursor.execute("""
                            SELECT al.id, al.level_name, al.level_category
                            FROM term_academic_levels tal
                            JOIN academic_levels al ON tal.academic_level_id = al.id
                            WHERE tal.term_id = %s AND al.level_status = 'active'
                            ORDER BY al.level_name ASC
                        """, (term_dict['id'],))
                        academic_levels_list = cursor.fetchall()
                        term_dict['academic_levels'] = [
                            {
                                'id': al.get('id') if isinstance(al, dict) else al[0],
                                'level_name': al.get('level_name') if isinstance(al, dict) else al[1],
                                'level_category': al.get('level_category') if isinstance(al, dict) else al[2]
                            }
                            for al in academic_levels_list
                        ]
                        # For backward compatibility, set academic_level_name to first level or None
                        term_dict['academic_level_name'] = academic_levels_list[0].get('level_name') if academic_levels_list and isinstance(academic_levels_list[0], dict) else (academic_levels_list[0][1] if academic_levels_list else None)
                        terms.append(term_dict)
                except Exception as e:
                    # Tables might not exist yet
                    print(f"Note: terms table may not exist yet: {e}")
                    terms = []
        except Exception as e:
            print(f"Error fetching data: {e}")
            print(f"Error type: {type(e).__name__}")
            print(f"Error args: {e.args}")
            import traceback
            traceback.print_exc()
        finally:
            if connection:
                connection.close()
    
    # Calculate days remaining for academic years and terms
    from datetime import date, datetime
    today = date.today()
    
    # Add days_remaining to academic years
    for year in academic_years:
        if year.get('end_date'):
            end_date = year['end_date']
            # Handle different date formats
            if isinstance(end_date, str):
                try:
                    end_date = datetime.strptime(end_date, '%Y-%m-%d').date()
                except:
                    try:
                        end_date = datetime.strptime(end_date, '%Y-%m-%d %H:%M:%S').date()
                    except:
                        end_date = None
            elif isinstance(end_date, datetime):
                end_date = end_date.date()
            elif isinstance(end_date, date):
                end_date = end_date
            else:
                end_date = None
            
            if end_date:
                try:
                    days_diff = (end_date - today).days
                    year['days_remaining'] = days_diff if days_diff >= 0 else 0
                except:
                    year['days_remaining'] = None
            else:
                year['days_remaining'] = None
        else:
            year['days_remaining'] = None
    
    # Add days_remaining to terms
    for term in terms:
        if term.get('end_date'):
            end_date = term['end_date']
            # Handle different date formats
            if isinstance(end_date, str):
                try:
                    end_date = datetime.strptime(end_date, '%Y-%m-%d').date()
                except:
                    try:
                        end_date = datetime.strptime(end_date, '%Y-%m-%d %H:%M:%S').date()
                    except:
                        end_date = None
            elif isinstance(end_date, datetime):
                end_date = end_date.date()
            elif isinstance(end_date, date):
                end_date = end_date
            else:
                end_date = None
            
            if end_date:
                try:
                    days_diff = (end_date - today).days
                    term['days_remaining'] = days_diff if days_diff >= 0 else 0
                except:
                    term['days_remaining'] = None
            else:
                term['days_remaining'] = None
        else:
            term['days_remaining'] = None
    
    _cfg = get_school_settings()
    _theme = (_cfg.get('default_theme_mode') or 'dark').strip().lower()
    if _theme not in ('light', 'dark'):
        _theme = 'dark'
    general_data = {
        'maintenance_mode': bool(_cfg.get('maintenance_mode')),
        'allow_registration': bool(_cfg.get('allow_registration', True)),
        'default_language': _cfg.get('default_language') or 'en',
        'timezone': _cfg.get('timezone') or 'Africa/Nairobi',
        'default_theme_mode': _theme,
    }

    return render_template('dashboards/system_settings.html', 
                         school_data=school_data, 
                         academic_levels=academic_levels,
                         academic_years=academic_years,
                         terms=terms,
                         current_academic_year=current_academic_year,
                         today=today,
                         is_technician=is_technician,
                         is_accountant=is_accountant,
                         theme_settings=theme_settings,
                         login_settings=login_settings,
                         general_data=general_data)


def _load_schedule_profiles_and_settings(cursor, selected_profile_id: str):
    """Load schedule profile list + selected profile row for academic schedule management UI."""
    schedule_settings = {}
    schedule_profiles = []
    try:
        try:
            cursor.execute("""
                SELECT id, profile_name, applicable_levels, is_active
                FROM academic_coordinator_settings
                ORDER BY is_active DESC, updated_at DESC, id DESC
            """)
            has_is_active = True
        except Exception:
            cursor.execute("""
                SELECT id, profile_name, applicable_levels
                FROM academic_coordinator_settings
                ORDER BY updated_at DESC, id DESC
            """)
            has_is_active = False
        raw_profiles = cursor.fetchall() or []
        for row in raw_profiles:
            if isinstance(row, dict):
                raw_levels = row.get('applicable_levels') or '[]'
                profile_id = row.get('id')
                profile_name = row.get('profile_name') or f'Profile {profile_id}'
                is_active = bool(row.get('is_active')) if has_is_active else False
            else:
                raw_levels = row[2] if row[2] else '[]'
                profile_id = row[0]
                profile_name = row[1] if row[1] else f'Profile {profile_id}'
                is_active = bool(row[3]) if has_is_active and len(row) > 3 else False
            try:
                parsed_levels = json.loads(raw_levels)
            except Exception:
                parsed_levels = []
            schedule_profiles.append({
                'id': profile_id,
                'profile_name': profile_name,
                'applicable_levels': parsed_levels,
                'is_active': is_active
            })

        if selected_profile_id.isdigit():
            selected_id = int(selected_profile_id)
        elif schedule_profiles:
            active_profile = next((p for p in schedule_profiles if p.get('is_active')), None)
            selected_id = active_profile['id'] if active_profile else schedule_profiles[0]['id']
        else:
            selected_id = None
        if selected_id:
            cursor.execute("""
                SELECT id, profile_name, study_days, applicable_levels, class_time_allocation, class_duration, activity_time_allocation
                FROM academic_coordinator_settings
                WHERE id = %s
                LIMIT 1
            """, (selected_id,))
        else:
            cursor.execute("""
                SELECT id, profile_name, study_days, applicable_levels, class_time_allocation, class_duration, activity_time_allocation
                FROM academic_coordinator_settings
                ORDER BY updated_at DESC, id DESC
                LIMIT 1
            """)
        srow = cursor.fetchone()
        if srow:
            if isinstance(srow, dict):
                schedule_settings = dict(srow)
                try:
                    schedule_settings['applicable_levels'] = json.loads(schedule_settings.get('applicable_levels') or '[]')
                except Exception:
                    schedule_settings['applicable_levels'] = []
                try:
                    schedule_settings['class_times'] = json.loads(schedule_settings.get('class_time_allocation') or '[]')
                except Exception:
                    schedule_settings['class_times'] = []
                try:
                    schedule_settings['activities'] = json.loads(schedule_settings.get('activity_time_allocation') or '[]')
                except Exception:
                    schedule_settings['activities'] = []
            else:
                try:
                    parsed_levels = json.loads(srow[3] if srow[3] else '[]')
                except Exception:
                    parsed_levels = []
                try:
                    parsed_class_times = json.loads(srow[4] if srow[4] else '[]')
                except Exception:
                    parsed_class_times = []
                try:
                    parsed_activities = json.loads(srow[6] if srow[6] else '[]')
                except Exception:
                    parsed_activities = []
                schedule_settings = {
                    'id': srow[0],
                    'profile_name': srow[1] if srow[1] else '',
                    'study_days': srow[2] if srow[2] else '',
                    'applicable_levels': parsed_levels,
                    'class_times': parsed_class_times,
                    'class_duration': srow[5] if srow[5] else 60,
                    'activities': parsed_activities
                }
    except Exception as e:
        print(f"Note: schedule settings unavailable: {e}")
    return schedule_settings, schedule_profiles


@app.route('/dashboard/employee/academic-settings')
@login_required
def academic_settings():
    """Academic settings page for accountants - shows only Academic Levels, Years, and Terms"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check if user is accountant or viewing as accountant
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_technician = user_role == 'technician'
    
    # Check permission-based access (deputy head: view_student_fees role in permission catalog)
    has_view_fees_permission = check_permission_or_role(
        'view_student_fees',
        ['accountant', 'head of institution', 'deputy head of institution'],
    )
    has_manage_fees_permission = check_permission_or_role('manage_fees', ['accountant', 'head of institution'])
    # Curriculum coordinators use Academic Settings sidebar link; permission catalog includes view_academic_levels
    has_coordinator_academic_access = check_permission_or_role(
        'view_academic_levels',
        ['curriculum coordinator'],
    )
    
    # Permission check handles role fallback if no permissions are assigned
    if not (
        is_technician
        or has_view_fees_permission
        or has_manage_fees_permission
        or has_coordinator_academic_access
    ):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    if request.args.get('tab', '').strip().lower() == 'academic-schedule-management':
        pid = request.args.get('profile_id', '').strip()
        if pid.isdigit():
            return redirect(employee_dashboard_path(f'academic-schedule-management?profile_id={pid}'))
        return redirect(employee_dashboard_path('academic-schedule-management'))
    
    # Get academic levels, academic years, and terms
    connection = get_db_connection()
    academic_levels = []
    academic_years = []
    terms = []
    current_academic_year = None
    today = datetime.now().date()
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # Get academic levels
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description, level_status
                    FROM academic_levels
                    ORDER BY level_category, level_name ASC
                """)
                academic_levels_results = cursor.fetchall()
                
                for row in academic_levels_results:
                    raw_ls = row.get('level_status', 'active') if isinstance(row, dict) else (row[4] if len(row) > 4 else 'active')
                    if isinstance(raw_ls, bytes):
                        raw_ls = raw_ls.decode('utf-8', errors='ignore')
                    ls = (str(raw_ls or 'active')).strip().lower()
                    level_status_norm = 'active' if ls == 'active' else 'inactive'
                    academic_levels.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'level_category': row.get('level_category', '') if isinstance(row, dict) else row[1],
                        'level_name': row.get('level_name', '') if isinstance(row, dict) else row[2],
                        'level_description': row.get('level_description', '') if isinstance(row, dict) else row[3],
                        'level_status': level_status_norm,
                    })
                
                # Get academic years
                try:
                    cursor.execute("""
                        SELECT id, year_name, start_date, end_date, status, is_current
                        FROM academic_years
                        ORDER BY start_date DESC
                    """)
                    academic_years_results = cursor.fetchall()
                    
                    for row in academic_years_results:
                        year_dict = {
                            'id': row.get('id') if isinstance(row, dict) else row[0],
                            'year_name': row.get('year_name', '') if isinstance(row, dict) else row[1],
                            'start_date': row.get('start_date') if isinstance(row, dict) else row[2],
                            'end_date': row.get('end_date') if isinstance(row, dict) else row[3],
                            'status': row.get('status', 'active') if isinstance(row, dict) else (row[4] if len(row) > 4 else 'active'),
                            'is_current': row.get('is_current', False) if isinstance(row, dict) else (row[5] if len(row) > 5 else False)
                        }
                        academic_years.append(year_dict)
                        
                        if year_dict.get('is_current'):
                            current_academic_year = year_dict
                except Exception as e:
                    print(f"Note: academic_years table may not exist yet: {e}")
                    academic_years = []
                
                # Get terms with their academic levels
                try:
                    cursor.execute("""
                        SELECT t.id, t.term_name, t.academic_year_id,
                               t.start_date, t.end_date, t.status, t.is_current, t.is_locked, t.locked_at,
                               ay.year_name as academic_year_name
                        FROM terms t
                        LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                        ORDER BY t.academic_year_id DESC, t.start_date ASC
                    """)
                    terms_raw = cursor.fetchall()
                    terms = []
                    for term in terms_raw:
                        term_dict = dict(term) if isinstance(term, dict) else {
                            'id': term[0], 'term_name': term[1], 'academic_year_id': term[2],
                            'start_date': term[3], 'end_date': term[4], 'status': term[5],
                            'is_current': term[6] if len(term) > 6 else False,
                            'is_locked': term[7] if len(term) > 7 else False,
                            'locked_at': term[8] if len(term) > 8 else None,
                            'academic_year_name': term[9] if len(term) > 9 else None
                        }
                        terms.append(term_dict)
                except Exception as e:
                    print(f"Note: terms table may not exist yet: {e}")
                    terms = []

        except Exception as e:
            print(f"Error fetching academic settings: {e}")
        finally:
            connection.close()
    
    return render_template('dashboards/academic_settings.html',
                         academic_levels=academic_levels,
                         academic_years=academic_years,
                         terms=terms,
                         current_academic_year=current_academic_year,
                         today=today,
                         role=user_role)

