# Allocate Supervisor Route
@app.route('/dashboard/employee/exam-evaluation/allocate-supervisor', methods=['POST'])
@login_required
def allocate_exam_supervisor():
    """Allocate a teacher to supervise an exam"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    data = request.get_json()
    try:
        exam_id = int(data.get('exam_id', 0))
        supervisor_id = int(data.get('supervisor_id', 0))
        academic_level_id = int(data.get('academic_level_id', 0))
        role = data.get('role', 'invigilator')
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid ID values'}), 400
    
    if not all([exam_id > 0, supervisor_id > 0, academic_level_id > 0]):
        return jsonify({'success': False, 'message': 'Missing required fields'}), 400
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            cursor.execute("SELECT COALESCE(is_locked, 0) AS il FROM exams WHERE id = %s", (exam_id,))
            ex = cursor.fetchone()
            if not ex:
                return jsonify({'success': False, 'message': 'Exam not found'}), 404
            il = ex.get('il') if isinstance(ex, dict) else ex[0]
            if il:
                return jsonify({'success': False, 'message': 'This exam is locked. Unlock it before allocating supervisors.'}), 400

            cursor.execute("""
                SELECT id FROM employees
                WHERE id = %s AND status = 'active' AND (role = 'teachers' OR role = 'teacher')
            """, (supervisor_id,))
            if not cursor.fetchone():
                return jsonify({
                    'success': False,
                    'message': 'Supervisor must be an active employee with role Teacher.'
                }), 400

            # Check if allocation already exists
            cursor.execute("""
                SELECT id FROM exam_supervisors
                WHERE exam_id = %s AND supervisor_id = %s AND academic_level_id = %s
            """, (exam_id, supervisor_id, academic_level_id))
            
            if cursor.fetchone():
                return jsonify({'success': False, 'message': 'This supervisor is already allocated to this exam for this academic level'}), 400
            
            # Insert supervisor allocation
            cursor.execute("""
                INSERT INTO exam_supervisors (exam_id, supervisor_id, academic_level_id, role)
                VALUES (%s, %s, %s, %s)
            """, (exam_id, supervisor_id, academic_level_id, role))
            
            connection.commit()
            return jsonify({'success': True, 'message': 'Supervisor allocated successfully'})
            
    except Exception as e:
        print(f"Error allocating supervisor: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Error allocating supervisor: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()


@app.route('/dashboard/employee/exam-evaluation/set-lock', methods=['POST'])
@login_required
def set_exam_lock():
    """Allocation lock (is_locked) and/or scheduled marks lock deadline (marks_lock_at) for one exam group."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    exam_name = (data.get('exam_name') or '').strip().upper()
    try:
        academic_year_id = int(data.get('academic_year_id', 0))
        term_id = int(data.get('term_id', 0))
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid year or term'}), 400

    has_locked = 'locked' in data
    has_marks_lock = 'marks_lock_at' in data

    if not has_locked and not has_marks_lock:
        return jsonify({'success': False, 'message': 'Provide locked and/or marks_lock_at'}), 400

    locked = None
    if has_locked:
        locked_raw = data.get('locked')
        locked = bool(locked_raw) if not isinstance(locked_raw, str) else locked_raw.lower() in ('1', 'true', 'yes')

    marks_lock_dt = None
    marks_lock_clear = False
    if has_marks_lock:
        mla_raw = data.get('marks_lock_at')
        if mla_raw is None or (isinstance(mla_raw, str) and not str(mla_raw).strip()):
            marks_lock_clear = True
        else:
            s = str(mla_raw).strip().replace('Z', '+00:00')
            try:
                marks_lock_dt = datetime.fromisoformat(s)
            except ValueError:
                return jsonify({'success': False, 'message': 'Invalid marks_lock_at datetime'}), 400
            if getattr(marks_lock_dt, 'tzinfo', None):
                marks_lock_dt = marks_lock_dt.replace(tzinfo=None)

    if has_locked and locked is False:
        if not has_marks_lock or marks_lock_clear or marks_lock_dt is None:
            return jsonify({
                'success': False,
                'message': 'Unlocking requires a marks-entry deadline (date and time in the future).',
            }), 400
        if marks_lock_dt <= datetime.now():
            return jsonify({
                'success': False,
                'message': 'Marks-entry deadline must be in the future when unlocking.',
            }), 400

    if not exam_name or academic_year_id <= 0 or term_id <= 0:
        return jsonify({'success': False, 'message': 'Missing exam name, academic year, or term'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            ensure_exams_marks_lock_at_column(cursor)
            apply_marks_lock_deadline_auto_lock(cursor)
            n = 0
            if has_locked:
                lock_int = 1 if locked else 0
                cursor.execute("""
                    UPDATE exams SET
                        is_locked = %s,
                        locked_at = CASE WHEN %s = 1 THEN CURRENT_TIMESTAMP ELSE NULL END
                    WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s
                """, (lock_int, lock_int, exam_name, academic_year_id, term_id))
                n = cursor.rowcount
            if has_marks_lock:
                cursor.execute("""
                    UPDATE exams SET marks_lock_at = %s
                    WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s
                """, (None if marks_lock_clear else marks_lock_dt, exam_name, academic_year_id, term_id))
                n = max(n, cursor.rowcount)
            if n == 0:
                return jsonify({'success': False, 'message': 'No allocations found for that exam'}), 404
            connection.commit()
            msg_parts = []
            if has_locked:
                msg_parts.append('Exam allocations locked.' if locked else 'Exam allocations unlocked.')
            if has_marks_lock:
                msg_parts.append('Marks entry deadline cleared.' if marks_lock_clear else 'Marks entry deadline saved.')
            return jsonify({
                'success': True,
                'message': ' '.join(msg_parts) if msg_parts else 'Updated.',
                **({'locked': locked} if has_locked else {}),
                'marks_lock_at': None if marks_lock_clear else (marks_lock_dt.strftime('%Y-%m-%dT%H:%M:%S') if marks_lock_dt else None),
                'updated': n
            })
    except Exception as e:
        print(f"Error setting exam lock: {e}")
        import traceback
        traceback.print_exc()
        try:
            connection.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'message': f'Error updating lock: {str(e)}'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/exam-evaluation/set-registered-current-exam', methods=['POST'])
@login_required
def set_registered_current_exam():
    """Persist school-wide 'current' registered exam (exam_name + exam_type + year + term) for defaults and UI."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    clear = bool(data.get('clear'))

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            ensure_registered_current_exam_column(cursor)
            cursor.execute("SELECT id FROM school_settings ORDER BY id DESC LIMIT 1")
            row = cursor.fetchone()
            sid = row.get('id') if isinstance(row, dict) else (row[0] if row else None)
            if not sid:
                return jsonify({'success': False, 'message': 'School settings not initialized.'}), 400

            if clear:
                cursor.execute(
                    "UPDATE school_settings SET registered_current_exam_json = NULL WHERE id = %s",
                    (sid,),
                )
                connection.commit()
                invalidate_school_settings_cache()
                return jsonify({'success': True, 'message': 'School-wide current exam cleared.'})

            exam_name = (data.get('exam_name') or '').strip().upper()
            exam_type = (data.get('exam_type') or '').strip().upper()
            try:
                academic_year_id = int(data.get('academic_year_id', 0))
                term_id = int(data.get('term_id', 0))
            except (ValueError, TypeError):
                return jsonify({'success': False, 'message': 'Invalid year or term'}), 400

            if not exam_name or academic_year_id <= 0 or term_id <= 0:
                return jsonify({'success': False, 'message': 'Missing exam name, academic year, or term'}), 400

            cursor.execute(
                """
                SELECT 1 FROM exams
                WHERE UPPER(TRIM(exam_name)) = %s
                  AND academic_year_id = %s
                  AND term_id = %s
                  AND UPPER(TRIM(COALESCE(exam_type, ''))) = %s
                LIMIT 1
                """,
                (exam_name, academic_year_id, term_id, exam_type),
            )
            if not cursor.fetchone():
                return jsonify({'success': False, 'message': 'No registered exam matches that selection.'}), 404

            payload = json.dumps({
                'exam_name': exam_name,
                'exam_type': exam_type,
                'academic_year_id': academic_year_id,
                'term_id': term_id,
            })
            cursor.execute(
                "UPDATE school_settings SET registered_current_exam_json = %s WHERE id = %s",
                (payload, sid),
            )
            connection.commit()
            invalidate_school_settings_cache()
            return jsonify({'success': True, 'message': 'School-wide current exam saved.'})
    except Exception as e:
        print(f"set_registered_current_exam: {e}")
        import traceback
        traceback.print_exc()
        try:
            connection.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'message': f'Error saving: {str(e)}'}), 500
    finally:
        connection.close()


# Get Terms for Academic Year
@app.route('/dashboard/employee/exam-evaluation/get-terms', methods=['POST'])
@login_required
def get_terms_for_year():
    """Get terms for a selected academic year"""
    data = request.get_json()
    academic_year_id = int(data.get('academic_year_id', 0))
    
    if academic_year_id <= 0:
        return jsonify({'success': False, 'terms': []})
    
    connection = get_db_connection()
    terms = []
    
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT id, term_name, start_date, end_date
                    FROM terms
                    WHERE academic_year_id = %s AND status = 'active'
                    ORDER BY start_date ASC
                """, (academic_year_id,))
                terms_results = cursor.fetchall()
                for row in terms_results:
                    terms.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'term_name': row.get('term_name', '') if isinstance(row, dict) else row[1],
                        'start_date': row.get('start_date') if isinstance(row, dict) else row[2],
                        'end_date': row.get('end_date') if isinstance(row, dict) else row[3]
                    })
        except Exception as e:
            print(f"Error fetching terms: {e}")
        finally:
            connection.close()
    
    return jsonify({'success': True, 'terms': terms})

@app.route('/dashboard/employee/classes-subjects')
@login_required
def classes_subjects():
    """Classes & Subjects management page for academic coordinators"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check if user is academic coordinator or viewing as academic coordinator
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    # Allow academic coordinators, principals, and technicians
    if not (is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Get academic levels for classes
    connection = get_db_connection()
    academic_levels = []
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # Get academic levels
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description, level_status
                    FROM academic_levels
                    WHERE level_status = 'active'
                    ORDER BY level_category, level_name ASC
                """)
                academic_levels_results = cursor.fetchall()
                
                for row in academic_levels_results:
                    academic_levels.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'level_category': row.get('level_category', '') if isinstance(row, dict) else row[1],
                        'level_name': row.get('level_name', '') if isinstance(row, dict) else row[2],
                        'level_description': row.get('level_description', '') if isinstance(row, dict) else row[3],
                        'level_status': row.get('level_status', 'active') if isinstance(row, dict) else (row[4] if len(row) > 4 else 'active')
                    })

                # Per-level: subjects allocated to each academic level.
                # Source of truth is subject_academic_levels so the page shows all
                # registered level subjects, even when a teacher has not been assigned yet.
                allocations_by_level = {}
                try:
                    cursor.execute("""
                        SELECT sal.academic_level_id, sal.subject_id,
                               s.subject_name, s.subject_code,
                               COALESCE(s.status, 'active') AS subject_status
                        FROM subject_academic_levels sal
                        INNER JOIN academic_levels al
                            ON sal.academic_level_id = al.id
                           AND COALESCE(al.level_status, 'active') = 'active'
                        INNER JOIN subjects s ON sal.subject_id = s.id
                        ORDER BY al.level_name ASC, s.subject_name ASC
                    """)
                    assign_rows = cursor.fetchall() or []
                    for arow in assign_rows:
                        lid = arow.get('academic_level_id') if isinstance(arow, dict) else arow[0]
                        if lid is None:
                            continue
                        subj_name = (arow.get('subject_name', '') if isinstance(arow, dict) else arow[2]) or ''
                        subj_status = (arow.get('subject_status', 'active') if isinstance(arow, dict) else (arow[4] if len(arow) > 4 else 'active'))
                        if str(subj_status or '').lower() == 'inactive':
                            continue
                        subj_id = arow.get('subject_id') if isinstance(arow, dict) else arow[1]
                        if subj_id is None:
                            continue
                        level_subjects = allocations_by_level.setdefault(lid, {})
                        if subj_id not in level_subjects:
                            level_subjects[subj_id] = {
                                'subject_id': subj_id,
                                'subject_name': subj_name or 'Subject',
                                'subject_code': (arow.get('subject_code', '') if isinstance(arow, dict) else (arow[3] if len(arow) > 3 else '')) or '',
                            }
                except Exception as e:
                    print(f"Note: subject_academic_levels for classes-subjects: {e}")

                # Backward compatibility: if a subject is in teacher assignments but not
                # in subject_academic_levels, still include it in the list.
                try:
                    cursor.execute("""
                        SELECT tsa.academic_level_id, tsa.subject_id,
                               s.subject_name, s.subject_code,
                               COALESCE(s.status, 'active') AS subject_status
                        FROM teacher_subject_assignments tsa
                        INNER JOIN academic_levels al
                            ON tsa.academic_level_id = al.id
                           AND COALESCE(al.level_status, 'active') = 'active'
                        LEFT JOIN subjects s ON tsa.subject_id = s.id
                        ORDER BY al.level_name ASC, s.subject_name ASC
                    """)
                    tsa_rows = cursor.fetchall() or []
                    for trow in tsa_rows:
                        lid = trow.get('academic_level_id') if isinstance(trow, dict) else trow[0]
                        subj_id = trow.get('subject_id') if isinstance(trow, dict) else trow[1]
                        if lid is None or subj_id is None:
                            continue
                        subj_status = (trow.get('subject_status', 'active') if isinstance(trow, dict) else (trow[4] if len(trow) > 4 else 'active'))
                        if str(subj_status or '').lower() == 'inactive':
                            continue
                        level_subjects = allocations_by_level.setdefault(lid, {})
                        if subj_id not in level_subjects:
                            level_subjects[subj_id] = {
                                'subject_id': subj_id,
                                'subject_name': (trow.get('subject_name', '') if isinstance(trow, dict) else (trow[2] if len(trow) > 2 else '')) or 'Subject',
                                'subject_code': (trow.get('subject_code', '') if isinstance(trow, dict) else (trow[3] if len(trow) > 3 else '')) or '',
                            }
                except Exception as e:
                    print(f"Note: teacher_subject_assignments fallback for classes-subjects: {e}")

                ensure_subject_exam_display_order_columns(cursor)
                all_level_sids = set()
                for _lid, subdict in allocations_by_level.items():
                    all_level_sids.update(int(x) for x in subdict.keys() if x is not None)
                edo_by_sid = {}
                id_to_gc_all = {}
                if all_level_sids:
                    ph = ','.join(['%s'] * len(all_level_sids))
                    cursor.execute(
                        f"SELECT id, exam_display_order FROM subjects WHERE id IN ({ph})",
                        tuple(all_level_sids),
                    )
                    for er in cursor.fetchall() or []:
                        eid = er.get('id') if isinstance(er, dict) else er[0]
                        if eid is not None:
                            edo_by_sid[int(eid)] = er.get('exam_display_order') if isinstance(er, dict) else (er[1] if len(er) > 1 else None)
                    id_to_gc_all = fetch_subject_id_to_exam_group_category(cursor, list(all_level_sids))
                base_cat_order = fetch_base_academic_level_category_order(cursor)

                for level in academic_levels:
                    level_subjects = allocations_by_level.get(level['id'], {})
                    sort_rows = []
                    for sid, info in level_subjects.items():
                        try:
                            sid_i = int(sid)
                        except (TypeError, ValueError):
                            continue
                        gc = id_to_gc_all.get(sid_i, 'Uncategorized')
                        sort_rows.append(
                            {
                                'id': sid_i,
                                'subject_name': info.get('subject_name') or '',
                                'subject_code': info.get('subject_code') or '',
                                'exam_display_order': edo_by_sid.get(sid_i),
                                'group_category': gc,
                            }
                        )
                    sec_ord = build_exam_subject_section_order({r['group_category'] for r in sort_rows}, base_cat_order)
                    sort_rows.sort(key=lambda r: exam_subject_column_sort_key(r, sec_ord))
                    level['subject_allocations'] = [
                        {
                            'subject_id': r['id'],
                            'subject_name': r['subject_name'],
                            'subject_code': r['subject_code'],
                        }
                        for r in sort_rows
                    ]
        except Exception as e:
            print(f"Error fetching academic levels: {e}")
        finally:
            connection.close()
    
    return render_template('dashboards/classes_subjects.html',
                         academic_levels=academic_levels,
                         role=user_role)


@app.route('/dashboard/employee/classes-subjects/level/<int:level_id>')
@login_required
def classes_subjects_level_detail(level_id):
    """Academic level detail: all allocated subjects and assigned teachers."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    connection = get_db_connection()
    level = None
    level_subjects = []
    total_allocated_teachers = 0

    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description
                    FROM academic_levels
                    WHERE id = %s AND COALESCE(level_status, 'active') = 'active'
                    LIMIT 1
                """, (level_id,))
                row = cursor.fetchone()
                if not row:
                    flash('Academic level not found or inactive.', 'error')
                    return redirect(employee_dash_url('classes-subjects'))

                level = {
                    'id': row.get('id') if isinstance(row, dict) else row[0],
                    'level_category': row.get('level_category', '') if isinstance(row, dict) else (row[1] if len(row) > 1 else ''),
                    'level_name': row.get('level_name', '') if isinstance(row, dict) else (row[2] if len(row) > 2 else ''),
                    'level_description': row.get('level_description', '') if isinstance(row, dict) else (row[3] if len(row) > 3 else ''),
                }

                cursor.execute("""
                    SELECT sal.subject_id,
                           s.subject_name,
                           s.subject_code,
                           COALESCE(s.status, 'active') AS subject_status
                    FROM subject_academic_levels sal
                    INNER JOIN subjects s ON sal.subject_id = s.id
                    WHERE sal.academic_level_id = %s
                    ORDER BY s.subject_name ASC
                """, (level_id,))

                subjects_map = {}
                for srow in cursor.fetchall() or []:
                    subject_status = (srow.get('subject_status', 'active') if isinstance(srow, dict) else (srow[3] if len(srow) > 3 else 'active'))
                    if str(subject_status or '').lower() == 'inactive':
                        continue
                    subject_id = srow.get('subject_id') if isinstance(srow, dict) else srow[0]
                    if subject_id is None:
                        continue
                    subjects_map[subject_id] = {
                        'subject_id': subject_id,
                        'subject_name': (srow.get('subject_name', '') if isinstance(srow, dict) else (srow[1] if len(srow) > 1 else '')) or 'Subject',
                        'subject_code': (srow.get('subject_code', '') if isinstance(srow, dict) else (srow[2] if len(srow) > 2 else '')) or '',
                        'teachers': [],
                    }

                cursor.execute("""
                    SELECT DISTINCT tsa.subject_id, s.subject_name, s.subject_code, COALESCE(s.status, 'active') AS subject_status
                    FROM teacher_subject_assignments tsa
                    LEFT JOIN subjects s ON tsa.subject_id = s.id
                    WHERE tsa.academic_level_id = %s
                    ORDER BY s.subject_name ASC
                """, (level_id,))
                for tsub in cursor.fetchall() or []:
                    subject_status = (tsub.get('subject_status', 'active') if isinstance(tsub, dict) else (tsub[3] if len(tsub) > 3 else 'active'))
                    if str(subject_status or '').lower() == 'inactive':
                        continue
                    subject_id = tsub.get('subject_id') if isinstance(tsub, dict) else tsub[0]
                    if subject_id is None or subject_id in subjects_map:
                        continue
                    subjects_map[subject_id] = {
                        'subject_id': subject_id,
                        'subject_name': (tsub.get('subject_name', '') if isinstance(tsub, dict) else (tsub[1] if len(tsub) > 1 else '')) or 'Subject',
                        'subject_code': (tsub.get('subject_code', '') if isinstance(tsub, dict) else (tsub[2] if len(tsub) > 2 else '')) or '',
                        'teachers': [],
                    }

                cursor.execute(f"""
                    SELECT tsa.subject_id, e.id AS teacher_id, e.full_name AS teacher_name,
                           {_employee_staff_identity_sql('e')} AS teacher_employee_id
                    FROM teacher_subject_assignments tsa
                    LEFT JOIN employees e ON tsa.teacher_id = e.id
                    WHERE tsa.academic_level_id = %s
                    ORDER BY tsa.subject_id ASC, e.full_name ASC
                """, (level_id,))
                for trow in cursor.fetchall() or []:
                    subject_id = trow.get('subject_id') if isinstance(trow, dict) else trow[0]
                    if subject_id is None or subject_id not in subjects_map:
                        continue
                    teacher_id = trow.get('teacher_id') if isinstance(trow, dict) else (trow[1] if len(trow) > 1 else None)
                    teacher_name = (trow.get('teacher_name', '') if isinstance(trow, dict) else (trow[2] if len(trow) > 2 else '')) or ''
                    teacher_employee_id = (trow.get('teacher_employee_id', '') if isinstance(trow, dict) else (trow[3] if len(trow) > 3 else '')) or ''
                    if teacher_id is None and not teacher_name:
                        continue

                    existing_ids = {x.get('teacher_id') for x in subjects_map[subject_id]['teachers']}
                    if teacher_id in existing_ids:
                        continue

                    subjects_map[subject_id]['teachers'].append({
                        'teacher_id': teacher_id,
                        'teacher_name': teacher_name or 'Teacher',
                        'teacher_employee_id': teacher_employee_id,
                    })

                if subjects_map:
                    ensure_subject_exam_display_order_columns(cursor)
                    ph = ','.join(['%s'] * len(subjects_map))
                    cursor.execute(
                        f"SELECT id, exam_display_order FROM subjects WHERE id IN ({ph})",
                        tuple(subjects_map.keys()),
                    )
                    edo_map = {}
                    for er in cursor.fetchall() or []:
                        eid = er.get('id') if isinstance(er, dict) else er[0]
                        if eid is not None:
                            edo_map[int(eid)] = er.get('exam_display_order') if isinstance(er, dict) else (er[1] if len(er) > 1 else None)
                    bridge = []
                    for sid, val in subjects_map.items():
                        bridge.append(
                            {
                                'id': int(sid),
                                'subject_name': val['subject_name'],
                                'subject_code': val['subject_code'],
                                'exam_display_order': edo_map.get(int(sid)),
                                'teachers': val['teachers'],
                            }
                        )
                    sort_subjects_list_for_exam_columns(cursor, bridge)
                    level_subjects = [
                        {
                            'subject_id': b['id'],
                            'subject_name': b['subject_name'],
                            'subject_code': b['subject_code'],
                            'teachers': b['teachers'],
                        }
                        for b in bridge
                    ]
                else:
                    level_subjects = []
                total_allocated_teachers = sum(len(item.get('teachers') or []) for item in level_subjects)
        except Exception as e:
            print(f"Error loading classes-subjects level detail: {e}")
            import traceback
            traceback.print_exc()
            flash('Could not load level allocations right now.', 'error')
            return redirect(employee_dash_url('classes-subjects'))
        finally:
            connection.close()

    return render_template(
        'dashboards/classes_subjects_level_detail.html',
        role=user_role,
        level=level,
        level_subjects=level_subjects,
        total_allocated_teachers=total_allocated_teachers,
    )


def _subject_allocated_to_academic_category(cursor, subject_id, academic_category):
    """True if subject is allocated to any active academic level whose level_category matches (trim, case-insensitive)."""
    try:
        sid = int(subject_id)
    except (TypeError, ValueError):
        return False
    cat = (academic_category or '').strip().upper()
    if not cat:
        return False
    try:
        cursor.execute(
            """
            SELECT 1 FROM subject_academic_levels sal
            INNER JOIN academic_levels al ON al.id = sal.academic_level_id
                AND COALESCE(al.level_status, 'active') = 'active'
            WHERE sal.subject_id = %s
              AND UPPER(TRIM(al.level_category)) = %s
            LIMIT 1
            """,
            (sid, cat),
        )
        if cursor.fetchone():
            return True
        cursor.execute(
            """
            SELECT 1 FROM teacher_subject_assignments tsa
            INNER JOIN academic_levels al ON al.id = tsa.academic_level_id
                AND COALESCE(al.level_status, 'active') = 'active'
            WHERE tsa.subject_id = %s
              AND UPPER(TRIM(al.level_category)) = %s
            LIMIT 1
            """,
            (sid, cat),
        )
        return bool(cursor.fetchone())
    except Exception as e:
        print(f"_subject_allocated_to_academic_category: {e}")
        return False


def _library_subjects_by_academic_category(cursor):
    """
    Map UPPER(TRIM(level_category)) -> list of {id, subject_name, subject_code}
    from subject_academic_levels and teacher_subject_assignments (deduplicated).
    """
    from collections import defaultdict

    merged = defaultdict(dict)
    queries = (
        """
        SELECT UPPER(TRIM(al.level_category)) AS acad_cat, s.id AS subject_id, s.subject_name, s.subject_code
        FROM subject_academic_levels sal
        INNER JOIN academic_levels al ON al.id = sal.academic_level_id
            AND COALESCE(al.level_status, 'active') = 'active'
        INNER JOIN subjects s ON s.id = sal.subject_id
            AND COALESCE(s.status, 'active') = 'active'
        WHERE TRIM(COALESCE(al.level_category, '')) <> ''
        """,
        """
        SELECT UPPER(TRIM(al.level_category)) AS acad_cat, s.id AS subject_id, s.subject_name, s.subject_code
        FROM teacher_subject_assignments tsa
        INNER JOIN academic_levels al ON al.id = tsa.academic_level_id
            AND COALESCE(al.level_status, 'active') = 'active'
        INNER JOIN subjects s ON s.id = tsa.subject_id
            AND COALESCE(s.status, 'active') = 'active'
        WHERE TRIM(COALESCE(al.level_category, '')) <> ''
        """,
    )
    for sql in queries:
        try:
            cursor.execute(sql)
            for row in cursor.fetchall() or []:
                if isinstance(row, dict):
                    cat = row.get('acad_cat') or ''
                    sid = row.get('subject_id')
                    name = row.get('subject_name') or ''
                    code = row.get('subject_code') or ''
                else:
                    cat = (row[0] if len(row) > 0 else '') or ''
                    sid = row[1] if len(row) > 1 else None
                    name = (row[2] if len(row) > 2 else '') or ''
                    code = (row[3] if len(row) > 3 else '') or ''
                cat = (cat or '').strip().upper()
                if not cat or sid is None:
                    continue
                try:
                    sid_i = int(sid)
                except (TypeError, ValueError):
                    continue
                merged[cat][sid_i] = {
                    'id': sid_i,
                    'subject_name': name,
                    'subject_code': code or '',
                }
        except Exception as e:
            print(f"_library_subjects_by_academic_category: {e}")

    out = {}
    for cat_key, submap in merged.items():
        out[cat_key] = sorted(
            submap.values(),
            key=lambda x: (x.get('subject_name') or '').lower(),
        )
    return out


