@app.route('/system-settings/general', methods=['POST'])
@login_required
def update_general_settings():
    """Persist maintenance mode, admission registration gate, language, and timezone."""
    user_role = session.get('role', '').lower()
    if user_role != 'technician':
        flash('You do not have permission to perform this action.', 'error')
        return redirect(url_for('system_settings'))

    maintenance_mode = 1 if '1' in request.form.getlist('maintenance_mode') else 0
    allow_registration = 1 if '1' in request.form.getlist('allow_registration') else 0
    default_language = (request.form.get('default_language') or 'en').strip().lower()[:10]
    timezone_val = (request.form.get('timezone') or 'Africa/Nairobi').strip()[:64]
    default_theme_mode = (request.form.get('default_theme_mode') or 'dark').strip().lower()

    if default_language not in ('en', 'es', 'fr', 'sw'):
        default_language = 'en'
    allowed_tz = frozenset({
        'UTC', 'Africa/Nairobi', 'Europe/London', 'America/New_York', 'Asia/Dubai',
    })
    if timezone_val not in allowed_tz:
        timezone_val = 'Africa/Nairobi'
    if default_theme_mode not in ('light', 'dark'):
        default_theme_mode = 'dark'

    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_school_general_settings_columns(cursor)
                cursor.execute("SELECT id FROM school_settings ORDER BY id DESC LIMIT 1")
                row = cursor.fetchone()
                if not row:
                    flash('School settings row is missing. Save school profile first.', 'error')
                    return redirect(url_for('system_settings') + '#general-settings')
                school_id = row['id'] if isinstance(row, dict) else row[0]
                cursor.execute(
                    """
                    UPDATE school_settings
                    SET maintenance_mode = %s, allow_registration = %s,
                        default_language = %s, timezone = %s, default_theme_mode = %s
                    WHERE id = %s
                    """,
                    (maintenance_mode, allow_registration, default_language, timezone_val, default_theme_mode, school_id),
                )
                connection.commit()
                invalidate_school_settings_cache()
                flash('General settings saved successfully.', 'success')
        except Exception as e:
            try:
                connection.rollback()
            except Exception:
                pass
            print(f"update_general_settings: {e}")
            flash('Could not save general settings. If columns are missing, restart the app once to run migrations.', 'error')
        finally:
            connection.close()
    else:
        flash('Database connection error. Please try again later.', 'error')

    return redirect(url_for('system_settings') + '#general-settings')


# Theme / Colors Update Route
@app.route('/system-settings/theme', methods=['POST'])
@login_required
def update_theme():
    """Update theme colors and font - applies site-wide"""
    user_role = session.get('role', '').lower()
    if user_role != 'technician' and not check_permission_or_role('system_settings', allowed_roles=['accountant']):
        flash('You do not have permission to perform this action.', 'error')
        return redirect(url_for('system_settings'))

    primary_color = (request.form.get('primary_color') or '#800020').strip()
    secondary_color = (request.form.get('secondary_color') or '#A00030').strip()
    accent_color = (request.form.get('accent_color') or '#5C0014').strip()
    font_family = normalize_portal_font_family(request.form.get('font_family'))

    # Validate hex colors
    import re
    hex_pattern = re.compile(r'^#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})$')
    if not hex_pattern.match(primary_color): primary_color = '#800020'
    if not hex_pattern.match(secondary_color): secondary_color = '#A00030'
    if not hex_pattern.match(accent_color): accent_color = '#5C0014'

    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("SELECT id FROM school_settings ORDER BY id DESC LIMIT 1")
                row = cursor.fetchone()
                if row:
                    school_id = row['id'] if isinstance(row, dict) else row[0]
                    cursor.execute("""
                        UPDATE school_settings
                        SET primary_color = %s, secondary_color = %s, accent_color = %s, font_family = %s
                        WHERE id = %s
                    """, (primary_color, secondary_color, accent_color, font_family, school_id))
                else:
                    cursor.execute("""
                        INSERT INTO school_settings (school_name, primary_color, secondary_color, accent_color, font_family)
                        VALUES ('Modern School', %s, %s, %s, %s)
                    """, (primary_color, secondary_color, accent_color, font_family))
                connection.commit()
                invalidate_school_settings_cache()
            flash('Theme updated successfully! Changes apply across the entire site.', 'success')
        except Exception as e:
            if connection:
                try: connection.rollback()
                except: pass
            flash(f'Error saving theme: {str(e)}', 'error')
        finally:
            connection.close()
    else:
        flash('Database connection error.', 'error')

    return redirect(url_for('system_settings') + '#theme-colors')

