@app.route('/system-settings/term/<int:term_id>/toggle-lock', methods=['POST'])
@login_required
def toggle_term_lock(term_id):
    """Toggle term lock/unlock status"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Allow technicians and accountants
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_technician = user_role == 'technician'
    
    if not (is_technician or is_accountant):
        return jsonify({'success': False, 'message': 'Permission denied.'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Get current lock status
            cursor.execute("SELECT is_locked FROM terms WHERE id = %s", (term_id,))
            term_result = cursor.fetchone()
            if not term_result:
                return jsonify({'success': False, 'message': 'Term not found.'}), 404
            
            current_locked = term_result.get('is_locked') if isinstance(term_result, dict) else term_result[0]
            new_locked = not current_locked
            
            # Update lock status
            if new_locked:
                cursor.execute("""
                    UPDATE terms 
                    SET is_locked = TRUE, locked_at = NOW() 
                    WHERE id = %s
                """, (term_id,))
                message = 'Term locked successfully!'
            else:
                cursor.execute("""
                    UPDATE terms 
                    SET is_locked = FALSE, locked_at = NULL 
                    WHERE id = %s
                """, (term_id,))
                message = 'Term unlocked successfully!'
            
            connection.commit()
            return jsonify({
                'success': True, 
                'message': message,
                'is_locked': new_locked
            })
    except Exception as e:
        print(f"Error toggling term lock: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'An error occurred while updating the term lock status.'}), 500
    finally:
        connection.close()


def _ensure_db_schema():
    """Check DB health and auto-create missing tables. Runs on every app load (local + hosted)."""
    try:
        from db_health import check_and_heal
        ok, msg = check_and_heal()
        if ok:
            print(f"[DB] {msg}")
        else:
            print(f"[DB] Warning: {msg} - run: python update_db.py")
    except Exception as e:
        print(f"[DB] Check failed: {e}")
        try:
            if init_db():
                print("[DB] Tables created/verified (fallback)")
            from migrations.migration_manager import run_all_migrations
            run_all_migrations()
        except Exception as e2:
            print(f"[DB] Fallback failed: {e2}")


# /<role>/… → /dashboard/… ; /dashboard/<role-slug>/… → /dashboard/employee/…
app.wsgi_app = RootRolePathRewriteMiddleware(DashboardRolePathRewriteMiddleware(app.wsgi_app))

# Apply schema and migrations when app is loaded (so git pull + restart updates DB)
_ensure_db_schema()


@app.cli.command('update-db')
def flask_update_db():
    """Create/update DB tables and run migrations. Run after git pull."""
    print("Updating database...")
    try:
        if init_db():
            print("Tables OK")
        from migrations.migration_manager import run_all_migrations
        run_all_migrations()
        print("Done. Database is up to date.")
    except Exception as e:
        print(f"Error: {e}")
        raise


